#[derive(Clone, Copy)]
struct Migration {
    version: i64,
    name: &'static str,
    apply: fn(&Connection) -> Result<()>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct WorkspaceSchemaMigrationStep {
    pub version: i64,
    pub name: String,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct WorkspaceSchemaMigrationPlan {
    pub current_schema_version: i64,
    pub target_schema_version: i64,
    pub migrations: Vec<WorkspaceSchemaMigrationStep>,
}

impl WorkspaceSchemaMigrationPlan {
    pub fn migration_required(&self) -> bool {
        !self.migrations.is_empty()
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct WorkspaceRecord {
    pub workspace_id: String,
    /// Existing user Account that owns this Workspace. Owner transfer is a separate
    /// audited domain operation; ordinary upserts must preserve this identity.
    pub owner_account_id: String,
    pub display_name: String,
    pub state: String,
    pub created_at: String,
    pub updated_at: String,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct WorkspaceMemorySettingsRecord {
    pub workspace_id: String,
    pub language: String,
    pub created_at: String,
    pub updated_at: String,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct WorkerCreateReservation {
    pub worker_id: WorkerId,
    pub create_fingerprint: String,
    pub memory_settings: manifest::WorkspaceMemorySettingsSnapshot,
    pub singleton: Option<WorkerSingletonLease>,
}

/// Durable lease proving which Worker generation owns one opaque Workspace singleton key.
///
/// The current owner lives in `worker_singleton_owners`; matching lease data remains on every
/// create reservation so a displaced generation can be fenced from later restore attempts.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct WorkerSingletonLease {
    pub key: String,
    pub generation: u64,
    pub worker: RuntimeWorkerRef,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct RepositoryRecord {
    pub workspace_id: String,
    pub repository_id: String,
    pub repository_key: String,
    pub kind: String,
    pub provider: Option<String>,
    pub source: RepositorySource,
    pub default_ref: Option<String>,
    pub source_fingerprint: String,
    pub observed_status: RepositoryObservedStatus,
    pub observed_at: Option<String>,
    pub created_at: String,
    pub updated_at: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RepositoryInsertOutcome {
    Created,
    Existing(RepositoryRecord),
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
