    fn is_hosting_admin(&self, user_id: &str) -> Result<bool> {
        self.with_conn(|conn| {
            if activation::pending(conn, user_id)? {
                return Ok(false);
            }
            conn.query_row(
                "SELECT EXISTS(SELECT 1 FROM hosting_administrators h JOIN users u ON u.user_id = h.user_id WHERE u.user_id = ?1)",
                [user_id], |row| row.get(0),
            ).map_err(Error::from)
        })
    }

    fn hosting_self_registration_enabled(&self) -> Result<bool> {
        self.with_conn(|conn| {
            conn.query_row(
                "SELECT self_registration_enabled FROM hosting_settings WHERE singleton = 1",
                [],
                |row| row.get(0),
            )
            .map_err(Error::from)
        })
    }

    fn set_hosting_self_registration_enabled(
        &self,
        actor: &server_api::RequestActor,
        enabled: bool,
    ) -> Result<()> {
        self.with_immediate_transaction(|tx| {
            activation::require_active(tx, &actor.user_id)?;
            let allowed: bool = tx.query_row(
                "SELECT EXISTS(SELECT 1 FROM hosting_administrators h JOIN users u ON u.user_id = h.user_id WHERE u.user_id = ?1 AND u.account_id = ?2)",
                params![actor.user_id, actor.account_id], |row| row.get(0),
            )?;
            if !allowed {
                return Err(Error::WorkspacePermissionDenied(
                    "hosting_admin_required: a live hosting administrator is required".into(),
                ));
            }
            if tx.execute(
                "UPDATE hosting_settings SET self_registration_enabled = ?1 WHERE singleton = 1",
                [enabled],
            )? != 1 {
                return Err(Error::Store("hosting settings singleton is missing".into()));
            }
            Ok(())
        })
    }

    fn register_verified_passkey_with_result(
        &self,
        target: &PasskeyRegistrationTarget,
        credential: &PasskeyCredentialRecord,
        addition_challenge_id: Option<&str>,
    ) -> Result<()> {
        self.with_immediate_transaction(|tx| {
            let user = match target {
                PasskeyRegistrationTarget::NewAccount { user } => {
                    let enabled: bool = tx.query_row(
                        "SELECT self_registration_enabled FROM hosting_settings WHERE singleton = 1",
                        [], |row| row.get(0),
                    )?;
                    if !enabled {
                        return Err(Error::WorkspacePermissionDenied(
                            "self_registration_disabled: hosting self-registration is disabled".into(),
                        ));
                    }
                    let occupied: bool = tx.query_row(
                        "SELECT EXISTS(SELECT 1 FROM accounts WHERE kind = 'user' AND handle = ?1) OR EXISTS(SELECT 1 FROM users WHERE handle = ?1)",
                        params![user.handle], |row| row.get(0),
                    )?;
                    if occupied {
                        return Err(crate::auth::auth_error("auth_handle_exists", "handle is already registered"));
                    }
                    tx.execute(
                        "INSERT INTO accounts (account_id, kind, handle, display_name, created_at, updated_at) VALUES (?1, 'user', ?2, ?3, ?4, ?5)",
                        params![user.account_id, user.handle, user.display_name, user.created_at, user.updated_at],
                    )?;
                    tx.execute(
                        "INSERT INTO users (user_id, account_id, handle, display_name, created_at, updated_at) VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
                        params![user.user_id, user.account_id, user.handle, user.display_name, user.created_at, user.updated_at],
                    )?;
                    user
                }
                PasskeyRegistrationTarget::Activation { user, issuance_id } => {
                    activation::require_pending_target(tx, user, Some(issuance_id))?;
                    user
                }
                PasskeyRegistrationTarget::Addition { user, authentication } => {
                    activation::require_active(tx, &user.user_id)?;
                    let current = tx.query_row(
                        user_select_sql("WHERE user_id = ?1 AND account_id = ?2").as_str(),
                        params![user.user_id, user.account_id], read_user_record,
                    ).optional()?;
                    if current.is_none() {
                        return Err(crate::auth::auth_error("passkey_target_mismatch", "addition target no longer exists"));
                    }
                    let expires_at: Option<Option<String>> = match authentication {
                        PasskeyAuthenticationBinding::BrowserSession(hash) => tx.query_row(
                            "SELECT expires_at FROM browser_sessions WHERE token_hash = ?1 AND user_id = ?2 AND revoked_at IS NULL",
                            params![hash, user.user_id], |row| row.get(0),
                        ).optional()?,
                        PasskeyAuthenticationBinding::ApiToken(hash) => tx.query_row(
                            "SELECT expires_at FROM api_tokens WHERE token_hash = ?1 AND user_id = ?2 AND revoked_at IS NULL",
                            params![hash, user.user_id], |row| row.get(0),
                        ).optional()?,
                    };
                    if !expires_at.is_some_and(|expiry| expiry.as_deref().is_none_or(|value| !crate::auth::is_expired(value))) {
                        return Err(crate::auth::auth_error("auth_required", "addition credential has expired or been revoked"));
                    }
                    user
                }
            };
            if user.user_id != credential.user_id {
                return Err(crate::auth::auth_error("passkey_target_mismatch", "credential does not match enrollment target"));
            }
            tx.execute(
                "INSERT INTO passkey_credentials (credential_id, user_id, public_key_cose, transports_json, sign_count, created_at, last_used_at) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)",
                params![credential.credential_id, credential.user_id, credential.public_key_cose, credential.transports_json, credential.sign_count, credential.created_at, credential.last_used_at],
            )?;
            if let Some(challenge_id) = addition_challenge_id {
                let PasskeyRegistrationTarget::Addition { user, authentication } = target else {
                    return Err(crate::auth::auth_error("passkey_target_mismatch", "receipt requires an addition"));
                };
                tx.execute(
                    "INSERT INTO passkey_addition_receipts(challenge_id, credential_id, user_id, authentication_reference) VALUES (?1, ?2, ?3, ?4)",
                    params![challenge_id, credential.credential_id, user.user_id, authentication.reference()],
                )?;
            }
            if let PasskeyRegistrationTarget::Activation { user, issuance_id } = target {
                if tx.execute("DELETE FROM user_activations WHERE user_id=?1 AND issuance_id=?2", params![user.user_id, issuance_id])? != 1 {
                    return Err(crate::auth::auth_error("activation_code_invalid", "activation issuance no longer exists"));
                }
            }
            Ok(())
        })
    }

    fn list_passkey_summaries(&self, user_id: &str) -> Result<Vec<server_api::PasskeySummary>> {
        self.with_conn(|conn| {
            let mut stmt = conn.prepare(
                "SELECT m.key_reference, c.created_at, c.last_used_at, m.normal_login_verified_at
                 FROM passkey_credentials c JOIN passkey_metadata m USING(credential_id)
                 WHERE c.user_id = ?1 ORDER BY c.created_at, m.key_reference",
            )?;
            let rows = stmt.query_map([user_id], read_passkey_summary)?;
            rows.collect::<std::result::Result<Vec<_>, _>>()
                .map_err(Error::from)
        })
    }

    fn read_passkey_addition_result(
        &self,
        user_id: &str,
        original_authentication_reference: &str,
        challenge_id: &str,
    ) -> Result<Option<server_api::PasskeySummary>> {
        self.with_conn(|conn| {
            // Current authenticated ownership authorizes reading. The original
            // binding reference identifies the saved operation, not the current
            // session: Set-Cookie may have arrived even if its body was lost.
            let result = conn.query_row(
                "SELECT m.key_reference, c.created_at, c.last_used_at, m.normal_login_verified_at, r.authentication_reference
                 FROM passkey_addition_receipts r
                 JOIN passkey_credentials c USING(credential_id)
                 JOIN passkey_metadata m USING(credential_id)
                 WHERE r.challenge_id = ?1 AND r.user_id = ?2 AND c.user_id = ?2",
                params![challenge_id, user_id],
                |row| Ok((read_passkey_summary(row)?, row.get::<_, String>(4)?)),
            ).optional()?;
            match result {
                Some((key, reference)) if reference == original_authentication_reference => Ok(Some(key)),
                Some(_) => Err(crate::auth::auth_error("passkey_result_binding_mismatch", "original operation authentication reference does not match")),
                None => Ok(None),
            }
        })
    }

