fn read_runtime_removal_operation(
    row: &rusqlite::Row<'_>,
) -> rusqlite::Result<RuntimeRemovalOperation> {
    let state_value = row.get::<_, String>(6)?;
    let state = RuntimeRemovalOperationState::parse(&state_value).map_err(|error| {
        rusqlite::Error::FromSqlConversionFailure(
            6,
            rusqlite::types::Type::Text,
            error.to_string().into(),
        )
    })?;
    let expected_binding_id = row.get(4)?;
    let config_digest = row.get(5)?;
    Ok(RuntimeRemovalOperation {
        operation_id: row.get(0)?,
        workspace_id: row.get(1)?,
        runtime_id: row.get(2)?,
        request_fingerprint: row.get(3)?,
        expected_binding_id,
        config_digest,
        state,
        failure_category: row.get(7)?,
        binding_removed: row.get::<_, i64>(8)? != 0,
        runtime_registration_removed: row.get::<_, Option<i64>>(9)?.map(|value| value != 0),
        created_at: row.get(10)?,
        updated_at: row.get(11)?,
        completed_at: row.get(12)?,
    })
}

const RUNTIME_REMOVAL_OPERATION_SELECT: &str = "SELECT operation_id, workspace_id, runtime_id, request_fingerprint, \
            expected_binding_id, config_digest, state, failure_category, \
            binding_removed, runtime_registration_removed, created_at, updated_at, completed_at \
     FROM runtime_removal_operations";

fn load_runtime_removal_operation(
    conn: &Connection,
    operation_id: &str,
) -> Result<Option<RuntimeRemovalOperation>> {
    conn.query_row(
        &format!("{RUNTIME_REMOVAL_OPERATION_SELECT} WHERE operation_id = ?1"),
        params![operation_id],
        read_runtime_removal_operation,
    )
    .optional()
    .map_err(Error::from)
}

fn runtime_removal_preflight(
    conn: &Connection,
    workspace_id: &str,
    runtime_id: &str,
    expected_binding_id: &str,
) -> Result<()> {
    let binding_id = conn
        .query_row(
            "SELECT binding_id FROM workspace_runtime_bindings \
             WHERE workspace_id = ?1 AND runtime_id = ?2",
            params![workspace_id, runtime_id],
            |row| row.get::<_, String>(0),
        )
        .optional()?;
    let Some(binding_id) = binding_id else {
        return Err(Error::RuntimeBindingNotFound {
            runtime_id: runtime_id.to_string(),
        });
    };
    if binding_id != expected_binding_id {
        return Err(Error::RuntimeBindingIdConflict {
            expected: Some(expected_binding_id.to_owned()),
            actual: Some(binding_id),
        });
    }

    let guards = [
        (
            "other_workspace_binding",
            "SELECT EXISTS(SELECT 1 FROM workspace_runtime_bindings \
             WHERE runtime_id = ?1 AND workspace_id <> ?2 AND revoked_at IS NULL)",
        ),
        (
            "active_worker",
            "SELECT EXISTS(SELECT 1 FROM worker_registry WHERE runtime_id = ?1)",
        ),
        (
            "active_worker_assignment",
            "SELECT EXISTS(SELECT 1 FROM ticket_active_worker_assignments WHERE runtime_id = ?1)",
        ),
        (
            "active_workdir",
            "SELECT EXISTS(SELECT 1 FROM workdir_registry WHERE runtime_id = ?1)",
        ),
        (
            "active_workdir_attachment",
            "SELECT EXISTS(SELECT 1 FROM worker_workdir_links \
             WHERE runtime_id = ?1 AND unlinked_at IS NULL)",
        ),
        (
            "worker_create_or_restore",
            "SELECT EXISTS(SELECT 1 FROM worker_create_reservations \
             WHERE runtime_id = ?1 AND state <> 'removed')",
        ),
        (
            "workdir_create",
            "SELECT EXISTS(SELECT 1 FROM workdir_create_operations \
             WHERE resolved_runtime_id = ?1 AND state = 'pending')",
        ),
        (
            "worker_removal",
            "SELECT EXISTS(SELECT 1 FROM worker_removal_operations \
             WHERE runtime_id = ?1 AND state IN ('planned', 'executing', 'failed'))",
        ),
        (
            "workdir_removal",
            "SELECT EXISTS(SELECT 1 FROM workdir_removal_operations \
             WHERE runtime_id = ?1 AND state IN ('pending', 'failed') AND retryable = 1)",
        ),
    ];
    for (category, sql) in guards {
        let blocked = if category == "other_workspace_binding" {
            conn.query_row(sql, params![runtime_id, workspace_id], |row| {
                row.get::<_, bool>(0)
            })?
        } else {
            conn.query_row(sql, params![runtime_id], |row| row.get::<_, bool>(0))?
        };
        if blocked {
            return Err(Error::RuntimeBindingConflict(format!(
                "runtime_removal_{category}_blocked"
            )));
        }
    }
    Ok(())
}

fn read_workspace_runtime_binding(
    row: &rusqlite::Row<'_>,
) -> rusqlite::Result<WorkspaceRuntimeBinding> {
    let authentication_mode = match row.get::<_, String>(7)?.as_str() {
        "legacy_server_issuer" => WorkspaceRuntimeAuthenticationMode::LegacyServerIssuer,
        "workspace_identity" => WorkspaceRuntimeAuthenticationMode::WorkspaceIdentity,
        value => {
            return Err(rusqlite::Error::FromSqlConversionFailure(
                7,
                rusqlite::types::Type::Text,
                format!("unknown Workspace Runtime authentication mode {value}").into(),
            ));
        }
    };
    Ok(WorkspaceRuntimeBinding {
        workspace_id: row.get(0)?,
        runtime_id: row.get(1)?,
        display_name: row.get(2)?,
        base_url: row.get(3)?,
        public_key: row.get(4)?,
        public_key_fingerprint: row.get(5)?,
        binding_id: row.get(6)?,
        authentication_mode,
        created_at: row.get(8)?,
        updated_at: row.get(9)?,
        revoked_at: row.get(10)?,
    })
}

fn validate_identifier(field: &str, value: &str) -> Result<()> {
    if value.trim().is_empty() || value.trim() != value {
        return Err(Error::InvalidInput(format!(
            "{field} must be non-empty and must not contain surrounding whitespace"
        )));
    }
    Ok(())
}

fn validate_non_empty(field: &str, value: &str) -> Result<()> {
    if value.trim().is_empty() {
        return Err(Error::InvalidInput(format!("{field} must not be empty")));
    }
    Ok(())
}

fn validate_runtime_base_url(base_url: &str) -> Result<()> {
    let base_url = base_url.trim();
    if base_url.starts_with("http://")
        || base_url.starts_with("https://")
        || base_url == "in-process://embedded"
    {
        Ok(())
    } else {
        Err(Error::InvalidInput(
            "Runtime base_url must be an absolute http/https URL or the embedded Runtime endpoint"
                .to_string(),
        ))
    }
}

pub fn normalize_runtime_public_key(public_key: &str) -> Result<(String, String)> {
    let bytes = worker_runtime::auth::decode_public_key(public_key)
        .map_err(|err| Error::InvalidInput(format!("invalid Runtime public key: {err}")))?;
    let canonical = worker_runtime::auth::encode_public_key(&bytes);
    let digest = Sha256::digest(&bytes)
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    let fingerprint = format!("sha256:{digest}");
    Ok((canonical, fingerprint))
}

fn normalize_workspace_runtime_binding_key(record: &mut WorkspaceRuntimeBinding) -> Result<()> {
    let (canonical, fingerprint) = normalize_runtime_public_key(&record.public_key)?;
    if !record.public_key_fingerprint.is_empty() && record.public_key_fingerprint != fingerprint {
        return Err(Error::InvalidInput(
            "Runtime public key fingerprint does not match the public key".into(),
        ));
    }
    record.public_key = canonical;
    record.public_key_fingerprint = fingerprint;
    #[cfg(not(test))]
    if record.authentication_mode == WorkspaceRuntimeAuthenticationMode::LegacyServerIssuer
        && record.runtime_id != crate::hosts::EMBEDDED_RUNTIME_ID
    {
        return Err(Error::InvalidInput(
            "legacy Server issuer authentication is reserved for the embedded Runtime".into(),
        ));
    }
    if let Some(revoked_at) = &record.revoked_at {
        validate_non_empty("revoked_at", revoked_at)?;
    }
    Ok(())
}

fn map_runtime_binding_write_error(err: rusqlite::Error) -> Error {
    if matches!(
        &err,
        rusqlite::Error::SqliteFailure(error, _)
            if error.code == rusqlite::ErrorCode::ConstraintViolation
    ) {
        Error::RuntimeBindingConflict(
            "the Runtime id or public key fingerprint is already bound in this Workspace".into(),
        )
    } else {
        Error::from(err)
    }
}

