// The receipt/disposition commit precedes physical cleanup. An error here is
// safely retried with the same expected digest/reason, not a new execution.
fn reclaim_backend_job_input_storage(conn: &Connection) -> Result<()> {
    conn.execute_batch("PRAGMA secure_delete=ON; VACUUM;")?;
    let busy: i64 = conn.query_row("PRAGMA wal_checkpoint(TRUNCATE)", [], |r| r.get(0))?;
    if busy != 0 {
        return Err(Error::Store(
            "Backend Job input retired; SQLite body cleanup blocked by a reader, retry retirement"
                .into(),
        ));
    }
    Ok(())
}

fn backend_job_deadline(now: &str, timeout_seconds: u32) -> Result<String> {
    let now = chrono::DateTime::parse_from_rfc3339(now)
        .map_err(|error| Error::InvalidInput(format!("invalid Backend Job timestamp: {error}")))?;
    Ok((now + chrono::Duration::seconds(i64::from(timeout_seconds))).to_rfc3339())
}

fn backend_job_has_unfinished_cleanup(
    conn: &Connection,
    workspace_id: &str,
    job_id: &str,
) -> Result<bool> {
    Ok(conn.query_row(
        "SELECT EXISTS(SELECT 1 FROM backend_job_attempts WHERE workspace_id = ?1 AND job_id = ?2
         AND worker_cleanup_state IS NOT 'completed')",
        params![workspace_id, job_id],
        |row| row.get(0),
    )?)
}

fn read_active_backend_job_for_resource(
    conn: &Connection,
    workspace_id: &str,
    resource_key: &str,
) -> Result<Option<BackendJobRecord>> {
    // Resource ownership is computed from common Job/attempt authority. Unknown
    // effects block even after Worker removal; cleanup is not outcome resolution.
    let id = conn.query_row(
        "SELECT job.job_id FROM backend_jobs job WHERE job.workspace_id = ?1 AND job.resource_key = ?2
         AND (job.state IN ('pending', 'unknown') OR EXISTS (
             SELECT 1 FROM backend_job_attempts attempt WHERE attempt.workspace_id = job.workspace_id
             AND attempt.job_id = job.job_id
             AND attempt.worker_cleanup_state IS NOT 'completed'))
         ORDER BY job.created_at, job.job_id LIMIT 1",
        params![workspace_id, resource_key],
        |row| row.get::<_, String>(0),
    ).optional()?;
    id.map(|id| read_backend_job(conn, workspace_id, &id))
        .transpose()
        .map(Option::flatten)
}

/// Purge authority comes from the immutable request and exact attempt/Worker/input
/// binding, never from a profile or purpose string.
pub(crate) fn terminal_journal_job_worker(
    conn: &Connection,
    workspace: &str,
    worker: &RuntimeWorkerRef,
) -> Result<bool> {
    let identity: Option<(String, String)> = conn.query_row(
        "SELECT job_id, attempt_id FROM backend_job_attempts WHERE workspace_id=?1 AND runtime_id=?2 AND worker_id=?3",
        params![workspace, worker.runtime_id, worker.worker_id], |r| Ok((r.get(0)?, r.get(1)?)),
    ).optional()?;
    let Some((job_id, attempt_id)) = identity else {
        return Ok(false);
    };
    let job = read_backend_job(conn, workspace, &job_id)?
        .ok_or_else(|| Error::Store("Journal cleanup Job missing".into()))?;
    let attempt = read_backend_job_attempt(conn, workspace, &job_id, &attempt_id)?
        .ok_or_else(|| Error::Store("Journal cleanup attempt missing".into()))?;
    job.request.validate()?;
    Ok(job.request.grants.subjektiv_journal.is_some()
        && attempt.state.terminal()
        && attempt.worker.as_ref() == Some(worker)
        && attempt.input_digest == job.input_digest)
}

fn read_backend_job(
    conn: &Connection,
    workspace_id: &str,
    job_id: &str,
) -> Result<Option<BackendJobRecord>> {
    let row = conn.query_row(
        "SELECT request_json, intent_fingerprint, state, current_attempt, result_json, result_digest, failure_category, failure_detail, created_at, updated_at, completed_at, input_digest, input_disposition FROM backend_jobs WHERE workspace_id = ?1 AND job_id = ?2",
        params![workspace_id, job_id],
        |row| Ok((
            row.get::<_, String>(0)?, row.get::<_, String>(1)?, row.get::<_, String>(2)?,
            row.get::<_, i64>(3)?, row.get::<_, Option<String>>(4)?, row.get::<_, Option<String>>(5)?,
            row.get::<_, Option<String>>(6)?, row.get::<_, Option<String>>(7)?, row.get::<_, String>(8)?,
            row.get::<_, String>(9)?, row.get::<_, Option<String>>(10)?, row.get::<_, String>(11)?, row.get::<_, String>(12)?,
        )),
    ).optional()?;
    let Some((
        request_json,
        intent_fingerprint,
        state,
        current_attempt,
        result_json,
        result_digest,
        failure_category,
        failure_detail,
        created_at,
        updated_at,
        completed_at,
        input_digest,
        input_disposition,
    )) = row
    else {
        return Ok(None);
    };
    let request_value: serde_json::Value = serde_json::from_str(&request_json)
        .map_err(|error| Error::Store(format!("invalid stored Backend Job request: {error}")))?;
    if request_value.get("input").is_none() {
        return Err(Error::Store(
            "stored Backend Job input field is missing".into(),
        ));
    }
    let request: BackendJobRequest = serde_json::from_value(request_value)
        .map_err(|error| Error::Store(format!("invalid stored Backend Job request: {error}")))?;
    let result = result_json
        .map(|value| serde_json::from_str(&value))
        .transpose()
        .map_err(|error| Error::Store(format!("invalid stored Backend Job result: {error}")))?;
    let current_attempt = u8::try_from(current_attempt)
        .map_err(|_| Error::Store("Backend Job attempt number is out of range".to_string()))?;
    Ok(Some(BackendJobRecord {
        workspace_id: workspace_id.to_string(),
        request,
        intent_fingerprint,
        input_digest,
        input_disposition: serde_json::from_value(serde_json::Value::String(input_disposition))
            .map_err(|e| Error::Store(format!("invalid Job input disposition: {e}")))?,
        state: BackendJobState::parse(&state)?,
        current_attempt,
        result,
        result_digest,
        failure_category,
        failure_detail,
        created_at,
        updated_at,
        completed_at,
    }))
}

fn read_backend_job_attempt(
    conn: &Connection,
    workspace_id: &str,
    job_id: &str,
    attempt_id: &str,
) -> Result<Option<BackendJobAttemptRecord>> {
    let row = conn.query_row(
        "SELECT attempt, input_digest, state, runtime_id, worker_id, runtime_run_id, dispatched_at, deadline_at, result_json, result_digest, failure_category, failure_detail, worker_cleanup_state, worker_cleanup_failure_category, worker_cleanup_failure_detail, worker_cleanup_updated_at, worker_cleanup_completed_at, created_at, updated_at, completed_at FROM backend_job_attempts WHERE workspace_id = ?1 AND job_id = ?2 AND attempt_id = ?3",
        params![workspace_id, job_id, attempt_id],
        |row| Ok((
            row.get::<_, i64>(0)?, row.get::<_, String>(1)?, row.get::<_, String>(2)?,
            row.get::<_, Option<String>>(3)?, row.get::<_, Option<String>>(4)?, row.get::<_, Option<String>>(5)?,
            row.get::<_, Option<String>>(6)?, row.get::<_, String>(7)?, row.get::<_, Option<String>>(8)?,
            row.get::<_, Option<String>>(9)?, row.get::<_, Option<String>>(10)?, row.get::<_, Option<String>>(11)?,
            row.get::<_, Option<String>>(12)?, row.get::<_, Option<String>>(13)?, row.get::<_, Option<String>>(14)?,
            row.get::<_, Option<String>>(15)?, row.get::<_, Option<String>>(16)?, row.get::<_, String>(17)?,
            row.get::<_, String>(18)?, row.get::<_, Option<String>>(19)?,
        )),
    ).optional()?;
    let Some((
        attempt,
        input_digest,
        state,
        runtime_id,
        worker_id,
        runtime_run_id,
        dispatched_at,
        deadline_at,
        result_json,
        result_digest,
        failure_category,
        failure_detail,
        worker_cleanup_state,
        worker_cleanup_failure_category,
        worker_cleanup_failure_detail,
        worker_cleanup_updated_at,
        worker_cleanup_completed_at,
        created_at,
        updated_at,
        completed_at,
    )) = row
    else {
        return Ok(None);
    };
    let worker = match (runtime_id, worker_id) {
        (Some(runtime_id), Some(worker_id)) => Some(RuntimeWorkerRef::new(runtime_id, worker_id)),
        (None, None) => None,
        _ => {
            return Err(Error::Store(
                "Backend Job attempt has a partial Worker binding".to_string(),
            ));
        }
    };
    let result = result_json
        .map(|value| serde_json::from_str(&value))
        .transpose()
        .map_err(|error| {
            Error::Store(format!(
                "invalid stored Backend Job attempt result: {error}"
            ))
        })?;
    let attempt = u8::try_from(attempt)
        .map_err(|_| Error::Store("Backend Job attempt number is out of range".to_string()))?;
    Ok(Some(BackendJobAttemptRecord {
        workspace_id: workspace_id.to_string(),
        job_id: job_id.to_string(),
        attempt_id: attempt_id.to_string(),
        attempt,
        input_digest,
        state: BackendJobAttemptState::parse(&state)?,
        worker,
        runtime_run_id,
        dispatched_at,
        deadline_at,
        result,
        result_digest,
        failure_category,
        failure_detail,
        worker_cleanup_state: worker_cleanup_state
            .as_deref()
            .map(BackendJobWorkerCleanupState::parse)
            .transpose()?,
        worker_cleanup_failure_category,
        worker_cleanup_failure_detail,
        worker_cleanup_updated_at,
        worker_cleanup_completed_at,
        created_at,
        updated_at,
        completed_at,
    }))
}

