fn migrate_job_notifications_v95_to_v96(conn: &Connection) -> Result<()> {
    if current_schema_version(conn)? != 95 {
        return Err(Error::Store(
            "Job notification migration requires schema 95".into(),
        ));
    }
    let foreign_keys: bool = conn.query_row("PRAGMA foreign_keys", [], |r| r.get(0))?;
    let legacy_alter: bool = conn.query_row("PRAGMA legacy_alter_table", [], |r| r.get(0))?;
    conn.execute_batch("PRAGMA foreign_keys=OFF; PRAGMA legacy_alter_table=ON;")?;
    let result = (|| -> Result<()> {
        let tx = rusqlite::Transaction::new_unchecked(conn, TransactionBehavior::Exclusive)?;
        notification_routing::jobs::install(&tx)?;
        let violations: bool = tx.query_row(
            "SELECT EXISTS(SELECT 1 FROM pragma_foreign_key_check)",
            [],
            |r| r.get(0),
        )?;
        if violations {
            return Err(Error::Store(
                "Job notification migration foreign-key violation".into(),
            ));
        }
        tx.execute("INSERT INTO __yoi_schema_migrations(version,name) VALUES(96,'Backend Job common notification routing')",[])?;
        tx.commit()?;
        Ok(())
    })();
    let restore = conn
        .execute_batch(&format!(
            "PRAGMA legacy_alter_table={}; PRAGMA foreign_keys={};",
            i32::from(legacy_alter),
            i32::from(foreign_keys)
        ))
        .map_err(Error::from);
    result.and(restore)
}

fn migrate_business_notifications_v96_to_v97(conn: &Connection) -> Result<()> {
    if current_schema_version(conn)? != 96 {
        return Err(Error::Store(
            "Business notifications migration requires schema 96".into(),
        ));
    }
    // Older Workspace databases may not have opened the MR domain yet. Complete
    // its owner-managed, idempotent migration before composing business triggers.
    // A failed host migration leaves that independent domain upgrade intact.
    merge_request::migrate(conn)?;
    let tx = conn.unchecked_transaction()?;
    notification_routing::install_business_events(&tx)?;
    tx.execute("INSERT INTO __yoi_schema_migrations(version,name) VALUES(97,'MR notifications and authenticated implementation results')", [])?;
    verify_workspace_resource_constraints(&tx)?;
    tx.commit()?;
    Ok(())
}

