fn migrate_schema_103_variants_to_v104(conn: &Connection) -> Result<()> {
    if current_schema_version(conn)? != 103 {
        return Err(Error::Store(
            "Schema convergence migration requires schema 103".into(),
        ));
    }
    verify_schema_history(conn, 103)?;
    let tx = conn.unchecked_transaction()?;
    // Fresh databases on either branch recorded only a schema-103 baseline, so
    // the receipt alone cannot identify which feature needs to be installed.
    // Never rebuild existing metadata or receipts: key references and retired
    // Job input dispositions are already externally observable saved values.
    let passkey_results = table_exists(&tx, "passkey_metadata")?;
    let job_retention = column_exists(&tx, "backend_jobs", "input_disposition")?;
    let identity: String = tx.query_row(
        "SELECT name FROM __yoi_schema_migrations WHERE version=103",
        [],
        |row| row.get(0),
    )?;
    let matches_identity = match identity.as_str() {
        SCHEMA_BASELINE_NAME => passkey_results != job_retention,
        "Passkey metadata and atomic addition results" => passkey_results && !job_retention,
        "Job input retirement independent of immutable receipts" => {
            job_retention && !passkey_results
        }
        _ => false,
    };
    if !matches_identity {
        return Err(Error::Store(
            "Schema-103 features do not match the applied migration identity".into(),
        ));
    }
    if !passkey_results {
        tx.execute_batch(include_str!("passkey_results_schema.sql"))?;
    }
    if !job_retention {
        tx.execute_batch("ALTER TABLE backend_jobs ADD COLUMN input_disposition TEXT NOT NULL DEFAULT 'available' CHECK (input_disposition IN ('available','reclaimed','erased','invalidated'));")?;
        tx.execute_batch(crate::backend_job::INPUT_RETENTION_TRIGGERS)?;
    }
    let objects: i64 = tx.query_row(
        "SELECT count(*) FROM sqlite_schema WHERE
         (type='table' AND name IN ('passkey_metadata','passkey_addition_receipts')) OR
         (type='trigger' AND name IN ('passkey_metadata_insert','backend_job_identity_immutable','backend_job_input_retirement'))",
        [],
        |row| row.get(0),
    )?;
    if objects != 5 {
        return Err(Error::Store("Incomplete schema-103 feature schema".into()));
    }
    verify_workspace_resource_constraints(&tx)?;
    let violations: i64 =
        tx.query_row("SELECT count(*) FROM pragma_foreign_key_check", [], |row| {
            row.get(0)
        })?;
    if violations != 0 {
        return Err(Error::Store(
            "Schema convergence foreign-key violation".into(),
        ));
    }
    tx.execute(
        "INSERT INTO __yoi_schema_migrations(version,name) VALUES(104,?1)",
        ["Converge Passkey results and Job input retention"],
    )?;
    tx.commit()?;
    Ok(())
}

