// Fresh composition uses the posts contract. Retained fixtures pass frozen host
// and component DDL to the shared cross-domain constraint composition below.
fn create_workspace_schema_structure(conn: &Connection) -> Result<()> {
    create_workspace_schema_structure_from_sql(conn, include_str!("latest_schema.sql"), true)?;
    conn.execute_batch(include_str!("activation_schema.sql"))?;
    conn.execute_batch(include_str!("passkey_results_schema.sql"))?;
    conn.execute_batch(crate::plugin_plan::SCHEMA_SQL)?;
    conn.execute_batch(crate::plugin_receipt::SCHEMA_SQL)?;
    conn.execute_batch(crate::plugin_plan::LAUNCH_SCHEMA_SQL)?;
    Ok(())
}

fn create_workspace_schema_structure_from_sql(
    conn: &Connection,
    schema_sql: &str,
    ticket_posts: bool,
) -> Result<()> {
    // The composed Workspace parent FK rebuild must not discard domain-owned
    // case guards. Retain their SQL from the shared fresh Ticket schema.
    let ticket_parent_triggers = conn
        .prepare("SELECT sql FROM sqlite_schema WHERE type = 'trigger' AND tbl_name = 'typed_tickets' ORDER BY name")?
        .query_map([], |row| row.get::<_, String>(0))?
        .collect::<rusqlite::Result<Vec<_>>>()?;

    conn.execute_batch("CREATE TABLE worker_restore_intents (
        workspace_id TEXT NOT NULL, runtime_id TEXT NOT NULL, worker_id TEXT NOT NULL,
        domain_key TEXT NOT NULL, request_id TEXT NOT NULL, expected_token TEXT NOT NULL,
        settled INTEGER NOT NULL CHECK(settled IN (0,1)),
        PRIMARY KEY(workspace_id,runtime_id,worker_id,request_id),
        FOREIGN KEY(workspace_id) REFERENCES workspaces(workspace_id) ON DELETE CASCADE
    );
    CREATE UNIQUE INDEX worker_restore_intent_pending_domain ON worker_restore_intents(workspace_id,runtime_id,worker_id,domain_key) WHERE settled=0;")?;

    conn.execute_batch("DROP TABLE IF EXISTS typed_ticket_targets;")?;
    conn.execute_batch(
        &schema_sql
            .replace(
                "-- Plugin catalog schema is composed by store.rs.",
                include_str!("plugin_catalog_schema.sql"),
            )
            .replace(
                "-- Ticket-owned assignment schema is composed by store.rs.",
                ticket::TICKET_ASSIGNMENT_SCHEMA_SQL,
            )
            .replace(
                "-- Subject deletion schema is composed by store.rs.",
                include_str!("subject_deletion_schema.sql"),
            ),
    )?;
    let composed_sql = r#"
        ALTER TABLE typed_tickets RENAME TO typed_tickets_legacy_v66;
        CREATE TABLE typed_tickets (
            workspace_id TEXT NOT NULL,
            ticket_id TEXT NOT NULL,
            slug TEXT NOT NULL,
            title TEXT NOT NULL,
            status TEXT NOT NULL,
            kind TEXT NOT NULL,
            priority TEXT NOT NULL,
            body TEXT NOT NULL,
            created_at TEXT,
            updated_at TEXT,
            assignee TEXT,
            readiness TEXT,
            workflow_state TEXT NOT NULL,
            workflow_state_explicit INTEGER NOT NULL,
            queued_by TEXT,
            queued_at TEXT,
            resolution TEXT,
            PRIMARY KEY (workspace_id, ticket_id),
            FOREIGN KEY (workspace_id) REFERENCES workspaces(workspace_id) ON DELETE CASCADE
        );
        DROP TABLE typed_tickets_legacy_v66;
        CREATE INDEX idx_typed_tickets_workspace_state_updated
            ON typed_tickets(workspace_id, workflow_state, updated_at DESC, ticket_id);
        CREATE INDEX idx_typed_tickets_workspace_updated
            ON typed_tickets(workspace_id, updated_at DESC, ticket_id);
        CREATE TRIGGER ticket_assignment_ticket_parent_tombstone
            BEFORE DELETE ON typed_tickets
            WHEN EXISTS (
                SELECT 1 FROM ticket_worker_assignments AS assignment
                WHERE assignment.workspace_id = OLD.workspace_id
                  AND assignment.ticket_id = OLD.ticket_id
            )
            BEGIN
                INSERT OR IGNORE INTO ticket_assignment_ticket_tombstones (
                    workspace_id, ticket_id, deleted_at
                ) VALUES (OLD.workspace_id, OLD.ticket_id, CURRENT_TIMESTAMP);
            END;
        CREATE TABLE typed_ticket_targets (
            workspace_id TEXT NOT NULL,
            ticket_id TEXT NOT NULL,
            ordinal INTEGER NOT NULL,
            repository_key TEXT NOT NULL,
            ref_selector TEXT,
            access TEXT NOT NULL CHECK (access IN ('read_only', 'read_write')),
            PRIMARY KEY (workspace_id, ticket_id, ordinal),
            UNIQUE (workspace_id, ticket_id, repository_key),
            FOREIGN KEY (workspace_id, ticket_id)
                REFERENCES typed_tickets(workspace_id, ticket_id) ON DELETE CASCADE,
            FOREIGN KEY (workspace_id, repository_key)
                REFERENCES repositories(workspace_id, repository_key) ON DELETE RESTRICT
        );
        CREATE INDEX typed_ticket_targets_workspace_repository
            ON typed_ticket_targets(workspace_id, repository_key, ticket_id);
        ALTER TABLE worker_workdir_links ADD COLUMN connection_id TEXT NOT NULL DEFAULT '';
        ALTER TABLE worker_workdir_links
            ADD COLUMN capabilities TEXT NOT NULL
            CHECK (capabilities IN (
                'all', 'read_only', 'read_write', 'command_only', 'read_command'
            ));
        "#;
    let composed_sql = if ticket_posts {
        composed_sql.replace("body TEXT NOT NULL,", "created_by TEXT,")
    } else {
        composed_sql.to_string()
    };
    conn.execute_batch(&composed_sql)?;
    install_ticket_case_assignment_work_schema(conn)?;
    for sql in ticket_parent_triggers {
        conn.execute_batch(&sql)?;
    }
    Ok(())
}

fn verify_workspace_resource_constraints(conn: &Connection) -> Result<()> {
    if current_schema_version(conn)? < 39 {
        return Ok(());
    }
    for trigger in [
        "ticket_assignment_ticket_parent_tombstone",
        "ticket_assignment_worker_parent_tombstone_delete",
        "ticket_assignment_worker_parent_tombstone_move",
        "ticket_worker_assignments_validate_insert",
        "ticket_worker_assignments_validate_update",
        "ticket_worker_assignment_events_validate_insert",
        "ticket_assignment_operations_validate_insert",
    ] {
        let exists = conn.query_row(
            "SELECT EXISTS(SELECT 1 FROM sqlite_schema WHERE type = 'trigger' AND name = ?1)",
            [trigger],
            |row| row.get::<_, bool>(0),
        )?;
        if !exists {
            return Err(Error::Store(format!(
                "Workspace resource constraint trigger `{trigger}` is missing"
            )));
        }
    }
    if current_schema_version(conn)? >= 82 {
        for (kind, name) in [
            ("table", "ticket_assignment_work_releases"),
            ("view", "ticket_active_worker_assignments"),
            ("trigger", "ticket_terminal_releases_work"),
            ("trigger", "ticket_terminal_assignment_releases_work_insert"),
            ("trigger", "ticket_terminal_assignment_releases_work_update"),
            ("trigger", "ticket_active_worker_role_insert"),
            ("trigger", "ticket_active_worker_role_update"),
            ("trigger", "ticket_active_worker_principal_insert"),
            ("trigger", "ticket_active_worker_principal_update"),
            ("trigger", "ticket_unfinished_work_blocks_worker_delete"),
            ("trigger", "ticket_unfinished_work_blocks_worker_move"),
        ] {
            let exists: bool = conn.query_row(
                "SELECT EXISTS(SELECT 1 FROM sqlite_schema WHERE type=?1 AND name=?2)",
                params![kind, name],
                |row| row.get(0),
            )?;
            if !exists {
                return Err(Error::Store(format!(
                    "unfinished Ticket work constraint {name} is missing"
                )));
            }
        }
    }
    if current_schema_version(conn)? >= 91 {
        for (name, predicate) in [
            (
                "ticket_active_worker_assignments",
                "ticket.workflow_state = 'open'",
            ),
            (
                "ticket_terminal_releases_work",
                "NEW.workflow_state = 'closed'",
            ),
            (
                "ticket_terminal_assignment_releases_work_insert",
                "workflow_state = 'closed'",
            ),
            (
                "ticket_terminal_assignment_releases_work_update",
                "workflow_state = 'closed'",
            ),
            (
                "ticket_active_worker_role_insert",
                "workflow_state = 'open'",
            ),
            (
                "ticket_active_worker_role_update",
                "workflow_state = 'open'",
            ),
        ] {
            let sql: String = conn.query_row(
                "SELECT sql FROM sqlite_schema WHERE name = ?1",
                [name],
                |row| row.get(0),
            )?;
            if !sql.contains(predicate) || sql.contains("'done'") {
                return Err(Error::Store(format!(
                    "Ticket case constraint {name} does not match schema 91"
                )));
            }
        }
    }
    if current_schema_version(conn)? >= 93 {
        for (kind, name) in [
            ("table", "ticket_assignment_delivery_origins"),
            ("table", "ticket_assignment_deliveries"),
            ("table", "ticket_assignment_delivery_requests"),
            ("table", "ticket_assignment_delivery_acknowledgements"),
            ("table", "ticket_assignment_operation_fences"),
            ("trigger", "ticket_assignment_delivery_origin_insert"),
            ("trigger", "ticket_assignment_delivery_origin_no_update"),
            ("trigger", "ticket_assignment_delivery_origin_no_delete"),
            ("trigger", "ticket_assignment_delivery_payload_no_update"),
            ("trigger", "ticket_assignment_delivery_payload_no_delete"),
            ("trigger", "ticket_assignment_delivery_request_no_update"),
            ("trigger", "ticket_assignment_delivery_request_no_delete"),
            ("trigger", "ticket_assignment_delivery_ack_no_update"),
            ("trigger", "ticket_assignment_delivery_ack_no_delete"),
            ("trigger", "ticket_assignment_operation_fence_no_update"),
            ("trigger", "ticket_assignment_operation_fence_no_delete"),
        ] {
            let present: bool = conn.query_row(
                "SELECT EXISTS(SELECT 1 FROM sqlite_schema WHERE type=?1 AND name=?2)",
                params![kind, name],
                |row| row.get(0),
            )?;
            if !present {
                return Err(Error::Store(format!(
                    "Assignment delivery constraint {name} is missing"
                )));
            }
        }
    }
    if current_schema_version(conn)? >= 94 {
        for (kind, name) in [
            ("table", "ticket_assignment_content_inputs"),
            ("trigger", "ticket_assignment_content_input_no_update"),
            ("trigger", "ticket_assignment_content_input_no_delete"),
            ("trigger", "ticket_assignment_title_input"),
            ("trigger", "ticket_assignment_initial_post_input"),
        ] {
            let present: bool = conn.query_row(
                "SELECT EXISTS(SELECT 1 FROM sqlite_schema WHERE type=?1 AND name=?2)",
                params![kind, name],
                |row| row.get(0),
            )?;
            if !present {
                return Err(Error::Store(format!(
                    "Assignment content input constraint {name} is missing"
                )));
            }
        }
    }
    if current_schema_version(conn)? >= 95 {
        notification_routing::verify(conn)?;
    }
    if current_schema_version(conn)? >= 96 {
        notification_routing::jobs::verify(conn)?;
    }
    if current_schema_version(conn)? >= 105 {
        subject_deletion_store::verify(conn)?;
    }
    Ok(())
}

fn validate_workspace_resource_references(conn: &Connection) -> Result<()> {
    let diagnostics = workspace_resource_reference_diagnostics(conn)?;
    if diagnostics.is_empty() {
        return Ok(());
    }
    Err(Error::Store(format!(
        "Workspace resource foreign-key preflight failed:\n- {}",
        diagnostics.join("\n- ")
    )))
}

fn workspace_resource_reference_diagnostics(conn: &Connection) -> Result<Vec<String>> {
    let mut diagnostics = Vec::new();
    let current_assignment_reference_sql =
        if column_exists(conn, "ticket_current_worker_assignments", "role")?
            && column_exists(conn, "ticket_worker_assignments", "role")?
        {
            "SELECT current.workspace_id || '/' || current.assignment_id \
             FROM ticket_current_worker_assignments AS current \
             WHERE NOT EXISTS (SELECT 1 FROM ticket_worker_assignments AS assignment \
                 WHERE assignment.workspace_id = current.workspace_id \
                   AND assignment.ticket_id = current.ticket_id \
                   AND assignment.role = current.role \
                   AND assignment.assignment_id = current.assignment_id) LIMIT 100"
        } else {
            "SELECT current.workspace_id || '/' || current.assignment_id \
             FROM ticket_current_worker_assignments AS current \
             WHERE NOT EXISTS (SELECT 1 FROM ticket_worker_assignments AS assignment \
                 WHERE assignment.workspace_id = current.workspace_id \
                   AND assignment.ticket_id = current.ticket_id \
                   AND assignment.assignment_id = current.assignment_id) LIMIT 100"
        };
    for (table, repository_nullable) in [
        ("workdir_registry", true),
        ("artifacts", true),
        ("typed_tickets", true),
        ("merge_requests", false),
    ] {
        if !table_exists(conn, table)? || !column_exists(conn, table, "repository_id")? {
            continue;
        }
        let null_filter = if repository_nullable {
            "child.repository_id IS NOT NULL AND"
        } else {
            ""
        };
        collect_reference_diagnostics(
            conn,
            &format!(
                "SELECT child.workspace_id || '/' || child.repository_id FROM {table} AS child \
                 WHERE {null_filter} NOT EXISTS (\
                     SELECT 1 FROM repositories AS parent \
                     WHERE parent.workspace_id = child.workspace_id \
                       AND parent.repository_id = child.repository_id\
                 ) LIMIT 100"
            ),
            &format!("{table}.repository_id"),
            &mut diagnostics,
        )?;
    }
    if table_exists(conn, "typed_ticket_targets")?
        && column_exists(conn, "typed_ticket_targets", "repository_key")?
    {
        collect_reference_diagnostics(
            conn,
            "SELECT child.workspace_id || '/' || child.repository_key
               FROM typed_ticket_targets AS child
              WHERE NOT EXISTS (
                    SELECT 1 FROM repositories AS parent
                     WHERE parent.workspace_id = child.workspace_id
                       AND parent.repository_key = child.repository_key
              ) LIMIT 100",
            "typed_ticket_targets.repository_key",
            &mut diagnostics,
        )?;
    }

    for (label, sql) in [
        (
            "typed_ticket_relations.target",
            "SELECT relation.workspace_id || '/' || relation.ticket_id || ' -> ' || relation.target \
             FROM typed_ticket_relations AS relation \
             WHERE NOT EXISTS (SELECT 1 FROM typed_tickets AS target \
                 WHERE target.workspace_id = relation.workspace_id \
                   AND target.ticket_id = relation.target) LIMIT 100",
        ),
        (
            "objective_events.objective_id",
            "SELECT child.workspace_id || '/' || child.event_id || ' -> ' || child.objective_id \
             FROM objective_events AS child \
             WHERE NOT EXISTS (SELECT 1 FROM objectives AS parent \
                 WHERE parent.workspace_id = child.workspace_id \
                   AND parent.objective_id = child.objective_id) LIMIT 100",
        ),
        (
            "objective_resources.objective_id",
            "SELECT child.workspace_id || '/' || child.resource_path || ' -> ' || child.objective_id \
             FROM objective_resources AS child \
             WHERE NOT EXISTS (SELECT 1 FROM objectives AS parent \
                 WHERE parent.workspace_id = child.workspace_id \
                   AND parent.objective_id = child.objective_id) LIMIT 100",
        ),
        (
            "objective_ticket_links.objective_id",
            "SELECT link.workspace_id || '/' || link.objective_id || ' -> ' || link.ticket_id \
             FROM objective_ticket_links AS link \
             WHERE NOT EXISTS (SELECT 1 FROM objectives AS objective \
                 WHERE objective.workspace_id = link.workspace_id \
                   AND objective.objective_id = link.objective_id) LIMIT 100",
        ),
        (
            "objective_ticket_links.ticket_id",
            "SELECT link.workspace_id || '/' || link.objective_id || ' -> ' || link.ticket_id \
             FROM objective_ticket_links AS link \
             WHERE NOT EXISTS (SELECT 1 FROM typed_tickets AS ticket \
                 WHERE ticket.workspace_id = link.workspace_id \
                   AND ticket.ticket_id = link.ticket_id) LIMIT 100",
        ),
        (
            "ticket_current_worker_assignments.assignment_id",
            current_assignment_reference_sql,
        ),
        (
            "ticket_worker_assignment_events.assignment_id",
            "SELECT event.workspace_id || '/' || event.event_id \
             FROM ticket_worker_assignment_events AS event \
             WHERE (event.assignment_id IS NOT NULL AND NOT EXISTS (\
                       SELECT 1 FROM ticket_worker_assignments AS assignment \
                       WHERE assignment.workspace_id = event.workspace_id \
                         AND assignment.ticket_id = event.ticket_id \
                         AND assignment.assignment_id = event.assignment_id)) \
                OR (event.previous_assignment_id IS NOT NULL AND NOT EXISTS (\
                       SELECT 1 FROM ticket_worker_assignments AS assignment \
                       WHERE assignment.workspace_id = event.workspace_id \
                         AND assignment.ticket_id = event.ticket_id \
                         AND assignment.assignment_id = event.previous_assignment_id)) LIMIT 100",
        ),
        (
            "artifacts.ticket_id",
            "SELECT artifact.workspace_id || '/' || artifact.artifact_id || ' -> ' || artifact.ticket_id \
             FROM artifacts AS artifact WHERE artifact.ticket_id IS NOT NULL \
               AND NOT EXISTS (SELECT 1 FROM typed_tickets AS ticket \
                 WHERE ticket.workspace_id = artifact.workspace_id \
                   AND ticket.ticket_id = artifact.ticket_id) LIMIT 100",
        ),
        (
            "artifacts.worker_ref",
            "SELECT artifact.workspace_id || '/' || artifact.artifact_id \
             FROM artifacts AS artifact \
             WHERE (artifact.worker_ref_kind IS NULL) != (artifact.worker_ref_key IS NULL) LIMIT 100",
        ),
        (
            "artifacts.objective_id",
            "SELECT artifact.workspace_id || '/' || artifact.artifact_id || ' -> ' || artifact.objective_id \
             FROM artifacts AS artifact WHERE artifact.objective_id IS NOT NULL \
               AND NOT EXISTS (SELECT 1 FROM objectives AS objective \
                 WHERE objective.workspace_id = artifact.workspace_id \
                   AND objective.objective_id = artifact.objective_id) LIMIT 100",
        ),
    ] {
        let Some(table) = label.split('.').next() else {
            continue;
        };
        if !table_exists(conn, table)? {
            continue;
        }
        if sql.contains("typed_tickets") && !table_exists(conn, "typed_tickets")? {
            continue;
        }
        if sql.contains("worker.worker_id") && !column_exists(conn, "worker_registry", "worker_id")?
        {
            continue;
        }
        if sql.contains("assignment.worker_id")
            && !column_exists(conn, "ticket_worker_assignments", "worker_id")?
        {
            continue;
        }
        if sql.contains("current.worker_id")
            && !column_exists(conn, "ticket_current_worker_assignments", "worker_id")?
        {
            continue;
        }
        collect_reference_diagnostics(conn, sql, label, &mut diagnostics)?;
    }

    // Assignment and operation rows are historical soft references. The current schema records
    // an explicit tombstone before a live Ticket or Worker parent is deleted or moved. Missing
    // parents without that authority are corruption and remain startup-blocking.
    if table_exists(conn, "ticket_worker_assignments")? && table_exists(conn, "typed_tickets")? {
        let tombstone_filter = if table_exists(conn, "ticket_assignment_ticket_tombstones")? {
            "AND NOT EXISTS (SELECT 1 FROM ticket_assignment_ticket_tombstones AS tombstone \
             WHERE tombstone.workspace_id = assignment.workspace_id \
               AND tombstone.ticket_id = assignment.ticket_id)"
        } else {
            ""
        };
        collect_reference_diagnostics(
            conn,
            &format!(
                "SELECT assignment.workspace_id || '/' || assignment.assignment_id || ' -> ' || assignment.ticket_id \
                 FROM ticket_worker_assignments AS assignment \
                 WHERE NOT EXISTS (SELECT 1 FROM typed_tickets AS ticket \
                     WHERE ticket.workspace_id = assignment.workspace_id \
                       AND ticket.ticket_id = assignment.ticket_id) \
                 {tombstone_filter} LIMIT 100"
            ),
            "ticket_worker_assignments.ticket_id",
            &mut diagnostics,
        )?;
    }
    if table_exists(conn, "ticket_worker_assignments")?
        && table_exists(conn, "worker_registry")?
        && column_exists(conn, "ticket_worker_assignments", "worker_id")?
        && column_exists(conn, "worker_registry", "worker_id")?
    {
        collect_assignment_worker_reference_diagnostics(conn, &mut diagnostics)?;
    }
    if table_exists(conn, "ticket_assignment_operations")? && table_exists(conn, "typed_tickets")? {
        let tombstone_filter = if table_exists(conn, "ticket_assignment_ticket_tombstones")? {
            "AND NOT EXISTS (SELECT 1 FROM ticket_assignment_ticket_tombstones AS tombstone \
             WHERE tombstone.workspace_id = operation.workspace_id \
               AND tombstone.ticket_id = operation.ticket_id)"
        } else {
            ""
        };
        collect_reference_diagnostics(
            conn,
            &format!(
                "SELECT operation.workspace_id || '/' || operation.operation_id || ' -> ' || operation.ticket_id \
                 FROM ticket_assignment_operations AS operation \
                 WHERE NOT EXISTS (SELECT 1 FROM typed_tickets AS ticket \
                     WHERE ticket.workspace_id = operation.workspace_id \
                       AND ticket.ticket_id = operation.ticket_id) \
                 {tombstone_filter} LIMIT 100"
            ),
            "ticket_assignment_operations.ticket_id",
            &mut diagnostics,
        )?;
    }
    Ok(diagnostics)
}

fn collect_assignment_worker_reference_diagnostics(
    conn: &Connection,
    diagnostics: &mut Vec<String>,
) -> Result<()> {
    let has_assignment_tombstones = table_exists(conn, "ticket_assignment_worker_tombstones")?;
    let tombstone_filter = if has_assignment_tombstones {
        "AND NOT EXISTS (SELECT 1 FROM ticket_assignment_worker_tombstones AS tombstone \
         WHERE tombstone.workspace_id = assignment.workspace_id \
           AND tombstone.runtime_id = assignment.runtime_id \
           AND tombstone.worker_id = assignment.worker_id)"
    } else {
        ""
    };
    let worker_principal_filter =
        if column_exists(conn, "ticket_worker_assignments", "principal_kind")? {
            "assignment.principal_kind = 'worker' AND "
        } else {
            ""
        };
    let sql = format!(
        "SELECT assignment.workspace_id, assignment.assignment_id, \
                assignment.runtime_id, assignment.worker_id \
         FROM ticket_worker_assignments AS assignment \
         WHERE {worker_principal_filter}NOT EXISTS (SELECT 1 FROM worker_registry AS worker \
             WHERE worker.workspace_id = assignment.workspace_id \
               AND worker.runtime_id = assignment.runtime_id \
               AND worker.worker_id = assignment.worker_id) \
         {tombstone_filter}"
    );
    let mut statement = conn.prepare(&sql)?;
    let rows = statement.query_map([], |row| {
        Ok((
            row.get::<_, String>(0)?,
            row.get::<_, String>(1)?,
            row.get::<_, String>(2)?,
            row.get::<_, String>(3)?,
        ))
    })?;
    let mut worker_diagnostic_count = 0;
    for row in rows {
        let (workspace_id, assignment_id, runtime_id, worker_id) = row?;
        diagnostics.push(format!(
            "ticket_worker_assignments.worker_id: \
             {workspace_id}/{assignment_id} -> {runtime_id}/{worker_id}"
        ));
        worker_diagnostic_count += 1;
        if worker_diagnostic_count == 100 {
            break;
        }
    }
    Ok(())
}

fn collect_reference_diagnostics(
    conn: &Connection,
    sql: &str,
    label: &str,
    diagnostics: &mut Vec<String>,
) -> Result<()> {
    let mut statement = conn.prepare(sql)?;
    let rows = statement.query_map([], |row| row.get::<_, String>(0))?;
    for row in rows {
        diagnostics.push(format!("{label}: {}", row?));
    }
    Ok(())
}

fn read_workspace_memory_settings(
    row: &rusqlite::Row<'_>,
) -> rusqlite::Result<WorkspaceMemorySettingsRecord> {
    Ok(WorkspaceMemorySettingsRecord {
        workspace_id: row.get(0)?,
        language: row.get(1)?,
        created_at: row.get(2)?,
        updated_at: row.get(3)?,
    })
}

fn validate_workspace_memory_settings_snapshot(
    snapshot: &manifest::WorkspaceMemorySettingsSnapshot,
    expected_workspace_id: &str,
) -> Result<()> {
    if snapshot.workspace_id != expected_workspace_id
        || !manifest::is_normalized_workspace_memory_language(&snapshot.language)
    {
        return Err(Error::Store(
            "Workspace Memory settings are corrupt or belong to another Workspace".to_string(),
        ));
    }
    Ok(())
}

fn validate_workspace_memory_settings_record(
    record: &WorkspaceMemorySettingsRecord,
    expected_workspace_id: &str,
) -> Result<()> {
    validate_workspace_memory_settings_snapshot(
        &manifest::WorkspaceMemorySettingsSnapshot {
            workspace_id: record.workspace_id.clone(),
            language: record.language.clone(),
        },
        expected_workspace_id,
    )
}

fn normalize_workspace_memory_language(language: &str) -> Result<String> {
    let language = language.trim();
    if !manifest::is_normalized_workspace_memory_language(language) {
        return Err(Error::InvalidInput(format!(
            "Workspace Memory language must be a non-empty UTF-8 string of at most {} characters without control characters",
            manifest::MAX_WORKSPACE_MEMORY_LANGUAGE_CHARS
        )));
    }
    Ok(language.to_string())
}

pub(crate) fn validate_worker_singleton_key(key: &str) -> Result<()> {
    if key.is_empty() {
        return Err(Error::InvalidInput(
            "Worker singleton key must not be empty".to_string(),
        ));
    }
    if key.len() > 512 {
        return Err(Error::InvalidInput(
            "Worker singleton key must not exceed 512 UTF-8 bytes".to_string(),
        ));
    }
    Ok(())
}

fn subject_create_recovery_candidate(
    conn: &Connection,
    workspace: &str,
    lease: &WorkerSingletonLease,
) -> Result<Option<String>> {
    if !lease
        .key
        .starts_with(crate::subjektiv::SUBJECT_WORKER_SINGLETON_PREFIX)
    {
        return Err(Error::InvalidInput("not a Subject singleton".into()));
    }
    let generation = i64::try_from(lease.generation)
        .map_err(|_| Error::InvalidInput("invalid singleton generation".into()))?;
    Ok(conn.query_row(
        "SELECT r.create_fingerprint FROM worker_create_reservations r
         JOIN worker_singleton_owners o ON o.workspace_id=r.workspace_id
           AND o.runtime_id=r.runtime_id AND o.worker_id=r.worker_id
           AND o.singleton_key=r.singleton_key AND o.generation=r.singleton_generation
         WHERE r.workspace_id=?1 AND r.runtime_id=?2 AND r.worker_id=?3
           AND r.singleton_key=?4 AND r.singleton_generation=?5 AND r.state='removed'
           AND NOT EXISTS(SELECT 1 FROM worker_registry w
             WHERE w.workspace_id=r.workspace_id AND w.runtime_id=r.runtime_id AND w.worker_id=r.worker_id)",
        params![workspace, lease.worker.runtime_id, lease.worker.worker_id, lease.key, generation],
        |row| row.get(0),
    ).optional()?)
}

fn current_worker_singleton_owner(
    conn: &Connection,
    workspace_id: &str,
    singleton_key: &str,
) -> Result<Option<(WorkerSingletonLease, Option<String>)>> {
    let owner = conn
        .query_row(
            "SELECT owner.runtime_id, owner.worker_id, owner.generation, \
                    CASE WHEN reservation.state='removed' AND EXISTS(SELECT 1 FROM subject_deletion_removals d WHERE d.workspace_id=owner.workspace_id AND d.runtime_id=owner.runtime_id AND d.worker_id=owner.worker_id AND owner.singleton_key IN ('subjektiv:'||d.subject_id,'subjektiv-consolidation:'||d.subject_id)) THEN 'created' \
                    WHEN substr(owner.singleton_key,1,10)='subjektiv:' AND reservation.state='removed' \
                      AND NOT EXISTS(SELECT 1 FROM subject_worker_releases r WHERE r.workspace_id=owner.workspace_id AND r.worker_id=owner.worker_id AND r.runtime_id=owner.runtime_id AND r.singleton_key=owner.singleton_key AND r.singleton_generation=owner.generation AND r.completed=1) \
                      AND NOT EXISTS(SELECT 1 FROM subject_create_recoveries r WHERE r.workspace_id=owner.workspace_id AND r.worker_id=owner.worker_id AND r.runtime_id=owner.runtime_id AND r.singleton_key=owner.singleton_key AND r.singleton_generation=owner.generation AND r.create_fingerprint=reservation.create_fingerprint AND r.completed=1) \
                      AND NOT EXISTS(SELECT 1 FROM worker_removal_operations r JOIN subject_deletion_workers d ON d.workspace_id=r.workspace_id AND d.runtime_id=r.runtime_id AND d.worker_id=r.worker_id WHERE r.workspace_id=owner.workspace_id AND r.runtime_id=owner.runtime_id AND r.worker_id=owner.worker_id AND r.state='succeeded' AND owner.singleton_key='subjektiv:'||d.subject_id AND (d.prior_removal_operation_id=r.operation_id OR (d.prior_removal_operation_id IS NULL AND d.is_job=0 AND r.session_disposition='archive' AND r.archive_retention_kind='forever' AND r.metadata_disposition='tombstone'))) \
                      AND NOT EXISTS(SELECT 1 FROM subject_deletion_workers d WHERE d.workspace_id=owner.workspace_id AND d.runtime_id=owner.runtime_id AND d.worker_id=owner.worker_id AND owner.singleton_key='subjektiv:'||d.subject_id AND d.originals_absent=1) \
                    THEN 'created' ELSE reservation.state END \
             FROM worker_singleton_owners owner \
             LEFT JOIN worker_create_reservations reservation \
               ON reservation.workspace_id = owner.workspace_id \
              AND reservation.worker_id = owner.worker_id \
             WHERE owner.workspace_id = ?1 AND owner.singleton_key = ?2",
            params![workspace_id, singleton_key],
            |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, i64>(2)?,
                    row.get::<_, Option<String>>(3)?,
                ))
            },
        )
        .optional()?;
    owner
        .map(|(runtime_id, worker_id, generation, mut state)| {
            let worker = RuntimeWorkerRef::new(runtime_id, worker_id);
            if let Some(subject) = singleton_key.strip_prefix("subjektiv:").or_else(|| singleton_key.strip_prefix("subjektiv-consolidation:"))
                && state.as_deref() == Some("created")
                && subject_deletion_store::completed_removal_matches(conn, workspace_id, subject, &worker)?
            {
                let removed: bool = conn.query_row("SELECT EXISTS(SELECT 1 FROM worker_create_reservations WHERE workspace_id=?1 AND runtime_id=?2 AND worker_id=?3 AND state='removed')",params![workspace_id,worker.runtime_id,worker.worker_id],|r|r.get(0))?;
                if removed { state = Some("removed".into()); }
            }
            let generation = generation.try_into().map_err(|_| {
                Error::Store(format!(
                    "Worker singleton key {singleton_key:?} has an invalid generation"
                ))
            })?;
            Ok((
                WorkerSingletonLease {
                    key: singleton_key.to_string(),
                    generation,
                    worker,
                },
                state,
            ))
        })
        .transpose()
}

fn require_current_worker_singleton_lease(
    conn: &Connection,
    workspace_id: &str,
    expected: &WorkerSingletonLease,
) -> Result<()> {
    let current =
        current_worker_singleton_owner(conn, workspace_id, &expected.key)?.map(|(lease, _)| lease);
    if current.as_ref() != Some(expected) {
        let current_worker = current
            .map(|lease| {
                format!(
                    "{}:{} generation {}",
                    lease.worker.runtime_id, lease.worker.worker_id, lease.generation
                )
            })
            .unwrap_or_else(|| "no current owner".to_string());
        return Err(Error::RepositoryConflict(format!(
            "worker_singleton_fenced: Worker {}:{} generation {} no longer owns singleton key {:?}; current owner is {current_worker}",
            expected.worker.runtime_id,
            expected.worker.worker_id,
            expected.generation,
            expected.key
        )));
    }
    Ok(())
}

fn bound_worker_create_fingerprint(
    request_fingerprint: &str,
    snapshot: &manifest::WorkspaceMemorySettingsSnapshot,
) -> String {
    let mut digest = Sha256::new();
    digest.update(b"workspace-worker-create-v3\0");
    digest.update(request_fingerprint.as_bytes());
    digest.update(b"\0");
    digest.update(snapshot.workspace_id.as_bytes());
    digest.update(b"\0");
    digest.update(snapshot.language.as_bytes());
    let encoded = digest
        .finalize()
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    format!("sha256:{encoded}")
}

fn current_schema_version(conn: &Connection) -> Result<i64> {
    conn.query_row(
        "SELECT COALESCE(MAX(version), 0) FROM __yoi_schema_migrations",
        [],
        |row| row.get(0),
    )
    .map_err(Error::from)
}

fn worker_resource_id(worker: &RuntimeWorkerRef) -> String {
    fn encode(value: &str) -> String {
        value
            .as_bytes()
            .iter()
            .map(|byte| format!("{byte:02X}"))
            .collect()
    }
    format!(
        "{}:{}",
        encode(&worker.runtime_id),
        encode(&worker.worker_id)
    )
}

fn parse_worker_resource_id(resource_id: &str) -> Option<RuntimeWorkerRef> {
    fn decode(value: &str) -> Option<String> {
        if value.len() % 2 != 0 {
            return None;
        }
        let bytes = (0..value.len())
            .step_by(2)
            .map(|index| u8::from_str_radix(&value[index..index + 2], 16).ok())
            .collect::<Option<Vec<_>>>()?;
        String::from_utf8(bytes).ok()
    }
    let (runtime_id, worker_id) = resource_id.split_once(':')?;
    Some(RuntimeWorkerRef::new(
        decode(runtime_id)?,
        decode(worker_id)?,
    ))
}

fn allocate_resource_key(
    conn: &Connection,
    workspace_id: &str,
    kind: WorkspaceResourceKind,
    resource_id: &str,
    allocated_at: &str,
) -> Result<String> {
    if let Some(existing) = conn
        .query_row(
            "SELECT resource_key FROM workspace_resource_keys
             WHERE workspace_id = ?1 AND resource_kind = ?2 AND resource_id = ?3",
            params![workspace_id, kind.as_str(), resource_id],
            |row| row.get(0),
        )
        .optional()?
    {
        return Ok(existing);
    }
    conn.execute(
        "INSERT OR IGNORE INTO workspace_resource_key_counters
         (workspace_id, resource_kind, next_sequence) VALUES (?1, ?2, 1)",
        params![workspace_id, kind.as_str()],
    )?;
    let sequence: i64 = conn.query_row(
        "SELECT next_sequence FROM workspace_resource_key_counters
         WHERE workspace_id = ?1 AND resource_kind = ?2",
        params![workspace_id, kind.as_str()],
        |row| row.get(0),
    )?;
    conn.execute(
        "UPDATE workspace_resource_key_counters SET next_sequence = ?3
         WHERE workspace_id = ?1 AND resource_kind = ?2",
        params![workspace_id, kind.as_str(), sequence + 1],
    )?;
    let resource_key = format!("{}-{sequence}", kind.prefix());
    conn.execute(
        "INSERT INTO workspace_resource_keys
         (workspace_id, resource_kind, resource_id, sequence, resource_key, allocated_at)
         VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
        params![
            workspace_id,
            kind.as_str(),
            resource_id,
            sequence,
            resource_key,
            allocated_at
        ],
    )?;
    Ok(resource_key)
}

fn workspace_schema_migration_history(conn: &Connection) -> Result<Vec<(i64, String)>> {
    let mut stmt =
        conn.prepare("SELECT version, name FROM __yoi_schema_migrations ORDER BY version ASC")?;
    stmt.query_map([], |row| {
        Ok((row.get::<_, i64>(0)?, row.get::<_, String>(1)?))
    })?
    .collect::<rusqlite::Result<Vec<_>>>()
    .map_err(Error::from)
}

fn verify_schema_history(conn: &Connection, current: i64) -> Result<()> {
    let rows = workspace_schema_migration_history(conn)?;
    let Some((baseline_version, baseline_name)) = rows.first() else {
        return Err(Error::Store(format!(
            "database migration history is empty for schema version {current}"
        )));
    };
    if *baseline_version < OLDEST_SCHEMA_VERSION
        || *baseline_version > LATEST_SCHEMA_VERSION
        || baseline_name != SCHEMA_BASELINE_NAME
    {
        return Err(Error::Store(format!(
            "database migration history does not start with a retained schema baseline: found {rows:?}"
        )));
    }

    let mut expected = vec![(*baseline_version, SCHEMA_BASELINE_NAME.to_string())];
    for migration in MIGRATIONS
        .iter()
        .filter(|migration| migration.version > *baseline_version && migration.version <= current)
    {
        // The two published schema-103 migrations are alternatives, not aliases.
        // Match the exact saved identity while retaining every other history check.
        let migration = if migration.version == JOB_INPUT_RETENTION_SCHEMA_103.version
            && rows.iter().any(|(version, name)| {
                *version == JOB_INPUT_RETENTION_SCHEMA_103.version
                    && name == JOB_INPUT_RETENTION_SCHEMA_103.name
            }) {
            &JOB_INPUT_RETENTION_SCHEMA_103
        } else {
            migration
        };
        expected.push((migration.version, migration.name.to_string()));
    }
    if rows != expected || expected.last().map(|row| row.0) != Some(current) {
        return Err(Error::Store(format!(
            "database migration history is not canonical for schema version {current}: expected {expected:?}, found {rows:?}"
        )));
    }
    Ok(())
}

fn workspace_schema_migration_plan(conn: &Connection) -> Result<WorkspaceSchemaMigrationPlan> {
    let current = current_schema_version(conn)?;
    if current > LATEST_SCHEMA_VERSION {
        return Err(Error::Store(format!(
            "database schema version {current} is newer than this server supports ({LATEST_SCHEMA_VERSION}); refusing to serve with an older binary"
        )));
    }
    if current != 0 && current < OLDEST_SCHEMA_VERSION {
        return Err(Error::Store(format!(
            "database schema version {current} predates the oldest retained migration ({OLDEST_SCHEMA_VERSION})"
        )));
    }
    if current != 0 {
        verify_schema_history(conn, current)?;
    }

    let migrations = if current == 0 {
        vec![WorkspaceSchemaMigrationStep {
            version: LATEST_SCHEMA_VERSION,
            name: SCHEMA_BASELINE_NAME.to_string(),
        }]
    } else {
        MIGRATIONS
            .iter()
            .filter(|migration| migration.version > current)
            .map(|migration| WorkspaceSchemaMigrationStep {
                version: migration.version,
                name: migration.name.to_string(),
            })
            .collect()
    };
    Ok(WorkspaceSchemaMigrationPlan {
        current_schema_version: current,
        target_schema_version: LATEST_SCHEMA_VERSION,
        migrations,
    })
}

#[cfg(test)]
fn apply_migrations(conn: &Connection) -> Result<()> {
    apply_migrations_with_secret_source(
        conn,
        conn.path().filter(|path| !path.is_empty()).map(Path::new),
    )
}

fn apply_migrations_with_secret_source(
    conn: &Connection,
    secret_source: Option<&Path>,
) -> Result<()> {
    let plan = workspace_schema_migration_plan(conn)?;
    // Check recovery blockers before any retained migration commits. Waiting until
    // schema 87 would strand a schema-84 operator without a runnable old binary.
    if plan.current_schema_version > 0
        && plan.current_schema_version < 88
        && table_exists(conn, "worker_removal_operations")?
    {
        let unresolved: Option<String> = conn.query_row(
            "SELECT operation_id FROM worker_removal_operations WHERE state IN ('executing','failed') ORDER BY operation_id LIMIT 1",
            [], |row| row.get(0),
        ).optional()?;
        if let Some(operation) = unresolved {
            return Err(Error::Store(format!(
                "Worker removal {operation} requires receipt reconciliation on the existing Server before schema migration; database remains at schema {}",
                plan.current_schema_version
            )));
        }
    }
    if plan.current_schema_version == 0 {
        let foreign_keys_enabled =
            conn.query_row("PRAGMA foreign_keys", [], |row| row.get::<_, i64>(0))? != 0;
        let legacy_alter_table_enabled =
            conn.query_row("PRAGMA legacy_alter_table", [], |row| row.get::<_, i64>(0))? != 0;
        if foreign_keys_enabled {
            conn.execute_batch("PRAGMA foreign_keys = OFF;")?;
        }
        if !legacy_alter_table_enabled {
            conn.execute_batch("PRAGMA legacy_alter_table = ON;")?;
        }
        let create_result = (|| {
            let tx = rusqlite::Transaction::new_unchecked(conn, TransactionBehavior::Exclusive)?;
            create_latest_workspace_schema(&tx)?;
            tx.execute(
                "INSERT INTO __yoi_schema_migrations (version, name) VALUES (?1, ?2)",
                params![LATEST_SCHEMA_VERSION, SCHEMA_BASELINE_NAME],
            )?;
            tx.commit()?;
            Ok(())
        })();
        let restore_result = match (legacy_alter_table_enabled, foreign_keys_enabled) {
            (false, true) => {
                conn.execute_batch("PRAGMA legacy_alter_table = OFF; PRAGMA foreign_keys = ON;")
            }
            (false, false) => conn.execute_batch("PRAGMA legacy_alter_table = OFF;"),
            (true, true) => conn.execute_batch("PRAGMA foreign_keys = ON;"),
            (true, false) => Ok(()),
        }
        .map_err(Error::from);
        match (create_result, restore_result) {
            (Err(error), _) => return Err(error),
            (Ok(()), Err(error)) => return Err(error),
            (Ok(()), Ok(())) => {}
        }
    } else {
        for step in &plan.migrations {
            let migration = MIGRATIONS
                .iter()
                .find(|migration| migration.version == step.version)
                .ok_or_else(|| {
                    Error::Store(format!(
                        "migration implementation for schema version {} is missing",
                        step.version
                    ))
                })?;
            if migration.version == 87 {
                migrate_repository_keys_v86_to_v87_with_secret_source(conn, secret_source)?;
            } else {
                (migration.apply)(conn)?;
            }
        }
    }

    verify_schema_history(conn, LATEST_SCHEMA_VERSION)?;
    crate::plugin_catalog::verify(conn)?;
    crate::plugin_plan::verify_plan_schema(conn)?;
    crate::plugin_host::verify_receipt_schema(conn)?;
    crate::plugin_plan::verify_launch_schema(conn)?;
    subject_assignment_migration::verify(conn)?;
    verify_workspace_runtime_binding_schema(conn)?;
    verify_workspace_runtime_verification_schema(conn)?;
    verify_workspace_deletion_schema(conn)?;
    verify_workspace_signing_identity_schema(conn)
}

fn table_exists(conn: &Connection, table_name: &str) -> Result<bool> {
    conn.query_row(
        "SELECT EXISTS(SELECT 1 FROM sqlite_schema WHERE type = 'table' AND name = ?1)",
        params![table_name],
        |row| row.get::<_, bool>(0),
    )
    .map_err(Error::from)
}

fn column_exists(conn: &Connection, table_name: &str, column_name: &str) -> Result<bool> {
    Ok(table_columns(conn, table_name)?
        .iter()
        .any(|column| column == column_name))
}

fn table_columns(conn: &Connection, table_name: &str) -> Result<Vec<String>> {
    let mut stmt = conn.prepare(&format!("PRAGMA table_info({table_name})"))?;
    let rows = stmt.query_map([], |row| row.get::<_, String>(1))?;
    rows.collect::<rusqlite::Result<Vec<_>>>()
        .map_err(Error::from)
}

