    #[test]
    fn runtime_removal_rejects_shared_binding_and_fences_new_binding_until_cleanup() {
        let (temp, store) = runtime_removal_test_store();
        store
            .with_conn(|conn| {
                conn.execute_batch(
                    "INSERT INTO accounts(account_id, kind, handle, display_name, created_at, updated_at) \
                     VALUES ('owner-b', 'user', 'owner-b', 'Owner B', '1', '1'); \
                     INSERT INTO workspaces(workspace_id, owner_account_id, display_name, state, created_at, updated_at) \
                     VALUES ('workspace-b', 'owner-b', 'Workspace B', 'active', '1', '1'); \
                     INSERT INTO workspace_runtime_bindings(\
                         workspace_id, runtime_id, display_name, base_url, public_key, \
                         public_key_fingerprint, binding_id, authentication_mode, \
                         created_at, updated_at\
                     ) VALUES (\
                         'workspace-b', 'runtime-a', 'Runtime A', 'https://runtime.invalid', \
                         'key-a', 'fingerprint-b', 'binding-other', 'legacy_server_issuer', '1', '1'\
                     );",
                )?;
                Ok(())
            })
            .unwrap();
        let shared = store
            .reserve_runtime_removal(
                "workspace-a",
                "runtime-a",
                "remove-shared",
                "fingerprint-shared",
                "binding-live",
                &store
                    .load_workspace_config("workspace-a")
                    .unwrap()
                    .unwrap()
                    .snapshot
                    .digest,
            )
            .unwrap_err();
        assert!(
            shared
                .to_string()
                .contains("runtime_removal_other_workspace_binding_blocked")
        );
        assert_runtime_removal_binding_unchanged(&store);
        assert!(
            store
                .get_workspace_runtime_binding("workspace-b", "runtime-a")
                .unwrap()
                .is_some()
        );

        store
            .with_conn(|conn| {
                conn.execute(
                    "DELETE FROM workspace_runtime_bindings WHERE workspace_id = 'workspace-b'",
                    [],
                )?;
                Ok(())
            })
            .unwrap();
        store
            .reserve_runtime_removal(
                "workspace-a",
                "runtime-a",
                "remove-fenced",
                "fingerprint-fenced",
                "binding-live",
                &store
                    .load_workspace_config("workspace-a")
                    .unwrap()
                    .unwrap()
                    .snapshot
                    .digest,
            )
            .unwrap();
        let competing_conn = Connection::open(temp.path().join("server.db")).unwrap();
        competing_conn
            .execute_batch("PRAGMA foreign_keys = ON; PRAGMA busy_timeout = 5000;")
            .unwrap();
        let blocked_insert = competing_conn.execute(
            "INSERT INTO workspace_runtime_bindings(\
                 workspace_id, runtime_id, display_name, base_url, public_key, \
                 public_key_fingerprint, binding_id, authentication_mode, \
                 created_at, updated_at\
             ) VALUES (\
                 'workspace-b', 'runtime-a', 'Runtime A', 'https://runtime.invalid', \
                 'key-a', 'fingerprint-b', 'binding-other', 'legacy_server_issuer', '1', '1'\
             )",
            [],
        );
        assert!(
            blocked_insert
                .unwrap_err()
                .to_string()
                .contains("runtime_removal_in_progress")
        );

        for competing_mutation in [
            "INSERT INTO worker_registry(\
                 workspace_id, worker_id, runtime_id, display_name, retention_state, created_at, updated_at\
             ) VALUES ('workspace-a', 'racing-worker', 'runtime-a', 'Racing Worker', 'normal', '2', '2')",
            "INSERT INTO worker_create_reservations(\
                 workspace_id, allocation_key, worker_id, runtime_id, create_fingerprint, state, created_at, updated_at\
             ) VALUES ('workspace-a', 'racing-allocation', 'racing-worker', 'runtime-a', 'racing-create', 'reserved', '2', '2')",
            "INSERT INTO workdir_create_operations(\
                 workspace_id, operation_id, request_fingerprint, repository_id, resolved_runtime_id, \
                 config_projection_digest, working_directory_id, state, created_at, updated_at\
             ) VALUES (\
                 'workspace-a', 'racing-workdir-create', 'racing-request', 'repository-a', 'runtime-a', \
                 'racing-projection', 'racing-workdir', 'pending', '2', '2'\
             )",
        ] {
            let error = competing_conn.execute(competing_mutation, []).unwrap_err();
            assert!(
                error.to_string().contains("runtime_removal_in_progress"),
                "competing Runtime resource mutation was not fenced: {error}"
            );
        }
        assert_runtime_removal_binding_unchanged(&store);
    }

    #[test]
    fn runtime_removal_checkpoint_replays_and_recovers_after_reopen() {
        let (temp, store) = runtime_removal_test_store();
        let reserved = store
            .reserve_runtime_removal(
                "workspace-a",
                "runtime-a",
                "remove-runtime-a",
                "fingerprint-a",
                "binding-live",
                &store
                    .load_workspace_config("workspace-a")
                    .unwrap()
                    .unwrap()
                    .snapshot
                    .digest,
            )
            .unwrap();
        assert!(!reserved.replay);
        let failed = store
            .mark_runtime_removal_failed("remove-runtime-a", "injected_cleanup_failure")
            .unwrap();
        assert_eq!(failed.state, RuntimeRemovalOperationState::Failed);
        assert_runtime_removal_binding_unchanged(&store);
        let retried = store
            .reserve_runtime_removal(
                "workspace-a",
                "runtime-a",
                "remove-runtime-a",
                "fingerprint-a",
                "binding-live",
                &store
                    .load_workspace_config("workspace-a")
                    .unwrap()
                    .unwrap()
                    .snapshot
                    .digest,
            )
            .unwrap();
        assert!(retried.replay);
        let checkpoint = store
            .commit_runtime_binding_removal("remove-runtime-a")
            .unwrap();
        assert_eq!(
            checkpoint.state,
            RuntimeRemovalOperationState::CleanupPending
        );
        assert!(checkpoint.binding_removed);
        drop(store);

        let reopened = Connection::open(temp.path().join("server.db")).unwrap();
        let (state, binding_removed): (String, i64) = reopened
            .query_row(
                "SELECT state, binding_removed FROM runtime_removal_operations \
                 WHERE operation_id = 'remove-runtime-a'",
                [],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(state, "cleanup_pending");
        assert_eq!(binding_removed, 1);
        reopened
            .execute(
                "UPDATE runtime_removal_operations \
                 SET state = 'succeeded', runtime_registration_removed = 1, completed_at = '2', updated_at = '2' \
                 WHERE operation_id = 'remove-runtime-a' AND state = 'cleanup_pending'",
                [],
            )
            .unwrap();
        let completed: (String, i64) = reopened
            .query_row(
                "SELECT state, runtime_registration_removed FROM runtime_removal_operations \
                 WHERE operation_id = 'remove-runtime-a'",
                [],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(completed, ("succeeded".to_string(), 1));
    }

    #[test]
    fn schema_v59_upgrade_adds_runtime_removal_authority_atomically() -> Result<()> {
        let temp = tempfile::tempdir().unwrap();
        let path = temp.path().join("server.db");
        prepare_retained_schema(&path, 59);

        let conn = Connection::open(&path)?;
        configure_sqlite(&conn)?;
        migrate_runtime_removal_operations_v59_to_v60(&conn)?;
        assert_eq!(current_schema_version(&conn)?, 60);
        let table_count: i64 = conn.query_row(
            "SELECT COUNT(*) FROM sqlite_master \
             WHERE type = 'table' AND name = 'runtime_removal_operations'",
            [],
            |row| row.get(0),
        )?;
        let trigger_count: i64 = conn.query_row(
            "SELECT COUNT(*) FROM sqlite_master \
             WHERE type = 'trigger' AND (\
                 name LIKE '%_blocked_by_runtime_removal' OR \
                 name LIKE 'runtime_binding_%_blocked_by_removal'\
             )",
            [],
            |row| row.get(0),
        )?;
        let foreign_key_failures: i64 =
            conn.query_row("SELECT COUNT(*) FROM pragma_foreign_key_check", [], |row| {
                row.get(0)
            })?;
        assert_eq!(table_count, 1);
        assert_eq!(trigger_count, 18);
        assert_eq!(foreign_key_failures, 0);
        Ok(())
    }

    #[test]
    fn schema_v60_upgrade_removes_worker_run_generation_column() {
        let temp = tempfile::tempdir().unwrap();
        let path = temp.path().join("server.db");
        prepare_retained_schema(&path, 60);

        let conn = Connection::open(&path).unwrap();
        configure_sqlite(&conn).unwrap();
        migrate_worker_run_generation_v60_to_v61(&conn).unwrap();
        assert_eq!(current_schema_version(&conn).unwrap(), 61);
        let columns = conn
            .prepare("PRAGMA table_info(worker_removal_operations)")
            .unwrap()
            .query_map([], |row| row.get::<_, String>(1))
            .unwrap()
            .collect::<rusqlite::Result<Vec<_>>>()
            .unwrap();
        assert!(!columns.iter().any(|column| column == "run_generation"));
        assert_eq!(
            conn.query_row("PRAGMA quick_check", [], |row| row.get::<_, String>(0))
                .unwrap(),
            "ok"
        );
        let foreign_key_failures: i64 = conn
            .query_row("SELECT COUNT(*) FROM pragma_foreign_key_check", [], |row| {
                row.get(0)
            })
            .unwrap();
        assert_eq!(foreign_key_failures, 0);
    }

    #[test]
    fn schema_v59_runtime_removal_migration_rolls_back_partial_ddl_and_marker() {
        let temp = tempfile::tempdir().unwrap();
        let store = SqliteWorkspaceStore::open_for_test(temp.path().join("server.db")).unwrap();
        store
            .with_conn(|conn| {
                let trigger_names = {
                    let mut stmt = conn.prepare(
                        "SELECT name FROM sqlite_master \
                         WHERE type = 'trigger' AND sql LIKE '%runtime_removal_operations%'",
                    )?;
                    stmt.query_map([], |row| row.get::<_, String>(0))?
                        .collect::<std::result::Result<Vec<_>, _>>()?
                };
                for trigger_name in trigger_names {
                    conn.execute_batch(&format!("DROP TRIGGER \"{trigger_name}\";"))?;
                }
                conn.execute_batch(
                    "DROP TABLE runtime_removal_operations; \
                     DELETE FROM __yoi_schema_migrations WHERE version = 60; \
                     CREATE INDEX runtime_removal_operations_one_active_runtime \
                     ON workspace_runtime_bindings(runtime_id);",
                )?;

                let migration_error = migrate_runtime_removal_operations_v59_to_v60(conn)
                    .expect_err("injected index-name collision must fail migration");
                assert!(migration_error.to_string().contains("already exists"));
                let table_count: i64 = conn.query_row(
                    "SELECT COUNT(*) FROM sqlite_master \
                     WHERE type = 'table' AND name = 'runtime_removal_operations'",
                    [],
                    |row| row.get(0),
                )?;
                let marker_count: i64 = conn.query_row(
                    "SELECT COUNT(*) FROM __yoi_schema_migrations WHERE version = 60",
                    [],
                    |row| row.get(0),
                )?;
                assert_eq!(table_count, 0, "partial Runtime removal DDL leaked");
                assert_eq!(marker_count, 0, "failed migration advanced schema marker");
                Ok(())
            })
            .unwrap();
    }

