    #[test]
    fn schema_v68_preserves_legacy_external_grants_without_command_authority() {
        let temp = tempfile::tempdir().unwrap();
        let path = temp.path().join("server.db");
        prepare_schema_v50(&path, Some("workspace-a"));
        let mut conn = Connection::open(&path).unwrap();
        configure_sqlite(&conn).unwrap();
        for migration in MIGRATIONS
            .iter()
            .filter(|migration| migration.version <= 67)
        {
            (migration.apply)(&conn).unwrap();
        }
        let tx = conn.transaction().unwrap();
        tx.execute_batch(
            "INSERT INTO external_workdir_grants (
                 grant_id, workspace_id, workdir_id, provider_instance_id, display_name,
                 permissions, created_by, created_at, expires_at, generation, status, updated_at
             ) VALUES
                 ('grant-ro', 'workspace-a', 'external-ro', 'provider-ro', 'Read only',
                  'read_only', 'owner', '1', NULL, 1, 'pending', '1'),
                 ('grant-rw', 'workspace-a', 'external-rw', 'provider-rw', 'Read write',
                  'read_write', 'owner', '1', NULL, 1, 'pending', '1');
             INSERT INTO workdir_registry (
                 workspace_id, workdir_id, display_name, source_kind, runtime_id,
                 repository_id, external_grant_id, creation_selector, creation_ref,
                 materialization_status, cleanliness, created_at, updated_at
             ) VALUES
                 ('workspace-a', 'external-ro', 'Read only', 'external_grant', NULL,
                  NULL, 'grant-ro', NULL, NULL, 'pending', 'unknown', '1', '1'),
                 ('workspace-a', 'external-rw', 'Read write', 'external_grant', NULL,
                  NULL, 'grant-rw', NULL, NULL, 'pending', 'unknown', '1', '1');",
        )
        .unwrap();
        tx.commit().unwrap();

        migrate_external_workdir_command_permission_v67_to_v68(&conn).unwrap();
        assert_eq!(current_schema_version(&conn).unwrap(), 68);
        let permissions = conn
            .prepare("SELECT permissions FROM external_workdir_grants ORDER BY grant_id")
            .unwrap()
            .query_map([], |row| row.get::<_, String>(0))
            .unwrap()
            .collect::<rusqlite::Result<Vec<_>>>()
            .unwrap();
        assert_eq!(permissions, vec!["read_only", "read_write"]);
        assert!(
            conn.execute(
                "UPDATE external_workdir_grants SET permissions = 'read_command' WHERE grant_id = 'grant-ro'",
                [],
            )
            .is_ok()
        );
        assert!(
            conn.execute(
                "UPDATE external_workdir_grants SET permissions = 'write_only' WHERE grant_id = 'grant-rw'",
                [],
            )
            .is_err()
        );
    }

    #[test]
    fn schema_v69_preserves_legacy_attachment_capabilities_and_allows_command_subsets() {
        let temp = tempfile::tempdir().unwrap();
        let path = temp.path().join("server.db");
        prepare_schema_v50(&path, Some("workspace-a"));
        let mut conn = Connection::open(&path).unwrap();
        configure_sqlite(&conn).unwrap();
        for migration in MIGRATIONS
            .iter()
            .filter(|migration| migration.version <= 68)
        {
            (migration.apply)(&conn).unwrap();
        }
        let tx = conn.transaction().unwrap();
        tx.execute_batch(
            r#"
            INSERT INTO worker_registry (
                workspace_id, runtime_id, worker_id, display_name, retention_state,
                created_at, updated_at
            ) VALUES ('workspace-a', 'runtime-a', 'worker-a', 'Worker A', 'normal', '1', '1');
            INSERT INTO external_workdir_grants (
                grant_id, workspace_id, workdir_id, provider_instance_id, display_name,
                permissions, created_by, created_at, expires_at, generation, status, updated_at
            ) VALUES
                ('grant-ro', 'workspace-a', 'external-ro', 'provider-ro', 'Read only',
                 'read_only', 'owner', '1', NULL, 1, 'pending', '1'),
                ('grant-rw', 'workspace-a', 'external-rw', 'provider-rw', 'Read write',
                 'read_write', 'owner', '1', NULL, 1, 'pending', '1');
            INSERT INTO workdir_registry (
                workspace_id, workdir_id, display_name, source_kind, runtime_id,
                repository_id, external_grant_id, creation_selector, creation_ref,
                materialization_status, cleanliness, created_at, updated_at
            ) VALUES
                ('workspace-a', 'external-ro', 'Read only', 'external_grant', NULL,
                 NULL, 'grant-ro', NULL, NULL, 'pending', 'unknown', '1', '1'),
                ('workspace-a', 'external-rw', 'Read write', 'external_grant', NULL,
                 NULL, 'grant-rw', NULL, NULL, 'pending', 'unknown', '1', '1');
            INSERT INTO worker_workdir_links (
                workspace_id, runtime_id, worker_id, workdir_id, alias, capabilities,
                linked_at, unlinked_at
            ) VALUES
                ('workspace-a', 'runtime-a', 'worker-a', 'external-ro', 'readonly',
                 'read_only', '1', '2'),
                ('workspace-a', 'runtime-a', 'worker-a', 'external-rw', 'readwrite',
                 'read_write', '1', '2');
            "#,
        )
        .unwrap();
        tx.commit().unwrap();

        migrate_workdir_command_attachment_capabilities_v68_to_v69(&conn).unwrap();
        assert_eq!(current_schema_version(&conn).unwrap(), 69);
        let capabilities = conn
            .prepare("SELECT capabilities FROM worker_workdir_links ORDER BY alias")
            .unwrap()
            .query_map([], |row| row.get::<_, String>(0))
            .unwrap()
            .collect::<rusqlite::Result<Vec<_>>>()
            .unwrap();
        assert_eq!(capabilities, vec!["read_only", "read_write"]);
        assert!(
            conn.execute(
                "UPDATE worker_workdir_links SET capabilities = 'command_only' WHERE alias = 'readonly'",
                [],
            )
            .is_ok()
        );
        assert!(
            conn.execute(
                "UPDATE worker_workdir_links SET capabilities = 'read_command' WHERE alias = 'readwrite'",
                [],
            )
            .is_ok()
        );
        assert!(
            conn.execute(
                "UPDATE worker_workdir_links SET capabilities = 'write_only' WHERE alias = 'readonly'",
                [],
            )
            .is_err()
        );
    }

    #[test]
    fn schema_v71_adds_delivery_claim_states_without_losing_existing_intent() {
        let temp = tempfile::tempdir().unwrap();
        let path = temp.path().join("server.db");
        prepare_schema_v50(&path, Some("workspace-a"));
        let conn = Connection::open(&path).unwrap();
        configure_sqlite(&conn).unwrap();
        for migration in MIGRATIONS
            .iter()
            .filter(|migration| migration.version <= 70)
        {
            (migration.apply)(&conn).unwrap();
        }
        conn.execute_batch(
            r#"
            INSERT INTO backend_jobs (
                workspace_id, job_id, purpose, input_revision, input_ref, request_json,
                intent_fingerprint, state, current_attempt, created_at, updated_at
            ) VALUES (
                'workspace-a', 'job-a', 'check', 'legacy-input-token', 'test://job-a', '{}',
                'sha256:test', 'pending', 1, '1', '1'
            );
            INSERT INTO backend_job_attempts (
                workspace_id, job_id, attempt_id, attempt, input_revision, state,
                deadline_at, created_at, updated_at
            ) VALUES (
                'workspace-a', 'job-a', 'job-a:attempt:1', 1, 'legacy-input-token', 'reserved',
                '2', '1', '1'
            );
            INSERT INTO backend_job_deliveries (
                workspace_id, delivery_id, job_id, attempt_id, target_runtime_id,
                target_worker_id, state, created_at, updated_at
            ) VALUES (
                'workspace-a', 'delivery-a', 'job-a', 'job-a:attempt:1', 'runtime-a',
                'worker-a', 'pending', '1', '1'
            );
            "#,
        )
        .unwrap();

        migrate_backend_job_delivery_claims_v70_to_v71(&conn).unwrap();
        assert_eq!(current_schema_version(&conn).unwrap(), 71);
        assert_eq!(
            conn.query_row(
                "SELECT state FROM backend_job_deliveries WHERE delivery_id = 'delivery-a'",
                [],
                |row| row.get::<_, String>(0),
            )
            .unwrap(),
            "pending"
        );
        assert_eq!(
            conn.execute(
                "UPDATE backend_job_deliveries SET state = 'sending' WHERE delivery_id = 'delivery-a'",
                [],
            )
            .unwrap(),
            1
        );
        assert_eq!(
            conn.execute(
                "UPDATE backend_job_deliveries SET state = 'unknown' WHERE delivery_id = 'delivery-a'",
                [],
            )
            .unwrap(),
            1
        );
    }

    #[test]
    fn backend_job_worker_cleanup_migration_queues_legacy_terminal_workers() {
        let conn = Connection::open_in_memory().unwrap();
        conn.execute_batch(
            r#"
            CREATE TABLE __yoi_schema_migrations (
                version INTEGER PRIMARY KEY,
                name TEXT NOT NULL
            );
            INSERT INTO __yoi_schema_migrations(version, name)
                VALUES (76, 'workspace schema baseline');
            CREATE TABLE backend_job_attempts (
                workspace_id TEXT NOT NULL,
                job_id TEXT NOT NULL,
                attempt_id TEXT NOT NULL,
                state TEXT NOT NULL,
                runtime_id TEXT,
                worker_id TEXT,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL
            );
            INSERT INTO backend_job_attempts VALUES
                ('w', 'terminal-bound', 'a1', 'completed', 'runtime', 'worker', '1', '2'),
                ('w', 'terminal-unbound', 'a2', 'failed', NULL, NULL, '1', '3'),
                ('w', 'running', 'a3', 'dispatched', 'runtime', 'running-worker', '1', '4');
            "#,
        )
        .unwrap();

        migrate_backend_job_worker_cleanup_v76_to_v77(&conn).unwrap();

        let states = conn
            .prepare(
                "SELECT job_id, worker_cleanup_state, worker_cleanup_completed_at FROM backend_job_attempts ORDER BY job_id",
            )
            .unwrap()
            .query_map([], |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, Option<String>>(1)?,
                    row.get::<_, Option<String>>(2)?,
                ))
            })
            .unwrap()
            .collect::<rusqlite::Result<Vec<_>>>()
            .unwrap();
        assert_eq!(
            states,
            vec![
                ("running".to_string(), None, None,),
                (
                    "terminal-bound".to_string(),
                    Some("pending".to_string()),
                    None,
                ),
                (
                    "terminal-unbound".to_string(),
                    Some("completed".to_string()),
                    Some("3".to_string()),
                ),
            ]
        );
        assert_eq!(current_schema_version(&conn).unwrap(), 77);
    }

    #[test]
    fn migration_resumes_from_a_valid_partially_applied_chain() {
        let temp = tempfile::tempdir().unwrap();
        let path = temp.path().join("server.db");
        prepare_schema_v50(&path, Some("workspace-a"));
        let conn = Connection::open(&path).unwrap();
        configure_sqlite(&conn).unwrap();
        migrate_workspace_runtime_bindings_v50_to_v51(&conn).unwrap();
        drop(conn);

        let plan = SqliteWorkspaceStore::migration_plan(&path).unwrap();
        assert_eq!(plan.current_schema_version, 51);
        assert_eq!(
            plan.migrations
                .iter()
                .map(|migration| migration.version)
                .collect::<Vec<_>>(),
            (52..=LATEST_SCHEMA_VERSION).collect::<Vec<_>>()
        );
        SqliteWorkspaceStore::migrate_database(&path).unwrap();
        let conn = Connection::open(&path).unwrap();
        assert_eq!(
            current_schema_version(&conn).unwrap(),
            LATEST_SCHEMA_VERSION
        );
        assert_eq!(
            workspace_schema_migration_history(&conn).unwrap().len(),
            (LATEST_SCHEMA_VERSION - 50 + 1) as usize
        );
        assert!(column_exists(&conn, "worker_workdir_links", "alias").unwrap());
        assert!(column_exists(&conn, "worker_workdir_links", "capabilities").unwrap());
        assert!(!column_exists(&conn, "worker_workdir_links", "role").unwrap());
    }

