    #[test]
    fn schema_v52_migrates_deletion_operations_and_normalizes_incomplete_reservations() -> Result<()>
    {
        let temp = tempfile::tempdir().unwrap();
        let path = temp.path().join("server.db");
        prepare_schema_v52(&path);
        let conn = Connection::open(&path).unwrap();
        conn.execute_batch(
            "INSERT INTO accounts(account_id,kind,handle,display_name,created_at,updated_at)
             VALUES('owner','user','owner','Owner','1','1');
             INSERT INTO workspaces(workspace_id,owner_account_id,display_name,state,created_at,updated_at)
             VALUES('workspace-a','owner','Workspace A','active','1','1');
             INSERT INTO worker_create_reservations(
                workspace_id,allocation_key,worker_id,runtime_id,create_fingerprint,state,
                request_fingerprint,memory_settings_revision,memory_language,created_at,updated_at
             ) VALUES(
                'workspace-a','allocation','worker-a','runtime-a','fingerprint','created',
                'request-fingerprint',NULL,NULL,'1','1'
             );
             INSERT INTO worker_create_reservations(
                workspace_id,allocation_key,worker_id,runtime_id,create_fingerprint,state,
                request_fingerprint,memory_settings_revision,memory_language,created_at,updated_at
             ) VALUES(
                'workspace-a','allocation-complete','worker-b','runtime-a','fingerprint-b','reserved',
                'request-complete',7,'ja','1','1'
             );",
        )
        .unwrap();
        configure_sqlite(&conn)?;
        migrate_workspace_deletion_v52_to_v53(&conn)?;
        assert_eq!(current_schema_version(&conn)?, 53);
        verify_workspace_deletion_schema(&conn)?;
        let reservation_state: String = conn.query_row(
            "SELECT state FROM worker_create_reservations WHERE workspace_id='workspace-a' AND allocation_key='allocation'",
            [],
            |row| row.get(0),
        )?;
        assert_eq!(reservation_state, "created");
        let reservation_memory = conn.query_row(
            "SELECT request_fingerprint, memory_language
             FROM worker_create_reservations
             WHERE workspace_id='workspace-a' AND allocation_key='allocation'",
            [],
            |row| {
                Ok((
                    row.get::<_, Option<String>>(0)?,
                    row.get::<_, Option<String>>(1)?,
                ))
            },
        )?;
        assert_eq!(reservation_memory, (None, None));
        let complete_memory = conn.query_row(
            "SELECT request_fingerprint, memory_language
             FROM worker_create_reservations
             WHERE workspace_id='workspace-a' AND allocation_key='allocation-complete'",
            [],
            |row| {
                Ok((
                    row.get::<_, Option<String>>(0)?,
                    row.get::<_, Option<String>>(1)?,
                ))
            },
        )?;
        assert_eq!(
            complete_memory,
            (Some("request-complete".to_string()), Some("ja".to_string()))
        );
        let violations: i64 =
            conn.query_row("SELECT COUNT(*) FROM pragma_foreign_key_check", [], |row| {
                row.get(0)
            })?;
        assert_eq!(violations, 0);
        Ok(())
    }

    #[test]
    fn schema_v53_signing_identity_migration_rolls_back_on_failure() {
        let temp = tempfile::tempdir().unwrap();
        let path = temp.path().join("server.db");
        prepare_schema_v52(&path);
        let conn = Connection::open(&path).unwrap();
        configure_sqlite(&conn).unwrap();
        migrate_workspace_deletion_v52_to_v53(&conn).unwrap();
        conn.execute_batch(
            "CREATE TABLE workspace_signing_identity_audit (unexpected TEXT NOT NULL);",
        )
        .unwrap();
        let before = conn
            .query_row(
                "SELECT sql FROM sqlite_schema WHERE type='table' AND name='workspace_signing_identity_audit'",
                [],
                |row| row.get::<_, String>(0),
            )
            .unwrap();

        assert!(migrate_workspace_signing_identity_v53_to_v54(&conn).is_err());
        assert_eq!(current_schema_version(&conn).unwrap(), 53);
        assert!(!table_exists(&conn, "workspace_signing_identities").unwrap());
        assert!(
            !table_exists(&conn, "workspace_signing_identity_provisioning_operations").unwrap()
        );
        let after = conn
            .query_row(
                "SELECT sql FROM sqlite_schema WHERE type='table' AND name='workspace_signing_identity_audit'",
                [],
                |row| row.get::<_, String>(0),
            )
            .unwrap();
        assert_eq!(after, before);
    }

