    #[tokio::test]
    async fn worker_create_reservation_allocates_uuid_before_runtime_and_replays_exact_input() {
        let dir = tempfile::tempdir().unwrap();
        let store = SqliteWorkspaceStore::open_api_fixture(dir.path().join("server.db")).unwrap();
        store
            .upsert_workspace(&WorkspaceRecord {
                workspace_id: "workspace-a".to_string(),
                owner_account_id: "owner-account".to_string(),
                display_name: "Workspace A".to_string(),
                state: "active".to_string(),
                created_at: "2026-08-06T00:00:00Z".to_string(),
                updated_at: "2026-08-06T00:00:00Z".to_string(),
            })
            .await
            .unwrap();

        let memory_settings = store.get_workspace_memory_settings("workspace-a").unwrap();
        assert_eq!(memory_settings.language, "English");
        let reserved = store
            .reserve_worker_create(
                "workspace-a",
                "arcadia",
                "operation-1",
                "sha256:one",
                None,
                &memory_settings,
            )
            .unwrap();
        assert_eq!(
            reserved.worker_id.as_uuid().get_version(),
            Some(uuid::Version::SortRand)
        );
        assert_eq!(reserved.memory_settings.language, "English");
        let reserved_worker = RuntimeWorkerRef::new("arcadia", reserved.worker_id.to_string());
        assert!(
            store
                .has_active_worker_create_reservation("workspace-a", &reserved_worker)
                .unwrap()
        );
        let unchanged_memory_settings = store
            .update_workspace_memory_settings("workspace-a", "English", " English ")
            .unwrap();
        assert_eq!(unchanged_memory_settings, memory_settings);
        let updated_memory_settings = store
            .update_workspace_memory_settings("workspace-a", "English", " Français ")
            .unwrap();
        assert_eq!(updated_memory_settings.language, "Français");
        assert!(matches!(
            store.update_workspace_memory_settings("workspace-a", "English", "Japanese"),
            Err(Error::WorkspaceConfigConflict(_))
        ));
        assert_eq!(
            store
                .get_workspace_memory_settings("workspace-a")
                .unwrap()
                .language,
            "Français"
        );
        assert_eq!(
            store
                .reserve_worker_create(
                    "workspace-a",
                    "arcadia",
                    "operation-1",
                    "sha256:one",
                    None,
                    &updated_memory_settings,
                )
                .unwrap(),
            reserved
        );
        assert!(
            store
                .reserve_worker_create(
                    "workspace-a",
                    "arcadia",
                    "operation-1",
                    "sha256:different",
                    None,
                    &updated_memory_settings,
                )
                .is_err()
        );
        assert_eq!(
            store
                .worker_resource_key("workspace-a", &reserved_worker)
                .unwrap()
                .as_deref(),
            Some("W-1")
        );
        assert_eq!(
            store
                .resolve_worker_resource_reference("workspace-a", "W-1")
                .unwrap(),
            Some(reserved_worker.clone())
        );
        let second = store
            .reserve_worker_create(
                "workspace-a",
                "arcadia",
                "operation-2",
                "sha256:two",
                None,
                &updated_memory_settings,
            )
            .unwrap();
        assert_eq!(
            store
                .worker_resource_key(
                    "workspace-a",
                    &RuntimeWorkerRef::new("arcadia", second.worker_id.to_string()),
                )
                .unwrap()
                .as_deref(),
            Some("W-2")
        );
        store
            .fail_worker_create_reservation(
                "workspace-a",
                "arcadia",
                second.worker_id,
                &second.create_fingerprint,
            )
            .unwrap();
        store
            .fail_worker_create_reservation(
                "workspace-a",
                "arcadia",
                second.worker_id,
                &second.create_fingerprint,
            )
            .unwrap();
        assert!(
            !store
                .has_active_worker_create_reservation(
                    "workspace-a",
                    &RuntimeWorkerRef::new("arcadia", second.worker_id.to_string())
                )
                .unwrap()
        );
        assert_eq!(
            store
                .worker_resource_key(
                    "workspace-a",
                    &RuntimeWorkerRef::new("arcadia", second.worker_id.to_string()),
                )
                .unwrap(),
            None
        );
        assert_eq!(
            store
                .resolve_worker_resource_reference("workspace-a", "W-2")
                .unwrap(),
            None
        );
        let failed_state: String = store
            .with_conn(|conn| {
                conn.query_row(
                    "SELECT state FROM worker_create_reservations \
                     WHERE workspace_id = 'workspace-a' AND worker_id = ?1",
                    [second.worker_id.to_string()],
                    |row| row.get(0),
                )
                .map_err(Error::from)
            })
            .unwrap();
        assert_eq!(failed_state, "removed");
        store
            .complete_worker_create_reservation("workspace-a", reserved.worker_id)
            .unwrap();
        assert!(
            !store
                .has_active_worker_create_reservation("workspace-a", &reserved_worker)
                .unwrap()
        );
        let state: String = store
            .with_conn(|conn| {
                conn.query_row(
                    "SELECT state FROM worker_create_reservations \
                     WHERE workspace_id = 'workspace-a' AND worker_id = ?1",
                    [reserved.worker_id.to_string()],
                    |row| row.get(0),
                )
                .map_err(Error::from)
            })
            .unwrap();
        assert_eq!(state, "created");
        store
            .with_conn(|conn| {
                conn.execute(
                    "INSERT INTO worker_registry (
                        workspace_id, runtime_id, worker_id, display_name,
                        created_at, updated_at, retention_state
                     ) VALUES ('workspace-a', 'arcadia', ?1, 'Worker', '1', '1', 'normal')",
                    [reserved.worker_id.to_string()],
                )?;
                Ok(())
            })
            .unwrap();
        assert!(
            store
                .fail_worker_create_reservation(
                    "workspace-a",
                    "arcadia",
                    reserved.worker_id,
                    &reserved.create_fingerprint,
                )
                .is_err()
        );
        assert!(
            !store
                .delete_worker_registry("workspace-a", &reserved_worker)
                .unwrap()
                .changes
                .is_empty()
        );
        let removed_state: String = store
            .with_conn(|conn| {
                conn.query_row(
                    "SELECT state FROM worker_create_reservations
                     WHERE workspace_id = 'workspace-a' AND worker_id = ?1",
                    [reserved.worker_id.to_string()],
                    |row| row.get(0),
                )
                .map_err(Error::from)
            })
            .unwrap();
        assert_eq!(removed_state, "removed");
        assert!(
            store
                .release_removed_worker_resource_key("workspace-a", reserved.worker_id)
                .unwrap()
        );
        store
            .fail_worker_create_reservation(
                "workspace-a",
                "arcadia",
                reserved.worker_id,
                &reserved.create_fingerprint,
            )
            .unwrap();
        assert_eq!(
            store
                .worker_resource_key("workspace-a", &reserved_worker)
                .unwrap(),
            None
        );
        assert!(
            store
                .reserve_worker_create(
                    "workspace-a",
                    "arcadia",
                    "operation-1",
                    "sha256:one",
                    None,
                    &updated_memory_settings,
                )
                .is_err()
        );

        store
            .with_conn(|conn| {
                conn.execute(
                    "UPDATE workspace_memory_settings SET language = ' English ' \
                     WHERE workspace_id = 'workspace-a'",
                    [],
                )?;
                Ok(())
            })
            .unwrap();
        assert!(store.get_workspace_memory_settings("workspace-a").is_err());
        assert!(
            store
                .update_workspace_memory_settings("workspace-a", "Français", "Spanish")
                .is_err()
        );
        let mut corrupt = updated_memory_settings.clone();
        corrupt.language = " English ".to_string();
        assert!(
            store
                .reserve_worker_create(
                    "workspace-a",
                    "arcadia",
                    "operation-corrupt",
                    "sha256:corrupt",
                    None,
                    &corrupt,
                )
                .is_err()
        );

        store
            .with_conn(|conn| {
                conn.execute(
                    "DELETE FROM workspace_memory_settings WHERE workspace_id = 'workspace-a'",
                    [],
                )?;
                Ok(())
            })
            .unwrap();
        assert!(store.get_workspace_memory_settings("workspace-a").is_err());
    }

    #[tokio::test]
    async fn worker_singleton_restart_retry_replays_exact_workdir_intent_and_rejects_changes() {
        let dir = tempfile::tempdir().unwrap();
        let database = dir.path().join("server.db");
        let store = SqliteWorkspaceStore::open_api_fixture(&database).unwrap();
        store
            .upsert_workspace(&WorkspaceRecord {
                workspace_id: "workspace-a".to_string(),
                owner_account_id: "owner-account".to_string(),
                display_name: "Workspace A".to_string(),
                state: "active".to_string(),
                created_at: "2026-10-01T00:00:00Z".to_string(),
                updated_at: "2026-10-01T00:00:00Z".to_string(),
            })
            .await
            .unwrap();
        let memory = store.get_workspace_memory_settings("workspace-a").unwrap();
        let request = |relative_cwd: Option<&str>| crate::hosts::WorkerSpawnRequest {
            requested_worker_name: Some("Subject Worker".to_string()),
            singleton_key: Some("subjektiv:restart-retry".to_string()),
            intent: crate::hosts::WorkerSpawnIntent::WorkspaceCompanion,
            acceptance: crate::hosts::WorkerSpawnAcceptanceRequirement::RunAccepted {
                expected_segments: 0,
            },
            profile: worker_runtime::catalog::ProfileSelector::Builtin(
                "builtin:companion".to_string(),
            ),
            ticket_assignment: None,
            initial_submit: Vec::new(),
            workdir_attachment_requests: Vec::new(),
            resolved_workdir_attachment_requests: Vec::new(),
            resolved_workdir_attachments: vec![
                worker_runtime::catalog::WorkingDirectoryAttachmentClaim {
                    alias: workdir::WorkdirAttachmentAlias::new("checkout").unwrap(),
                    working_directory_id: "workdir-a".to_string(),
                    relative_cwd: relative_cwd.map(ToOwned::to_owned),
                    capabilities: workdir::WorkdirSessionCapabilities::READ_ONLY,
                },
            ],
            resolved_config_bundle: None,
            resolved_worker_observation_enabled: false,
            resolved_worker_observation_grants: Vec::new(),
            resolved_control_operation: None,
            resolved_execution_grant: None,
            resolved_workspace_api: None,
            resolved_memory_settings: None,
            resolved_subjektiv_attached: false,
        };
        let stable_fingerprint =
            crate::hosts::worker_spawn_create_fingerprint(&request(Some("src"))).unwrap();
        let changed_workdir_fingerprint =
            crate::hosts::worker_spawn_create_fingerprint(&request(Some("tests"))).unwrap();
        assert_ne!(stable_fingerprint, changed_workdir_fingerprint);
        let reserved = store
            .reserve_worker_create(
                "workspace-a",
                "runtime-a",
                "manual:lost-before-dispatch",
                &stable_fingerprint,
                Some("subjektiv:restart-retry"),
                &memory,
            )
            .unwrap();
        drop(store);

        let reopened = SqliteWorkspaceStore::open_for_test(&database).unwrap();
        let retried = reopened
            .reserve_worker_create(
                "workspace-a",
                "runtime-a",
                "manual:new-after-restart",
                &stable_fingerprint,
                Some("subjektiv:restart-retry"),
                &memory,
            )
            .unwrap();
        assert_eq!(retried, reserved);
        let reservation_count: i64 = reopened
            .with_conn(|conn| {
                conn.query_row(
                    "SELECT COUNT(*) FROM worker_create_reservations \
                     WHERE workspace_id = 'workspace-a' AND singleton_key = 'subjektiv:restart-retry'",
                    [],
                    |row| row.get(0),
                )
                .map_err(Error::from)
            })
            .unwrap();
        assert_eq!(reservation_count, 1);
        let conflict = reopened
            .reserve_worker_create(
                "workspace-a",
                "runtime-a",
                "manual:different-request",
                &changed_workdir_fingerprint,
                Some("subjektiv:restart-retry"),
                &memory,
            )
            .unwrap_err();
        assert!(matches!(
            conflict,
            Error::RepositoryConflict(message) if message.contains("worker_singleton_owned")
        ));

        reopened
            .fail_worker_create_reservation(
                "workspace-a",
                "runtime-a",
                reserved.worker_id,
                &reserved.create_fingerprint,
            )
            .unwrap();
        drop(reopened);
        let reopened = SqliteWorkspaceStore::open_for_test(&database).unwrap();
        let conflict = reopened
            .reserve_worker_create(
                "workspace-a",
                "runtime-a",
                "manual:retry-after-terminal-failure",
                &stable_fingerprint,
                Some("subjektiv:restart-retry"),
                &memory,
            )
            .unwrap_err();
        assert!(matches!(conflict, Error::RepositoryConflict(message)
            if message.contains("worker_singleton_release_required")));
        let worker = RuntimeWorkerRef::new("runtime-a", reserved.worker_id.to_string());
        assert!(
            !reopened
                .has_active_worker_create_reservation("workspace-a", &worker)
                .unwrap()
        );
        assert!(
            reopened
                .worker_resource_key("workspace-a", &worker)
                .unwrap()
                .is_none()
        );
        assert_eq!(
            reopened
                .current_worker_singleton_owner("workspace-a", "subjektiv:restart-retry")
                .unwrap(),
            reserved.singleton
        );
    }

    #[tokio::test]
    async fn worker_singleton_ownership_is_workspace_scoped_durable_and_fences_old_generations() {
        let dir = tempfile::tempdir().unwrap();
        let database = dir.path().join("server.db");
        let store = SqliteWorkspaceStore::open_api_fixture(&database).unwrap();
        for workspace_id in ["workspace-a", "workspace-b"] {
            store
                .upsert_workspace(&WorkspaceRecord {
                    workspace_id: workspace_id.to_string(),
                    owner_account_id: "owner-account".to_string(),
                    display_name: workspace_id.to_string(),
                    state: "active".to_string(),
                    created_at: "2026-10-01T00:00:00Z".to_string(),
                    updated_at: "2026-10-01T00:00:00Z".to_string(),
                })
                .await
                .unwrap();
        }
        // Generic singleton lifecycle; Subject-prefixed keys have a separate explicit release contract.
        let key = "fixture:主体 id/?!";
        let memory_a = store.get_workspace_memory_settings("workspace-a").unwrap();
        let first = store
            .reserve_worker_create(
                "workspace-a",
                "runtime-a",
                "operation-a1",
                "sha256:a1",
                Some(key),
                &memory_a,
            )
            .unwrap();
        let first_lease = first.singleton.clone().unwrap();
        assert_eq!(first_lease.key, key);
        assert_eq!(first_lease.generation, 1);
        assert_eq!(
            store
                .reserve_worker_create(
                    "workspace-a",
                    "runtime-a",
                    "operation-a1",
                    "sha256:a1",
                    Some(key),
                    &memory_a,
                )
                .unwrap(),
            first
        );
        let conflict = store
            .reserve_worker_create(
                "workspace-a",
                "runtime-b",
                "operation-a2",
                "sha256:a2",
                Some(key),
                &memory_a,
            )
            .unwrap_err();
        assert!(
            matches!(conflict, Error::RepositoryConflict(message) if message.contains("worker_singleton_owned"))
        );

        // The same opaque key is independent in another Workspace.
        let memory_b = store.get_workspace_memory_settings("workspace-b").unwrap();
        let other_workspace = store
            .reserve_worker_create(
                "workspace-b",
                "runtime-b",
                "operation-b1",
                "sha256:b1",
                Some(key),
                &memory_b,
            )
            .unwrap();
        assert_eq!(other_workspace.singleton.unwrap().generation, 1);

        // A failed launch keeps the key pointing at the failed generation until Runtime absence is
        // confirmed and the reservation becomes terminal. A fresh operation can then replace it.
        store
            .fail_worker_create_reservation(
                "workspace-a",
                "runtime-a",
                first.worker_id,
                &first.create_fingerprint,
            )
            .unwrap();
        assert!(
            store
                .current_worker_singleton_owner("workspace-a", key)
                .unwrap()
                .is_none()
        );
        let replacement = store
            .reserve_worker_create(
                "workspace-a",
                "runtime-b",
                "operation-a3",
                "sha256:a3",
                Some(key),
                &memory_a,
            )
            .unwrap();
        let replacement_lease = replacement.singleton.clone().unwrap();
        assert_eq!(replacement_lease.generation, 2);
        assert!(
            store
                .require_current_worker_singleton_owner("workspace-a", &first_lease.worker)
                .unwrap_err()
                .to_string()
                .contains("worker_singleton_fenced")
        );
        assert_eq!(
            store
                .require_current_worker_singleton_owner("workspace-a", &replacement_lease.worker,)
                .unwrap(),
            Some(replacement_lease.clone())
        );
        drop(store);

        let reopened = SqliteWorkspaceStore::open_for_test(database).unwrap();
        assert_eq!(
            reopened
                .current_worker_singleton_owner("workspace-a", key)
                .unwrap(),
            Some(replacement_lease)
        );
    }

    #[test]
    fn passkey_results_migration_preserves_old_keys_unknown_confirmation_and_rolls_back() {
        for baseline in [50, 102] {
            let dir = tempfile::tempdir().unwrap();
            let database = dir.path().join("server.db");
            if baseline == 50 {
                prepare_schema_v50(&database, None);
            } else {
                prepare_retained_schema(&database, baseline);
            }
            let conn = Connection::open(&database).unwrap();
            configure_sqlite(&conn).unwrap();
            conn.execute_batch(r#"INSERT INTO accounts(account_id, kind, handle, display_name, created_at, updated_at)
                VALUES('account-old', 'user', 'old', 'Old', 'created', 'updated');
                INSERT INTO users(user_id, account_id, handle, display_name, created_at, updated_at)
                VALUES('user-old', 'account-old', 'old', 'Old', 'created', 'updated');
                INSERT INTO passkey_credentials(credential_id, user_id, public_key_cose, transports_json, sign_count, created_at, last_used_at)
                VALUES('old-key', 'user-old', 'unchanged-key-material', '["internal"]', 7, 'created-key', 'used-key');"#)
                .unwrap();
            if baseline == 102 {
                conn.execute_batch("CREATE TRIGGER interrupt_passkey_migration BEFORE INSERT ON __yoi_schema_migrations
                    WHEN NEW.version=103 BEGIN SELECT RAISE(ABORT, 'synthetic migration interruption'); END;").unwrap();
                assert!(migrate_passkey_results_v102_to_v103(&conn).is_err());
                assert_eq!(current_schema_version(&conn).unwrap(), 102);
                assert!(!table_exists(&conn, "passkey_metadata").unwrap());
                assert!(!table_exists(&conn, "passkey_addition_receipts").unwrap());
                conn.execute_batch("DROP TRIGGER interrupt_passkey_migration")
                    .unwrap();
            }
            drop(conn);
            let preflight = SqliteWorkspaceStore::migration_plan(&database).unwrap();
            assert!(preflight.migration_required());
            // Preflight must not install metadata in the source database.
            let conn = Connection::open(&database).unwrap();
            assert!(!table_exists(&conn, "passkey_metadata").unwrap());
            drop(conn);
            let migrated = SqliteWorkspaceStore::open_for_test(&database).unwrap();
            let record = migrated.get_passkey_credential("old-key").unwrap().unwrap();
            assert_eq!(record.public_key_cose, "unchanged-key-material");
            assert_eq!(record.sign_count, 7);
            assert_eq!(record.last_used_at.as_deref(), Some("used-key"));
            let summary = migrated
                .list_passkey_summaries("user-old")
                .unwrap()
                .remove(0);
            assert_eq!(summary.created_at, "created-key");
            assert_eq!(summary.last_used_at.as_deref(), Some("used-key"));
            assert!(summary.normal_login_verified_at.is_none());
            assert_eq!(summary.key_reference.len(), 32);
            let fresh = SqliteWorkspaceStore::in_memory_for_test().unwrap();
            let schema = |conn: &Connection| -> Result<Vec<(String, String)>> {
                let mut stmt = conn.prepare("SELECT name, sql FROM sqlite_schema WHERE name IN
                    ('passkey_metadata', 'passkey_metadata_insert', 'passkey_addition_receipts') ORDER BY name")?;
                Ok(stmt
                    .query_map([], |row| Ok((row.get(0)?, row.get(1)?)))?
                    .collect::<std::result::Result<Vec<_>, _>>()?)
            };
            assert_eq!(
                migrated.with_conn(schema).unwrap(),
                fresh.with_conn(schema).unwrap()
            );
            migrated.with_conn(|conn| {
                assert!(conn.execute("INSERT INTO passkey_metadata(credential_id,key_reference) VALUES('missing-key','ref')", []).is_err());
                assert!(conn.execute("INSERT INTO passkey_addition_receipts(challenge_id,credential_id,user_id,authentication_reference)
                    VALUES('operation','missing-key','user-old','{}')", []).is_err());
                assert_eq!(conn.query_row("SELECT count(*) FROM pragma_foreign_key_check", [], |row| row.get::<_, u64>(0))?, 0);
                Ok(())
            }).unwrap();
            drop(migrated);
            let reopened = SqliteWorkspaceStore::open_for_test(&database).unwrap();
            assert_eq!(
                reopened.list_passkey_summaries("user-old").unwrap(),
                vec![summary]
            );
        }
    }

    #[test]
    fn subject_create_recovery_migration_is_atomic_and_matches_fresh_schema() {
        let dir = tempfile::tempdir().unwrap();
        let database = dir.path().join("server.db");
        prepare_retained_schema(&database, 101);
        let conn = Connection::open(&database).unwrap();
        configure_sqlite(&conn).unwrap();
        conn.execute_batch("CREATE TRIGGER interrupt_create_recovery BEFORE INSERT ON __yoi_schema_migrations WHEN NEW.version=102 BEGIN SELECT RAISE(ABORT,'injected recovery migration interruption'); END;").unwrap();
        assert!(migrate_subject_create_recovery_v101_to_v102(&conn).is_err());
        assert_eq!(current_schema_version(&conn).unwrap(), 101);
        assert!(!table_exists(&conn, "subject_create_recoveries").unwrap());
        conn.execute_batch("DROP TRIGGER interrupt_create_recovery")
            .unwrap();
        migrate_subject_create_recovery_v101_to_v102(&conn).unwrap();
        assert_eq!(current_schema_version(&conn).unwrap(), 102);
        assert!(migrate_subject_create_recovery_v101_to_v102(&conn).is_err());
        let fresh = SqliteWorkspaceStore::in_memory_for_test().unwrap();
        let schema = |c: &Connection| -> Result<String> {
            Ok(c.query_row(
                "SELECT sql FROM sqlite_schema WHERE name='subject_create_recoveries'",
                [],
                |r| r.get::<_, String>(0),
            )?
            .split_whitespace()
            .collect::<Vec<_>>()
            .join(" "))
        };
        assert_eq!(schema(&conn).unwrap(), fresh.with_conn(schema).unwrap());
        assert_eq!(
            conn.query_row("SELECT count(*) FROM pragma_foreign_key_check", [], |r| r
                .get::<_, i64>(
                0
            ))
            .unwrap(),
            0
        );
        drop(conn);
        let reopened = SqliteWorkspaceStore::open_for_test(&database).unwrap();
        reopened
            .with_conn(|c| verify_schema_history(c, LATEST_SCHEMA_VERSION))
            .unwrap();
    }

    #[tokio::test]
    async fn subject_create_recovery_is_durable_exact_and_cannot_release_a_new_generation() {
        for baseline in [None, Some(52), Some(101)] {
            let dir = tempfile::tempdir().unwrap();
            let database = dir.path().join("server.db");
            if let Some(baseline) = baseline {
                prepare_retained_schema(&database, baseline);
            }
            let store = SqliteWorkspaceStore::open_api_fixture(&database).unwrap();
            store
                .upsert_workspace(&WorkspaceRecord {
                    workspace_id: "workspace-a".into(),
                    owner_account_id: "owner-account".into(),
                    display_name: "Workspace A".into(),
                    state: "active".into(),
                    created_at: "2026-10-01T00:00:00Z".into(),
                    updated_at: "2026-10-01T00:00:00Z".into(),
                })
                .await
                .unwrap();
            let memory = store.get_workspace_memory_settings("workspace-a").unwrap();
            let key = "subjektiv:failed-create";
            let first = store
                .reserve_worker_create(
                    "workspace-a",
                    "runtime-a",
                    "manual:first",
                    "sha256:first",
                    Some(key),
                    &memory,
                )
                .unwrap();
            let lease = first.singleton.unwrap();
            let fingerprint = first.create_fingerprint;
            assert_eq!(
                store
                    .subject_create_recovery_candidate("workspace-a", &lease)
                    .unwrap(),
                None
            );
            assert!(
                store
                    .prepare_subject_create_recovery("workspace-a", &lease, "recover-first")
                    .is_err()
            );
            store
                .fail_worker_create_reservation(
                    "workspace-a",
                    "runtime-a",
                    first.worker_id,
                    &fingerprint,
                )
                .unwrap();
            assert_eq!(
                store
                    .subject_create_recovery_candidate("workspace-a", &lease)
                    .unwrap(),
                Some(fingerprint.clone())
            );
            assert!(
                store
                    .prepare_subject_create_recovery("workspace-b", &lease, "recover-first")
                    .is_err()
            );
            for wrong in [
                WorkerSingletonLease {
                    generation: lease.generation + 1,
                    ..lease.clone()
                },
                WorkerSingletonLease {
                    key: "subjektiv:other".into(),
                    ..lease.clone()
                },
                WorkerSingletonLease {
                    worker: RuntimeWorkerRef::new("runtime-b", &lease.worker.worker_id),
                    ..lease.clone()
                },
                WorkerSingletonLease {
                    worker: RuntimeWorkerRef::new("runtime-a", "other-worker"),
                    ..lease.clone()
                },
            ] {
                assert_eq!(
                    store
                        .subject_create_recovery_candidate("workspace-a", &wrong)
                        .unwrap(),
                    None
                );
                assert!(
                    store
                        .prepare_subject_create_recovery("workspace-a", &wrong, "recover-first")
                        .is_err()
                );
            }
            assert!(
                store
                    .complete_subject_create_recovery(
                        "workspace-a",
                        &lease,
                        "recover-first",
                        &fingerprint
                    )
                    .is_err()
            );
            assert_eq!(
                store
                    .prepare_subject_create_recovery("workspace-a", &lease, "recover-first")
                    .unwrap(),
                fingerprint
            );
            assert!(
                store
                    .subject_release_pending("workspace-a", &lease.worker)
                    .unwrap()
            );
            assert_eq!(
                store
                    .current_worker_singleton_owner("workspace-a", key)
                    .unwrap(),
                Some(lease.clone())
            );
            assert!(
                store
                    .reserve_worker_create(
                        "workspace-a",
                        "runtime-a",
                        "manual:retry",
                        "sha256:first",
                        Some(key),
                        &memory
                    )
                    .is_err()
            );
            drop(store);
            let store = SqliteWorkspaceStore::open_for_test(&database).unwrap();
            assert_eq!(
                store
                    .prepare_subject_create_recovery("workspace-a", &lease, "recover-first")
                    .unwrap(),
                fingerprint
            );
            assert!(
                store
                    .prepare_subject_create_recovery("workspace-a", &lease, "different-operation")
                    .is_err()
            );
            assert!(
                store
                    .complete_subject_create_recovery(
                        "workspace-a",
                        &lease,
                        "recover-first",
                        "different-fingerprint"
                    )
                    .is_err()
            );
            assert!(
                store
                    .complete_subject_create_recovery(
                        "workspace-a",
                        &lease,
                        "different-operation",
                        &fingerprint
                    )
                    .is_err()
            );
            assert!(
                store
                    .complete_subject_create_recovery(
                        "workspace-b",
                        &lease,
                        "recover-first",
                        &fingerprint
                    )
                    .is_err()
            );
            // A registry row appearing after prepare must block both replay and completion.
            store.with_conn(|c| {
                c.execute("INSERT INTO worker_registry(workspace_id,runtime_id,worker_id,display_name,retention_state,created_at,updated_at) VALUES('workspace-a',?1,?2,'body','normal','now','now')", params![lease.worker.runtime_id, lease.worker.worker_id])?;
                Ok(())
            }).unwrap();
            assert_eq!(
                store
                    .subject_create_recovery_candidate("workspace-a", &lease)
                    .unwrap(),
                None
            );
            assert!(
                store
                    .prepare_subject_create_recovery("workspace-a", &lease, "recover-first")
                    .is_err()
            );
            assert!(
                store
                    .complete_subject_create_recovery(
                        "workspace-a",
                        &lease,
                        "recover-first",
                        &fingerprint
                    )
                    .is_err()
            );
            store.with_conn(|c| {
                c.execute("DELETE FROM worker_registry WHERE workspace_id='workspace-a' AND runtime_id=?1 AND worker_id=?2", params![lease.worker.runtime_id, lease.worker.worker_id])?;
                // Exercise a current-generation change while the operation is incomplete.
                c.execute("UPDATE worker_singleton_owners SET generation=generation+1 WHERE workspace_id='workspace-a' AND singleton_key=?1", [key])?;
                Ok(())
            }).unwrap();
            assert!(
                store
                    .complete_subject_create_recovery(
                        "workspace-a",
                        &lease,
                        "recover-first",
                        &fingerprint
                    )
                    .is_err()
            );
            assert!(
                store
                    .subject_release_pending("workspace-a", &lease.worker)
                    .unwrap()
            );
            store.with_conn(|c| {
                c.execute("UPDATE worker_singleton_owners SET generation=?2 WHERE workspace_id='workspace-a' AND singleton_key=?1", params![key, lease.generation as i64])?;
                Ok(())
            }).unwrap();
            store
                .complete_subject_create_recovery(
                    "workspace-a",
                    &lease,
                    "recover-first",
                    &fingerprint,
                )
                .unwrap();
            drop(store);
            let store = SqliteWorkspaceStore::open_for_test(&database).unwrap();
            store
                .complete_subject_create_recovery(
                    "workspace-a",
                    &lease,
                    "recover-first",
                    &fingerprint,
                )
                .unwrap();
            assert!(
                !store
                    .subject_release_pending("workspace-a", &lease.worker)
                    .unwrap()
            );
            assert_eq!(
                store
                    .current_worker_singleton_owner("workspace-a", key)
                    .unwrap(),
                None
            );
            let next = store
                .reserve_worker_create(
                    "workspace-a",
                    "runtime-b",
                    "manual:next",
                    "sha256:next",
                    Some(key),
                    &memory,
                )
                .unwrap();
            let next_lease = next.singleton.unwrap();
            assert_eq!(next_lease.generation, lease.generation + 1);
            store
                .complete_subject_create_recovery(
                    "workspace-a",
                    &lease,
                    "recover-first",
                    &fingerprint,
                )
                .unwrap();
            assert!(
                store
                    .prepare_subject_create_recovery("workspace-a", &lease, "recover-first")
                    .is_err()
            );
            assert!(
                store
                    .complete_subject_create_recovery(
                        "workspace-a",
                        &next_lease,
                        "recover-first",
                        &fingerprint
                    )
                    .is_err()
            );
            assert_eq!(
                store
                    .current_worker_singleton_owner("workspace-a", key)
                    .unwrap(),
                Some(next_lease.clone())
            );
            // The old completed proof cannot release the next removed generation.
            store
                .fail_worker_create_reservation(
                    "workspace-a",
                    "runtime-b",
                    next.worker_id,
                    &next.create_fingerprint,
                )
                .unwrap();
            assert_eq!(
                store
                    .current_worker_singleton_owner("workspace-a", key)
                    .unwrap(),
                Some(next_lease.clone())
            );
            assert!(
                store
                    .prepare_subject_create_recovery("workspace-a", &next_lease, "recover-first")
                    .is_err()
            );
            assert_eq!(
                store
                    .prepare_subject_create_recovery("workspace-a", &next_lease, "recover-next")
                    .unwrap(),
                next.create_fingerprint
            );
            store.with_conn(|c| {
                assert_eq!(c.query_row("SELECT count(*) FROM subject_worker_releases", [], |r| r.get::<_, i64>(0))?, 0);
                assert_eq!(c.query_row("SELECT state FROM worker_create_reservations WHERE workspace_id='workspace-a' AND worker_id=?1", [&lease.worker.worker_id], |r| r.get::<_, String>(0))?, "removed");
                assert!(c.execute("UPDATE subject_create_recoveries SET completed=2", []).is_err());
                assert!(c.execute("UPDATE subject_create_recoveries SET singleton_generation=0", []).is_err());
                assert_eq!(c.query_row("SELECT count(*) FROM pragma_foreign_key_check", [], |r| r.get::<_, i64>(0))?, 0);
                Ok(())
            }).unwrap();
        }
    }

    #[test]
    fn subject_release_migration_rolls_back_schema_and_marker_then_reopens() {
        let dir = tempfile::tempdir().unwrap();
        let database = dir.path().join("server.db");
        prepare_retained_schema(&database, 100);
        let conn = Connection::open(&database).unwrap();
        configure_sqlite(&conn).unwrap();
        conn.execute_batch("CREATE TRIGGER interrupt_subject_release_migration BEFORE INSERT ON __yoi_schema_migrations WHEN NEW.version=101 BEGIN SELECT RAISE(ABORT,'injected Subject release migration interruption'); END;").unwrap();
        assert!(migrate_subject_release_v100_to_v101(&conn).is_err());
        assert_eq!(current_schema_version(&conn).unwrap(), 100);
        assert!(!table_exists(&conn, "subject_worker_releases").unwrap());
        conn.execute_batch("DROP TRIGGER interrupt_subject_release_migration")
            .unwrap();
        migrate_subject_release_v100_to_v101(&conn).unwrap();
        assert_eq!(current_schema_version(&conn).unwrap(), 101);
        assert!(table_exists(&conn, "subject_worker_releases").unwrap());
        assert!(migrate_subject_release_v100_to_v101(&conn).is_err());
        drop(conn);
        let reopened = SqliteWorkspaceStore::open_for_test(database).unwrap();
        reopened
            .with_conn(|conn| verify_schema_history(conn, LATEST_SCHEMA_VERSION))
            .unwrap();
    }

    #[tokio::test]
    async fn subject_generic_removal_retains_occupancy_until_exact_explicit_release_receipt() {
        let dir = tempfile::tempdir().unwrap();
        let database = dir.path().join("server.db");
        let store = SqliteWorkspaceStore::open_api_fixture(&database).unwrap();
        store
            .upsert_workspace(&WorkspaceRecord {
                workspace_id: "workspace-a".into(),
                owner_account_id: "owner-account".into(),
                display_name: "Workspace A".into(),
                state: "active".into(),
                created_at: "2026-10-01T00:00:00Z".into(),
                updated_at: "2026-10-01T00:00:00Z".into(),
            })
            .await
            .unwrap();
        let memory = store.get_workspace_memory_settings("workspace-a").unwrap();
        let key = "subjektiv:subject-a";
        let first = store
            .reserve_worker_create(
                "workspace-a",
                "runtime-a",
                "first",
                "sha256:first",
                Some(key),
                &memory,
            )
            .unwrap();
        let lease = first.singleton.unwrap();
        store
            .fail_worker_create_reservation(
                "workspace-a",
                "runtime-a",
                first.worker_id,
                &first.create_fingerprint,
            )
            .unwrap();
        assert_eq!(
            store
                .current_worker_singleton_owner("workspace-a", key)
                .unwrap(),
            Some(lease.clone())
        );
        assert!(
            store
                .reserve_worker_create(
                    "workspace-a",
                    "runtime-b",
                    "early",
                    "sha256:early",
                    Some(key),
                    &memory
                )
                .is_err()
        );
        store
            .reserve_subject_release("workspace-a", &lease, "binding-a", "cancelled-first")
            .unwrap();
        assert!(
            store
                .subject_release_pending("workspace-a", &lease.worker)
                .unwrap()
        );
        store
            .cancel_subject_release("workspace-a", &lease, "binding-a", "cancelled-first")
            .unwrap();
        assert!(
            !store
                .subject_release_pending("workspace-a", &lease.worker)
                .unwrap()
        );
        assert!(
            store
                .reserve_subject_release("workspace-a", &lease, "binding-a", "cancelled-first")
                .is_err()
        );
        store
            .reserve_subject_release("workspace-a", &lease, "binding-a", "release-a")
            .unwrap();
        drop(store);
        let reopened = SqliteWorkspaceStore::open_for_test(&database).unwrap();
        assert_eq!(
            reopened
                .current_worker_singleton_owner("workspace-a", key)
                .unwrap(),
            Some(lease.clone())
        );
        assert!(
            reopened
                .reserve_subject_release("workspace-a", &lease, "binding-later", "release-a")
                .is_err()
        );
        // SQL component boundary: the Host's actual Controller and durable writer-revoke proof
        // are tested at their integration boundaries, not certified by this private SQL helper.
        assert!(
            reopened
                .release_subject_singleton("workspace-a", &lease, "binding-a", "release-a")
                .is_err()
        );
        reopened
            .confirm_subject_release_proof("workspace-a", &lease, "binding-a", "release-a", false)
            .unwrap();
        reopened
            .release_subject_singleton("workspace-a", &lease, "binding-a", "release-a")
            .unwrap();
        assert!(
            reopened
                .current_worker_singleton_owner("workspace-a", key)
                .unwrap()
                .is_none()
        );
        let replacement = reopened
            .reserve_worker_create(
                "workspace-a",
                "runtime-b",
                "next",
                "sha256:next",
                Some(key),
                &memory,
            )
            .unwrap();
        assert_eq!(
            replacement.singleton.unwrap().generation,
            lease.generation + 1
        );
        reopened
            .release_subject_singleton("workspace-a", &lease, "binding-a", "release-a")
            .unwrap();
        assert!(
            reopened
                .release_subject_singleton(
                    "workspace-a",
                    &lease,
                    "binding-a",
                    "different-operation"
                )
                .is_err()
        );
        assert!(
            reopened
                .require_current_worker_singleton_owner("workspace-a", &lease.worker)
                .is_err()
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn concurrent_worker_singleton_reservations_have_one_winner() {
        let dir = tempfile::tempdir().unwrap();
        let database = dir.path().join("server.db");
        let store = SqliteWorkspaceStore::open_api_fixture(&database).unwrap();
        store
            .upsert_workspace(&WorkspaceRecord {
                workspace_id: "workspace-a".to_string(),
                owner_account_id: "owner-account".to_string(),
                display_name: "Workspace A".to_string(),
                state: "active".to_string(),
                created_at: "2026-10-01T00:00:00Z".to_string(),
                updated_at: "2026-10-01T00:00:00Z".to_string(),
            })
            .await
            .unwrap();
        drop(store);

        let barrier = Arc::new(std::sync::Barrier::new(2));
        let handles = (0..2)
            .map(|index| {
                let database = database.clone();
                let barrier = barrier.clone();
                std::thread::spawn(move || {
                    let store = SqliteWorkspaceStore::open_for_test(database).unwrap();
                    let memory = store.get_workspace_memory_settings("workspace-a").unwrap();
                    barrier.wait();
                    store.reserve_worker_create(
                        "workspace-a",
                        if index == 0 { "runtime-a" } else { "runtime-b" },
                        &format!("operation-{index}"),
                        &format!("sha256:{index}"),
                        Some("shared-key"),
                        &memory,
                    )
                })
            })
            .collect::<Vec<_>>();
        let results = handles
            .into_iter()
            .map(|handle| handle.join().unwrap())
            .collect::<Vec<_>>();
        assert_eq!(results.iter().filter(|result| result.is_ok()).count(), 1);
        assert_eq!(results.iter().filter(|result| result.is_err()).count(), 1);
        let store = SqliteWorkspaceStore::open_for_test(database).unwrap();
        let owner = store
            .current_worker_singleton_owner("workspace-a", "shared-key")
            .unwrap()
            .unwrap();
        assert!(
            results
                .into_iter()
                .flatten()
                .any(|reservation| { reservation.worker_id.to_string() == owner.worker.worker_id })
        );
    }

    #[tokio::test]
    async fn workspace_flow_sources_pin_content_and_builtins_stay_resources() {
        let dir = tempfile::tempdir().unwrap();
        let store = SqliteWorkspaceStore::open_api_fixture(dir.path().join("server.db")).unwrap();
        store
            .upsert_workspace(&WorkspaceRecord {
                workspace_id: "workspace-a".to_string(),
                owner_account_id: "owner-account".to_string(),
                display_name: "Workspace A".to_string(),
                state: "active".to_string(),
                created_at: "2026-08-06T00:00:00Z".to_string(),
                updated_at: "2026-08-06T00:00:00Z".to_string(),
            })
            .await
            .unwrap();
        let workspace_source = r#"{
            schema_version = 1;
            name = "coder-review";
            initial = "work";
            states = {
                work = {
                    instructions = "Workspace initial content.";
                    transitions = { done = { target = "done"; condition = "Done."; }; };
                };
                done = { instructions = ""; terminal = true; };
            };
        }"#;
        let workspace = store
            .put_flow_source_for_kind(
                "workspace-a",
                FlowSourceKind::Workspace,
                "flows/coder-review.dcdl",
                workspace_source,
                "2026-08-06T00:00:01Z",
            )
            .unwrap();
        let builtin = flow::builtin_flow_source("coder-review").unwrap();
        assert_eq!(builtin.slug, workspace.name);
        assert!(
            store
                .put_flow_source_for_kind(
                    "workspace-a",
                    FlowSourceKind::Builtin,
                    builtin.path,
                    builtin.content,
                    "2026-08-06T00:00:02Z",
                )
                .is_err()
        );
        assert_eq!(
            store.list_flow_sources("workspace-a").unwrap(),
            vec![workspace.clone()]
        );

        let changed_content =
            workspace_source.replace("Workspace initial content.", "Workspace changed content.");
        let updated = store
            .put_flow_source_for_kind(
                "workspace-a",
                FlowSourceKind::Workspace,
                "flows/coder-review.dcdl",
                &changed_content,
                "2026-08-06T00:00:03Z",
            )
            .unwrap();
        assert_eq!(updated.flow_id, workspace.flow_id);
        assert_ne!(updated.content_digest, workspace.content_digest);
        let pinned = store
            .get_flow_source_content("workspace-a", &workspace.flow_id, &workspace.content_digest)
            .unwrap()
            .unwrap();
        assert_eq!(pinned.content, workspace_source);
        assert_eq!(pinned.definition.name, "coder-review");
        let restored = store
            .put_flow_source_for_kind(
                "workspace-a",
                FlowSourceKind::Workspace,
                "flows/coder-review.dcdl",
                workspace_source,
                "2026-08-06T00:00:04Z",
            )
            .unwrap();
        assert_eq!(restored.content_digest, workspace.content_digest);
        let count: i64 = store
            .with_conn(|conn| {
                Ok(conn.query_row(
            "SELECT COUNT(*) FROM flow_source_contents WHERE workspace_id=?1 AND flow_id=?2",
            params!["workspace-a", workspace.flow_id], |row| row.get(0),
        )?)
            })
            .unwrap();
        assert_eq!(
            count, 2,
            "returning to earlier content must reuse the immutable content"
        );
        drop(store);
        let reopened = SqliteWorkspaceStore::open_for_test(dir.path().join("server.db")).unwrap();
        assert_eq!(
            reopened
                .get_flow_source_content(
                    "workspace-a",
                    &workspace.flow_id,
                    &workspace.content_digest
                )
                .unwrap()
                .unwrap()
                .content,
            workspace_source
        );
    }

    // SQLite boundary: genuine retained Workspace-89 or -90 / Ticket-7,
    // including the real authentication cutover, not a lowered version marker.
    fn legacy_case_workspace(version: i64) -> (tempfile::TempDir, std::path::PathBuf) {
        assert!(matches!(version, 89 | 90));
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("cases.db");
        prepare_retained_schema(&path, 89);
        let conn = Connection::open(&path).unwrap();
        configure_sqlite(&conn).unwrap();
        conn.execute_batch("INSERT INTO accounts(account_id,kind,handle,display_name,created_at,updated_at)
            VALUES('case-owner','user','case-owner','Owner','1','1');
            INSERT INTO workspaces(workspace_id,owner_account_id,display_name,state,created_at,updated_at)
            VALUES('case-workspace','case-owner','Cases','active','1','1');
            INSERT INTO repositories(workspace_id,repository_id,repository_key,kind,provider,uri,default_ref,created_at,updated_at,source_kind,source_uri,source_fingerprint,observed_status)
            VALUES('case-workspace','case-repo','main','git','git','/fixture','develop','1','1','local_path','/fixture','sha256:fixture','unverified');").unwrap();
        conn.execute_batch(r#"
            INSERT INTO workspace_signing_identities(workspace_id,key_id,algorithm,public_key,public_key_fingerprint,private_material_ref,state,created_at,provisioned_at,updated_at)
                VALUES('case-workspace','case-key','ed25519','workspace-public-key','workspace-fingerprint','private-material','active','1','2','2');
            INSERT INTO workspace_signing_identity_provisioning_operations(operation_key,request_fingerprint,operation_kind,workspace_id,key_id,private_material_ref,actor_account_id,state,created_at,completed_at)
                VALUES('case-provision','original-provision','existing_workspace','case-workspace','case-key','private-material','case-owner','completed','1','2');
            INSERT INTO workspace_signing_identity_audit(event_id,workspace_id,key_id,action,public_key_fingerprint,actor_account_id,created_at)
                VALUES('case-key-audit','case-workspace','case-key','provisioned','workspace-fingerprint','case-owner','2');
            INSERT INTO workspace_runtime_bindings(workspace_id,runtime_id,display_name,base_url,public_key,public_key_fingerprint,binding_id,state,authentication_mode,workspace_key_id,workspace_public_key_fingerprint,workspace_trust_id,created_at,updated_at)
                VALUES('case-workspace','case-runtime','Verified runtime','https://runtime.invalid','runtime-public-key','runtime-fingerprint','case-binding','verified','workspace_identity','case-key','workspace-fingerprint','case-trust','1','2'),
                      ('case-workspace','legacy-runtime','Legacy runtime','https://legacy.invalid','legacy-public-key','legacy-fingerprint','legacy-binding','configured','legacy_server_issuer',NULL,NULL,NULL,'1','2');
            INSERT INTO workspace_runtime_verifications(workspace_id,runtime_id,binding_id,workspace_key_id,workspace_public_key_fingerprint,workspace_trust_id,runtime_public_key_fingerprint,challenge_id,state,last_outcome,verified_at,checked_at)
                VALUES('case-workspace','case-runtime','case-binding','case-key','workspace-fingerprint','case-trust','runtime-fingerprint','case-challenge','verified','original-verification','2','2');
            INSERT INTO workspace_runtime_binding_audit(workspace_id,runtime_id,actor_account_id,action,old_fingerprint,new_fingerprint,binding_id,at)
                VALUES('case-workspace','case-runtime','case-owner','created',NULL,'runtime-fingerprint','case-binding','1');
        "#).unwrap();
        if version == 90 {
            migrate_runtime_binding_connections_v89_to_v90(&conn).unwrap();
            verify_runtime_binding_connection_schema(&conn).unwrap();
        }
        assert_eq!(current_schema_version(&conn).unwrap(), version);
        assert_eq!(
            conn.query_row(
                "SELECT MAX(version) FROM ticket_schema_migrations",
                [],
                |row| row.get::<_, i64>(0)
            )
            .unwrap(),
            7
        );
        verify_workspace_resource_constraints(&conn).unwrap();
        (dir, path)
    }

    fn stored_fixture_rows(conn: &Connection, table: &str) -> Vec<Vec<rusqlite::types::Value>> {
        // Compare preserved original assignment evidence, not newly added tracking columns.
        if table == "typed_ticket_events" {
            return fixture_query_rows(
                conn,
                "SELECT workspace_id,ticket_id,event_index,kind,author,at,status,from_state,to_state,reason,state_field,heading,body FROM typed_ticket_events WHERE event_index >= 0 ORDER BY rowid",
            );
        }
        let columns = if table == "ticket_worker_assignments" {
            "workspace_id,ticket_id,assignment_id,role,principal_kind,principal_id,runtime_id,worker_id,assigned_by,assigned_at"
        } else {
            "*"
        };
        fixture_query_rows(
            conn,
            &format!("SELECT {columns} FROM {table} ORDER BY rowid"),
        )
    }

    fn fixture_query_rows(conn: &Connection, sql: &str) -> Vec<Vec<rusqlite::types::Value>> {
        let mut stmt = conn.prepare(sql).unwrap();
        let columns = stmt.column_count();
        stmt.query_map([], |row| (0..columns).map(|i| row.get(i)).collect())
            .unwrap()
            .collect::<rusqlite::Result<_>>()
            .unwrap()
    }

    // Project schema-89 live conclusions into the exact frozen archive layout.
    // At schema 90+ the same values must already be historical, never live auth.
    fn fixture_auth_rows(conn: &Connection) -> Vec<Vec<Vec<rusqlite::types::Value>>> {
        let (binding_evidence, verification_evidence) = if current_schema_version(conn).unwrap()
            == 89
        {
            (
                "SELECT workspace_id,runtime_id,binding_id,state,workspace_key_id,workspace_public_key_fingerprint,workspace_trust_id,updated_at FROM workspace_runtime_bindings ORDER BY runtime_id",
                "SELECT * FROM workspace_runtime_verifications ORDER BY runtime_id",
            )
        } else {
            (
                "SELECT * FROM workspace_runtime_binding_verification_archive ORDER BY runtime_id",
                "SELECT * FROM workspace_runtime_verification_archive ORDER BY runtime_id",
            )
        };
        ["SELECT workspace_id,runtime_id,display_name,base_url,public_key,public_key_fingerprint,binding_id,authentication_mode,created_at,updated_at,revoked_at FROM workspace_runtime_bindings ORDER BY runtime_id", binding_evidence, verification_evidence]
            .map(|sql| fixture_query_rows(conn, sql)).to_vec()
    }

