    #[test]
    fn schema_v90_cases_preserve_auth_archive_legacy_states_evidence_and_responsibility() {
        assert_legacy_cases_preserved(90);
    }

    fn assert_legacy_cases_preserved(version: i64) {
        use ticket::TicketBackend;
        let (_dir, path) = legacy_case_workspace(version);
        let conn = Connection::open(&path).unwrap();
        configure_sqlite(&conn).unwrap();
        for state in [
            "planning",
            "ready",
            "queued",
            "inprogress",
            "done",
            "closed",
        ] {
            for has_mr in [false, true] {
                let id = format!("{state}-{has_mr}");
                conn.execute("INSERT INTO typed_tickets(workspace_id,ticket_id,slug,title,status,kind,priority,body,workflow_state,workflow_state_explicit,queued_by,queued_at,resolution,readiness,assignee,created_at,updated_at)
                    VALUES('case-workspace',?1,?1,?1,?2,'task','P2','Original requirements',?3,1,?4,?5,'Original closure text','legacy-readiness','legacy-assignee','1','2')",
                    params![id, if matches!(state,"done"|"closed") { "closed" } else { "open" }, state,
                        (state=="queued").then_some("queue-author"), (state=="queued").then_some("queue-time")]).unwrap();
                conn.execute("INSERT INTO worker_registry(workspace_id,runtime_id,worker_id,display_name,retention_state,created_at,updated_at)
                    VALUES('case-workspace','case-runtime',?1,?1,'normal','1','1')", [&id]).unwrap();
                conn.execute("INSERT INTO ticket_worker_assignments(workspace_id,ticket_id,assignment_id,role,principal_kind,runtime_id,worker_id,assigned_by,assigned_at)
                    VALUES('case-workspace',?1,?1,'worker','worker','case-runtime',?1,'original-actor','1')", [&id]).unwrap();
                conn.execute("INSERT INTO ticket_current_worker_assignments(workspace_id,ticket_id,assignment_id,role,principal_kind,runtime_id,worker_id,updated_at)
                    VALUES('case-workspace',?1,?1,'worker','worker','case-runtime',?1,'1')", [&id]).unwrap();
                conn.execute("INSERT INTO ticket_worker_assignment_events(workspace_id,ticket_id,event_id,assignment_id,role,action,actor,created_at,operation_id)
                    VALUES('case-workspace',?1,?1,?1,'worker','assigned','original-actor','1',?1)", [&id]).unwrap();
                conn.execute("INSERT INTO ticket_assignment_operations(workspace_id,operation_id,action,ticket_id,role,runtime_id,worker_id,assignment_id,created_at,request_fingerprint,claim_state)
                    VALUES('case-workspace',?1,'assign',?1,'worker','case-runtime',?1,?1,'1','original-claim','committed')", [&id]).unwrap();
                conn.execute("INSERT INTO typed_ticket_events(workspace_id,ticket_id,event_index,kind,author,at,from_state,to_state,reason,state_field,heading,body)
                    VALUES('case-workspace',?1,0,'state_changed','original-author','1','planning',?2,'Original decision','state','Original heading','Original thread')", params![id,state]).unwrap();
                conn.execute("INSERT INTO typed_ticket_event_attributes(workspace_id,ticket_id,event_index,key,value)
                    VALUES('case-workspace',?1,0,'operation_key','original-operation')", [&id]).unwrap();
                conn.execute("INSERT INTO typed_ticket_event_references(workspace_id,ticket_id,event_index,ordinal,kind,target)
                    VALUES('case-workspace',?1,0,0,'commit','original-ref')", [&id]).unwrap();
                conn.execute("INSERT INTO typed_ticket_artifacts(workspace_id,ticket_id,relative_path,content)
                    VALUES('case-workspace',?1,'original.txt',?2)", params![id,b"original artifact".as_slice()]).unwrap();
                if has_mr {
                    conn.execute("INSERT INTO typed_ticket_targets(workspace_id,ticket_id,ordinal,repository_key,ref_selector,access)
                        VALUES('case-workspace',?1,0,'main','develop','read_write')", [&id]).unwrap();
                    conn.execute("INSERT INTO merge_requests(workspace_id,merge_request_id,repository_id,state,selector_from,selector_to,created_at,updated_at)
                        VALUES('case-workspace',?1,'case-repo','merged','work/original','develop','1','2')", [&id]).unwrap();
                    conn.execute("INSERT INTO merge_request_ticket_relations(workspace_id,merge_request_id,ticket_id,relation_kind,created_at)
                        VALUES('case-workspace',?1,?1,'implements','1')", [&id]).unwrap();
                    let evidence = merge_request::MergeEvent {
                        event_id: id.clone(),
                        sequence: 1,
                        operation_id: id.clone(),
                        approval_event_id: "original-approval".into(),
                        approved_source_ref: "original-source".into(),
                        target_ref_before: "original-target".into(),
                        target_ref_after: "original-result".into(),
                        strategy: merge_request::MergeStrategy::FastForward,
                        resolution: merge_request::ConflictResolution::None,
                        merged_by: merge_request::WorkerIdentity {
                            runtime_id: "original-runtime".into(),
                            worker_id: "original-orchestrator".into(),
                        },
                        created_at: chrono::DateTime::parse_from_rfc3339("2026-01-01T00:00:00Z")
                            .unwrap()
                            .with_timezone(&chrono::Utc),
                    };
                    conn.execute("INSERT INTO merge_request_thread_events(workspace_id,merge_request_id,event_id,sequence,kind,payload_json,operation_id,created_at)
                        VALUES('case-workspace',?1,?1,1,'merge',?2,?1,'2')", params![id,serde_json::to_string(&evidence).unwrap()]).unwrap();
                }
            }
        }
        conn.execute_batch("INSERT INTO worker_control_grants(workspace_id,grant_id,controller_runtime_id,controller_worker_id,subject_runtime_id,subject_worker_id,relation,origin,permissions_json,operation_id,created_at)
            VALUES('case-workspace','original-control','case-runtime','planning-false','case-runtime','closed-true','ticket','user','[\"stop\",\"observe\"]','original-grant','1');
            INSERT INTO worker_restore_intents(workspace_id,runtime_id,worker_id,domain_key,request_id,expected_token,settled)
            VALUES('case-workspace','case-runtime','closed-true','original-domain','original-restore','original-token',0);
            INSERT INTO workdir_registry(workspace_id,workdir_id,source_kind,runtime_id,repository_id,creation_selector,creation_ref,materialization_status,cleanliness,created_at,updated_at)
            VALUES('case-workspace','original-workdir','repository','case-runtime','case-repo','develop','original-ref','present','clean','1','1');
            INSERT INTO worker_workdir_links(workspace_id,runtime_id,worker_id,workdir_id,alias,capabilities,connection_id,linked_at)
            VALUES('case-workspace','case-runtime','closed-true','original-workdir','checkout','all','original-connection','1');").unwrap();
        // Queued intent with and without a pending claim must survive, but no
        // assignment, Worker create/restore or grant is synthesized by migration.
        for id in ["pending-queue", "only-queue"] {
            conn.execute("INSERT INTO typed_tickets(workspace_id,ticket_id,slug,title,status,kind,priority,body,workflow_state,workflow_state_explicit,queued_by,queued_at)
                VALUES('case-workspace',?1,?1,?1,'open','task','P2','','queued',1,'queue-author','queue-time')", [id]).unwrap();
        }
        conn.execute("INSERT INTO worker_registry(workspace_id,runtime_id,worker_id,display_name,retention_state,created_at,updated_at)
            VALUES('case-workspace','case-runtime','pending-worker','Pending','normal','1','1')", []).unwrap();
        conn.execute("INSERT INTO ticket_assignment_operations(workspace_id,operation_id,action,ticket_id,role,runtime_id,worker_id,created_at,request_fingerprint,claim_state)
            VALUES('case-workspace','pending-claim','assign','pending-queue','worker','case-runtime','pending-worker','1','pending-fingerprint','pending')", []).unwrap();
        // Compose real retained Ticket8 classification data across the full
        // six-state × MR matrix, before either auth90 or case91 runs.
        install_retained_ticket_tags8(&conn);
        let retained_tags = seed_retained_classification(&conn, "case-workspace", "done-true");
        conn.execute("INSERT OR IGNORE INTO typed_ticket_tags(workspace_id,ticket_id,tag_id)
            SELECT workspace_id,ticket_id,?1 FROM typed_tickets WHERE workspace_id='case-workspace'",
            [&retained_tags.active_ids[0]]).unwrap();
        let unchanged = [
            "workspace_tags",
            "typed_ticket_tags",
            "workspace_tag_operations",
            "typed_ticket_labels",
            "typed_ticket_events",
            "typed_ticket_event_attributes",
            "typed_ticket_event_references",
            "typed_ticket_artifacts",
            "typed_ticket_targets",
            "ticket_worker_assignments",
            "ticket_current_worker_assignments",
            "ticket_worker_assignment_events",
            "ticket_assignment_operations",
            "worker_registry",
            "worker_create_reservations",
            "worker_restore_intents",
            "workdir_registry",
            "worker_workdir_links",
            "worker_control_grants",
            "merge_requests",
            "merge_request_ticket_relations",
            "merge_request_thread_events",
            "workspace_runtime_binding_audit",
            "workspace_signing_identities",
            "workspace_signing_identity_audit",
            "workspace_signing_identity_provisioning_operations",
        ];
        let before = unchanged.map(|table| stored_fixture_rows(&conn, table));
        let auth_before = fixture_auth_rows(&conn);
        assert_eq!(
            auth_before.iter().map(Vec::len).collect::<Vec<_>>(),
            [2, 2, 1]
        );
        let plan = SqliteWorkspaceStore::migration_plan(&path).unwrap();
        assert_eq!(plan.current_schema_version, version);
        assert_eq!(plan.target_schema_version, LATEST_SCHEMA_VERSION);
        assert_eq!(
            plan.migrations
                .iter()
                .map(|step| step.version)
                .collect::<Vec<_>>(),
            ((version + 1)..=LATEST_SCHEMA_VERSION).collect::<Vec<_>>()
        );
        drop(conn);
        let store = SqliteWorkspaceStore::open_for_test(&path).unwrap();
        let backend = ticket::SqliteTicketBackend::open_verified(&path, "case-workspace").unwrap();
        store
            .with_conn(|conn| {
                assert_eq!(current_schema_version(conn)?, LATEST_SCHEMA_VERSION);
                assert_eq!(fixture_auth_rows(conn), auth_before);
                verify_runtime_binding_connection_schema(conn)?;
                ticket::verify_sqlite_ticket_schema(conn).unwrap();
                assert_eq!(workspace_schema_migration_history(conn)?.into_iter().filter(|(version, _)| *version >= 90).collect::<Vec<_>>(),
                    vec![(90, "Runtime binding connection configuration and historical verification archive".into()),
                         (91, "Ticket open/closed cases and retained routing evidence".into()),
                         (92, "Ticket-owned assignment tracking".into()),
                         (93, "Durable assignment deliveries and source-bound startup fences".into()),
                         (94, "Canonical Ticket posts".into()),
                         (95, "Common notification routing and durable Worker delivery".into()),
                         (96, "Backend Job common notification routing".into()),
                         (97, "MR notifications and authenticated implementation results".into()),
                         (98, "Assignment-independent implementation reports".into()),
                         (99, "Explicit hosting administrators and self-registration policy".into()),
                         (100, "Provisional users and scoped passkey activation".into()),
                         (101, "Durable explicit Subject body release".into()),
                         (102, "Durable failed Subject creation recovery".into()),
                         (103, "Passkey metadata and atomic addition results".into()),
                         (104, "Converge Passkey results and Job input retention".into()),
                         (105, "Durable Subject deletion snapshots and Job admission fences".into()),
                         (106, crate::plugin_catalog::MIGRATION_NAME.into()),
                         (107, "Immutable Worker Plugin plans and retained pins".into()),
                         (108, "Subject Ticket responsibility and current-body notification routing".into()),
                         (109, "Durable Plugin Host invocations and HTTPS effect receipts".into()),
                         (110, "Worker Plugin launch selection associations".into())]);
                for (table, rows) in unchanged.iter().zip(before.iter()) {
                    assert_eq!(&stored_fixture_rows(conn, table), rows, "preserve {table}");
                }
                assert_eq!(
                    conn.query_row(
                        "SELECT COUNT(*) FROM ticket_assignment_work_releases",
                        [],
                        |row| row.get::<_, i64>(0)
                    )?,
                    4
                );
                assert_eq!(
                    conn.query_row(
                        "SELECT COUNT(*) FROM ticket_active_worker_assignments",
                        [],
                        |row| row.get::<_, i64>(0)
                    )?,
                    8
                );
                assert_eq!(
                    conn.query_row("SELECT COUNT(*) FROM pragma_foreign_key_check", [], |row| {
                        row.get::<_, i64>(0)
                    })?,
                    0
                );
                Ok(())
            })
            .unwrap();
        for state in [
            "planning",
            "ready",
            "queued",
            "inprogress",
            "done",
            "closed",
        ] {
            for has_mr in [false, true] {
                let id = format!("{state}-{has_mr}");
                let ticket = backend.show(id.clone().into()).unwrap();
                assert!(!ticket.tags.is_empty(), "matrix classification {id}");
                assert_eq!(ticket.document.body.as_str(), "Original requirements");
                let snapshot = ticket.legacy_workflow_snapshot.as_ref().unwrap();
                assert_eq!(snapshot.workflow_state, state);
                assert_eq!(
                    snapshot.queued_by.as_deref(),
                    (state == "queued").then_some("queue-author")
                );
                assert_eq!(
                    snapshot.queued_at.as_deref(),
                    (state == "queued").then_some("queue-time")
                );
                assert_eq!(
                    snapshot.resolution.as_deref(),
                    Some("Original closure text")
                );
                assert_eq!(ticket.meta.assignee.as_deref(), Some("legacy-assignee"));
                if matches!(state, "done" | "closed") {
                    assert_eq!(ticket.meta.workflow_state, ticket::TicketState::Closed);
                    assert_eq!(
                        ticket.current_closure.as_ref().unwrap().reason,
                        ticket::TicketClosureReason::Unknown,
                        "MR evidence does not infer fulfillment"
                    );
                    assert_eq!(ticket.case_history.len(), 1);
                    let reopened = update_test_case(
                        &backend,
                        &id,
                        &format!("reopen-{id}"),
                        ticket::TicketCaseAction::Reopen,
                    );
                    assert_eq!(reopened.meta.workflow_state, ticket::TicketState::Open);
                    assert_eq!(reopened.case_history.len(), 2);
                    assert_eq!(reopened.case_history[0], ticket.case_history[0]);
                    assert_eq!(reopened.tags, ticket.tags);
                    assert_eq!(
                        reopened
                            .events
                            .iter()
                            .filter(|event| event.kind == ticket::TicketEventKind::TagsChanged)
                            .collect::<Vec<_>>(),
                        ticket
                            .events
                            .iter()
                            .filter(|event| event.kind == ticket::TicketEventKind::TagsChanged)
                            .collect::<Vec<_>>()
                    );
                    assert!(
                        store
                            .get_active_ticket_worker_assignment("case-workspace", &id)
                            .unwrap()
                            .is_none()
                    );
                    assert_eq!(
                        store
                            .get_current_ticket_worker_assignment("case-workspace", &id)
                            .unwrap()
                            .unwrap()
                            .assignment_id,
                        id
                    );
                    assert!(
                        store
                            .delete_worker_registry(
                                "case-workspace",
                                &RuntimeWorkerRef::new("case-runtime", &id)
                            )
                            .is_ok()
                    );
                } else {
                    assert_eq!(ticket.meta.workflow_state, ticket::TicketState::Open);
                    assert!(ticket.case_history.is_empty());
                    assert!(
                        store
                            .delete_worker_registry(
                                "case-workspace",
                                &RuntimeWorkerRef::new("case-runtime", &id)
                            )
                            .is_err()
                    );
                }
            }
        }
        for id in ["pending-queue", "only-queue"] {
            let queued = backend.show(id.into()).unwrap();
            assert_eq!(queued.meta.workflow_state, ticket::TicketState::Open);
            let snapshot = queued.legacy_workflow_snapshot.unwrap();
            assert_eq!(snapshot.workflow_state, "queued");
            assert_eq!(snapshot.queued_by.as_deref(), Some("queue-author"));
            assert_eq!(snapshot.queued_at.as_deref(), Some("queue-time"));
            assert!(queued.case_history.is_empty());
        }
        assert!(
            store
                .get_current_ticket_worker_assignment("case-workspace", "only-queue")
                .unwrap()
                .is_none()
        );
        assert!(
            store
                .get_active_ticket_worker_assignment("case-workspace", "pending-queue")
                .unwrap()
                .is_none()
        );
        let pending = store
            .get_ticket_assignment_operation("case-workspace", "pending-claim")
            .unwrap()
            .unwrap();
        assert_eq!(pending.claim_state, "pending");
        assert_eq!(
            pending.request_fingerprint.as_deref(),
            Some("pending-fingerprint")
        );
        drop(store);
        drop(backend);
        let reopened = SqliteWorkspaceStore::open_for_test(&path).unwrap();
        reopened
            .with_conn(|conn| {
                assert_eq!(current_schema_version(conn)?, LATEST_SCHEMA_VERSION);
                assert_eq!(fixture_auth_rows(conn), auth_before);
                Ok(())
            })
            .unwrap();
        let backend = ticket::SqliteTicketBackend::open_verified(&path, "case-workspace").unwrap();
        let reopened_case = backend.show("done-true".into()).unwrap();
        assert_eq!(reopened_case.meta.workflow_state, ticket::TicketState::Open);
        assert_eq!(reopened_case.case_history.len(), 2);
        assert_eq!(
            reopened_case.case_history[0].action,
            ticket::TicketCaseAction::Close {
                reason: ticket::TicketClosureReason::Unknown
            }
        );
        assert!(
            reopened
                .get_active_ticket_worker_assignment("case-workspace", "done-true")
                .unwrap()
                .is_none()
        );
        assert_eq!(
            reopened
                .get_ticket_assignment_operation("case-workspace", "pending-claim")
                .unwrap()
                .unwrap(),
            pending
        );
    }

    #[test]
    fn schema_v91_resumes_after_shared_ticket_migration_without_duplicating_judgments() {
        use ticket::TicketBackend;
        let (_dir, path) = legacy_case_workspace(90);
        let conn = Connection::open(&path).unwrap();
        configure_sqlite(&conn).unwrap();
        // Keep the collision table valid for dependent triggers during the shared
        // Ticket table rebuild. Only Workspace phase two must fail on DROP VIEW.
        conn.execute_batch("INSERT INTO typed_tickets(workspace_id,ticket_id,slug,title,status,kind,priority,body,workflow_state,workflow_state_explicit)
            VALUES('case-workspace','terminal','terminal','Terminal','closed','task','P2','','done',1);
            DROP VIEW ticket_active_worker_assignments;
            CREATE TABLE ticket_active_worker_assignments AS SELECT * FROM ticket_current_worker_assignments WHERE 0;").unwrap();
        install_retained_ticket_tags8(&conn);
        let _tags = seed_retained_classification(&conn, "case-workspace", "terminal");
        let tags_before = classification_rows(&conn);
        let auth_before = fixture_auth_rows(&conn);
        let error = migrate_ticket_cases_v90_to_v91(&conn).unwrap_err();
        assert!(error.to_string().contains("DROP TABLE"), "{error}");
        assert_eq!(current_schema_version(&conn).unwrap(), 90);
        assert_eq!(fixture_auth_rows(&conn), auth_before);
        assert_eq!(classification_rows(&conn), tags_before);
        // The shared transaction completed, but Workspace did not advertise a
        // composed schema. Its immutable evidence remains the retry authority.
        let before = stored_fixture_rows(&conn, "typed_ticket_case_history");
        assert_eq!(before.len(), 1);
        conn.execute_batch("DROP TABLE ticket_active_worker_assignments;")
            .unwrap();
        migrate_ticket_cases_v90_to_v91(&conn).unwrap();
        assert_eq!(current_schema_version(&conn).unwrap(), 91);
        assert_eq!(fixture_auth_rows(&conn), auth_before);
        assert_eq!(classification_rows(&conn), tags_before);
        assert_eq!(
            stored_fixture_rows(&conn, "typed_ticket_case_history"),
            before
        );
        drop(conn);
        let store = SqliteWorkspaceStore::open_for_test(&path).unwrap();
        let backend = ticket::SqliteTicketBackend::open_verified(&path, "case-workspace").unwrap();
        assert_eq!(
            backend
                .show("terminal".into())
                .unwrap()
                .current_closure
                .unwrap()
                .reason,
            ticket::TicketClosureReason::Unknown
        );
        assert!(
            store
                .get_active_ticket_worker_assignment("case-workspace", "terminal")
                .unwrap()
                .is_none()
        );
    }

    #[tokio::test]
    async fn claims_and_compensation_do_not_change_case_state_or_resume_closed_work() {
        let (dir, store) = manual_worker_start_store().await;
        seed_manual_start_ticket(&store, "ticket", "open");
        let record = manual_worker_assignment("ticket", "assignment");
        let fingerprint = manual_ticket_assignment_fingerprint(&record, None).unwrap();
        store
            .reserve_ticket_assignment_operation(
                "w",
                "claim",
                "ticket",
                "r",
                Some("worker"),
                &fingerprint,
                "1",
            )
            .unwrap();
        let backend =
            ticket::SqliteTicketBackend::open_verified(dir.path().join("workspace.db"), "w")
                .unwrap();
        use ticket::TicketBackend;
        assert_eq!(
            backend.show("ticket".into()).unwrap().meta.workflow_state,
            ticket::TicketState::Open
        );
        let closed = update_test_case(
            &backend,
            "ticket",
            "close",
            ticket::TicketCaseAction::Close {
                reason: ticket::TicketClosureReason::NotPlanned,
            },
        );
        assert!(
            store
                .get_pending_ticket_assignment_operation_for_worker(
                    "w",
                    &RuntimeWorkerRef::new("r", "worker")
                )
                .unwrap()
                .is_none()
        );
        assert!(
            store
                .bind_ticket_assignment_operation_worker("w", "claim", "worker")
                .is_err()
        );
        assert!(
            store
                .start_ticket_with_worker_assignment(&record, "event", "claim", None)
                .is_err()
        );
        store
            .rollback_ticket_assignment_operation("w", "claim")
            .unwrap();
        assert_eq!(
            backend.show("ticket".into()).unwrap().meta.workflow_state,
            ticket::TicketState::Closed
        );
        assert_eq!(
            backend.show("ticket".into()).unwrap().case_history,
            closed.case_history
        );
        assert_eq!(
            store
                .get_ticket_assignment_operation("w", "claim")
                .unwrap()
                .unwrap()
                .claim_state,
            "failed"
        );
        assert!(
            store
                .get_current_ticket_worker_assignment("w", "ticket")
                .unwrap()
                .is_none()
        );
        // Explicit reopening also leaves the failed claim receipt inert.
        update_test_case(
            &backend,
            "ticket",
            "reopen",
            ticket::TicketCaseAction::Reopen,
        );
        assert!(
            store
                .start_ticket_with_worker_assignment(&record, "event", "claim", None)
                .is_err()
        );
    }

    #[test]
    fn schema_v91_fresh_and_retained_cases_and_auth_enforce_equivalent_constraints() {
        // Compare SQLite boundary contracts, including guards lost by a parent
        // table rebuild, rather than only the latest version marker. Redundant
        // indexes with the same uniqueness contract are one semantic constraint.
        fn signature(conn: &Connection, object: &str) -> Vec<Vec<String>> {
            [
                "SELECT name,type,CAST(\"notnull\" AS TEXT),COALESCE(dflt_value,'<NULL>'),CAST(pk AS TEXT) FROM pragma_table_info(?1) ORDER BY name",
                "SELECT \"table\",\"from\",\"to\",on_update,on_delete,match,CAST(seq AS TEXT) FROM pragma_foreign_key_list(?1) ORDER BY \"table\",\"from\",\"to\",seq",
                "SELECT DISTINCT CAST(i.\"unique\" AS TEXT),CAST(i.partial AS TEXT),(SELECT group_concat(name,',') FROM (SELECT name FROM pragma_index_info(i.name) ORDER BY seqno)) FROM pragma_index_list(?1) AS i ORDER BY 1,2,3",
                "SELECT name,sql FROM sqlite_schema WHERE (type='trigger' AND tbl_name=?1) OR (type='view' AND name=?1) ORDER BY name",
            ].into_iter().flat_map(|sql| {
                let mut stmt = conn.prepare(sql).unwrap();
                let count = stmt.column_count();
                stmt.query_map([object], |row| {
                    (0..count).map(|i| row.get::<_, String>(i)).collect::<rusqlite::Result<Vec<_>>>()
                }).unwrap().map(|row| row.unwrap().into_iter().map(|value| {
                    value.chars().filter(|c| !c.is_whitespace() && *c != '"').collect()
                }).collect()).collect::<Vec<Vec<String>>>()
            }).collect()
        }
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("equivalence.db");
        prepare_retained_schema(&path, 90);
        let upgraded = SqliteWorkspaceStore::open_for_test(&path).unwrap();
        let fresh = SqliteWorkspaceStore::in_memory_for_test().unwrap();
        for object in [
            "workspace_tags",
            "typed_ticket_tags",
            "workspace_tag_operations",
            "typed_tickets",
            "typed_ticket_targets",
            "typed_ticket_case_metadata",
            "typed_ticket_case_history",
            "typed_ticket_legacy_workflow_snapshot",
            "ticket_current_worker_assignments",
            "ticket_assignment_work_releases",
            "ticket_active_worker_assignments",
            "worker_registry",
            "workspace_runtime_bindings",
            "workspace_runtime_binding_verification_archive",
            "workspace_runtime_verification_archive",
            "workspace_runtime_binding_audit",
            "workspace_signing_identities",
            "workspace_signing_identity_provisioning_operations",
            "workspace_signing_identity_audit",
        ] {
            let expected = fresh.with_conn(|conn| Ok(signature(conn, object))).unwrap();
            let actual = upgraded
                .with_conn(|conn| Ok(signature(conn, object)))
                .unwrap();
            assert!(!expected.is_empty(), "missing fresh schema object {object}");
            assert_eq!(actual, expected, "schema-91 boundary {object}");
        }
        for store in [&fresh, &upgraded] {
            store.with_conn(|conn| {
                assert_eq!(current_schema_version(conn)?, LATEST_SCHEMA_VERSION);
                verify_workspace_resource_constraints(conn)?;
                verify_runtime_binding_connection_schema(conn)?;
                ticket::verify_sqlite_ticket_schema(conn).unwrap();
                conn.execute_batch("INSERT INTO accounts(account_id,kind,handle,display_name,created_at,updated_at)
                    VALUES('guard-owner','user','guard-owner','Owner','1','1');
                    INSERT INTO workspaces(workspace_id,owner_account_id,display_name,state,created_at,updated_at)
                    VALUES('guard-workspace','guard-owner','Guard','active','1','1');
                    INSERT INTO typed_tickets(workspace_id,ticket_id,slug,title,status,kind,priority,workflow_state,workflow_state_explicit)
                    VALUES('guard-workspace','guard-ticket','guard-ticket','Guard','open','task','P2','open',1);
                    INSERT INTO typed_ticket_events(workspace_id,ticket_id,event_index,event_ref,kind,body) VALUES('guard-workspace','guard-ticket',-1,'guard-ticket:-1','comment','');")?;
                assert!(conn.execute("UPDATE typed_tickets SET workflow_state='done' WHERE ticket_id='guard-ticket'", []).is_err());
                assert!(conn.execute("INSERT INTO typed_tickets(workspace_id,ticket_id,slug,title,status,kind,priority,workflow_state,workflow_state_explicit)
                    VALUES('guard-workspace','bad-ticket','bad-ticket','Bad','open','task','P2','planning',1)", []).is_err());
                assert!(conn.execute("INSERT INTO workspace_runtime_bindings(workspace_id,runtime_id,display_name,base_url,public_key,public_key_fingerprint,binding_id,authentication_mode,created_at,updated_at)
                    VALUES('guard-workspace','bad-runtime','Bad','https://invalid.invalid','key','fingerprint','binding','invalid-mode','1','1')", []).is_err());
                Ok(())
            }).unwrap();
        }
    }

    #[test]
    fn schema_v91_case_constraint_verification_rejects_legacy_view_predicates() {
        let store = SqliteWorkspaceStore::in_memory_for_test().unwrap();
        store.with_conn(|conn| {
            conn.execute_batch("DROP VIEW ticket_active_worker_assignments;
                CREATE VIEW ticket_active_worker_assignments AS
                SELECT current.* FROM ticket_current_worker_assignments AS current
                JOIN typed_tickets AS ticket ON ticket.workspace_id=current.workspace_id AND ticket.ticket_id=current.ticket_id
                WHERE ticket.workflow_state NOT IN ('done','closed');")?;
            assert!(verify_workspace_resource_constraints(conn).unwrap_err().to_string().contains("schema 91"));
            Ok(())
        }).unwrap();
    }

    // Equivalent to the reported closed T-12 + retained Coder data. The
    // migration fixture is a real pre-cutover schema, not the live Workspace.
    #[test]
    fn schema_v81_terminal_responsibility_survives_migration_reopen_and_worker_deletion() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("workspace.db");
        prepare_schema_v50(&path, Some("workspace-a"));
        let conn = Connection::open(&path).unwrap();
        configure_sqlite(&conn).unwrap();
        for migration in MIGRATIONS.iter().filter(|m| m.version <= 81) {
            (migration.apply)(&conn).unwrap();
        }
        conn.execute_batch(r#"
            INSERT INTO worker_registry(workspace_id,runtime_id,worker_id,display_name,retention_state,created_at,updated_at)
                VALUES('workspace-a','runtime-a','old-coder','Coder T-12','normal','1','1');
            INSERT INTO typed_tickets(workspace_id,ticket_id,slug,title,status,kind,priority,body,workflow_state,workflow_state_explicit,updated_at)
                VALUES('workspace-a','closed-ticket','closed-ticket','Closed Ticket','closed','task','normal','','closed',1,'2');
            INSERT INTO ticket_worker_assignments(workspace_id,ticket_id,assignment_id,runtime_id,worker_id,assigned_by,assigned_at)
                VALUES('workspace-a','closed-ticket','old-assignment','runtime-a','old-coder','actor','1');
            INSERT INTO ticket_current_worker_assignments(workspace_id,ticket_id,assignment_id,runtime_id,worker_id,updated_at)
                VALUES('workspace-a','closed-ticket','old-assignment','runtime-a','old-coder','1');
            INSERT INTO ticket_worker_assignment_events(workspace_id,ticket_id,event_id,action,assignment_id,actor,created_at)
                VALUES('workspace-a','closed-ticket','assigned-event','assigned','old-assignment','actor','1');
            INSERT INTO ticket_worker_assignments(workspace_id,ticket_id,assignment_id,role,principal_kind,principal_id,assigned_by,assigned_at)
                VALUES('workspace-a','closed-ticket','historical-user','coder','user','owner','actor','0'),
                      ('workspace-a','closed-ticket','historical-contributor','contributor','user','owner','actor','0');
            INSERT INTO ticket_assignment_operations(workspace_id,operation_id,action,ticket_id,role,principal_kind,principal_id,assignment_id,created_at,request_fingerprint)
                VALUES('workspace-a','old-assignment-op','assign','closed-ticket','coder','user','owner','historical-user','0','original-fingerprint');
            INSERT INTO ticket_assignment_operations(workspace_id,operation_id,action,ticket_id,runtime_id,worker_id,created_at,request_fingerprint)
                VALUES('workspace-a','old-pending-op','assign','closed-ticket','runtime-a','old-coder','0','pending-fingerprint');
        "#).unwrap();
        assert_eq!(
            conn.query_row(
                "SELECT role FROM ticket_current_worker_assignments",
                [],
                |row| row.get::<_, String>(0)
            )
            .unwrap(),
            "coder"
        );
        let legacy_blockers = serde_json::json!([
            {"kind":"hold"}, {"kind":"current_assignment","assignment_id":"current_assignment","ticket_id":"closed-ticket"}
        ]).to_string();
        conn.execute("INSERT INTO worker_removal_operations(operation_id,plan_id,input_fingerprint,workspace_id,runtime_id,worker_id,worker_revision,policy_id,policy_revision,session_disposition,metadata_disposition,archive_retention_kind,diagnostics_disposition,blockers_json,state,reason,created_at,updated_at)
            VALUES('old-op','old-plan','immutable-fingerprint','workspace-a','runtime-a','old-coder','1','workspace-default-conservative',1,'purge','tombstone','forever','purge',?1,'blocked','retain','1','1')", [&legacy_blockers]).unwrap();
        migrate_assignment_work_v81_to_v82(&conn).unwrap();
        assert_eq!(current_schema_version(&conn).unwrap(), 82);
        apply_migrations(&conn).unwrap(); // canonical retry is a no-op
        let pending = read_assignment_operation(&conn, "workspace-a", "old-pending-op")
            .unwrap()
            .unwrap();
        assert_eq!(pending.claim_state, "pending");
        assert_eq!(
            pending.request_fingerprint.as_deref(),
            Some("pending-fingerprint")
        );
        assert!(pending.failure_reason.is_none());
        assert_eq!(
            read_assignment_operation(&conn, "workspace-a", "old-assignment-op")
                .unwrap()
                .unwrap()
                .claim_state,
            "committed"
        );
        for table in [
            "ticket_worker_assignments",
            "ticket_current_worker_assignments",
            "ticket_worker_assignment_events",
            "ticket_assignment_operations",
        ] {
            assert_eq!(
                conn.query_row(
                    &format!("SELECT COUNT(*) FROM {table} WHERE role='coder'"),
                    [],
                    |row| row.get::<_, i64>(0)
                )
                .unwrap(),
                0,
                "{table}"
            );
        }
        let historical_user =
            read_ticket_role_assignment_by_id(&conn, "workspace-a", "historical-user")
                .unwrap()
                .unwrap();
        assert_eq!(historical_user.role, TicketAssignmentRole::Worker);
        assert_eq!(
            historical_user.principal,
            TicketAssignmentPrincipal::User {
                account_id: "owner".into()
            }
        );
        assert_eq!(
            read_ticket_role_assignment_by_id(&conn, "workspace-a", "historical-contributor")
                .unwrap()
                .unwrap()
                .role,
            TicketAssignmentRole::Contributor
        );
        assert_eq!(conn.query_row("SELECT role,request_fingerprint,assignment_id FROM ticket_assignment_operations WHERE operation_id='old-assignment-op'", [], |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?, row.get::<_, String>(2)?))).unwrap(), ("worker".into(), "original-fingerprint".into(), "historical-user".into()));
        let (plan, fingerprint, state, encoded): (String,String,String,String) = conn.query_row(
            "SELECT plan_id,input_fingerprint,state,blockers_json FROM worker_removal_operations WHERE operation_id='old-op'", [],
            |row| Ok((row.get(0)?,row.get(1)?,row.get(2)?,row.get(3)?))).unwrap();
        assert_eq!(
            (plan.as_str(), fingerprint.as_str(), state.as_str()),
            ("old-plan", "immutable-fingerprint", "stale")
        );
        let blockers: Vec<crate::retention::WorkerRemovalBlocker> =
            serde_json::from_str(&encoded).unwrap();
        assert!(
            matches!(&blockers[..], [crate::retention::WorkerRemovalBlocker::Hold,crate::retention::WorkerRemovalBlocker::UnfinishedWork { assignment_id,ticket_id }] if assignment_id=="current_assignment" && ticket_id=="closed-ticket")
        );
        conn.execute_batch(
            "UPDATE typed_tickets SET workflow_state='open' WHERE ticket_id='closed-ticket';
            DELETE FROM worker_registry WHERE worker_id='old-coder';",
        )
        .unwrap();
        let (responsibility, active, history, tombstone): (i64, i64, i64, i64) = conn
            .query_row(
                "SELECT (SELECT COUNT(*) FROM ticket_current_worker_assignments),
                    (SELECT COUNT(*) FROM ticket_active_worker_assignments),
                    (SELECT COUNT(*) FROM ticket_worker_assignment_events),
                    (SELECT COUNT(*) FROM ticket_assignment_worker_tombstones)",
                [],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
            )
            .unwrap();
        assert_eq!((responsibility, active, history, tombstone), (1, 0, 1, 1));
        assert_eq!(
            conn.query_row("SELECT COUNT(*) FROM pragma_foreign_key_check", [], |row| {
                row.get::<_, i64>(0)
            })
            .unwrap(),
            0
        );
        assert!(
            conn.execute(
                "UPDATE ticket_current_worker_assignments SET updated_at='3'",
                []
            )
            .is_err(),
            "removed Worker cannot receive new authority"
        );
    }

    // Direct store fixture: explicit claims, not queue scheduling, are the
    // boundary under test. Targets need not be materialized by a Runtime.
    async fn manual_worker_start_store() -> (tempfile::TempDir, SqliteWorkspaceStore) {
        let dir = tempfile::tempdir().unwrap();
        let store =
            SqliteWorkspaceStore::open_api_fixture(dir.path().join("workspace.db")).unwrap();
        store
            .upsert_workspace(&WorkspaceRecord {
                workspace_id: "w".into(),
                owner_account_id: "owner-account".into(),
                display_name: "W".into(),
                state: "active".into(),
                created_at: "1".into(),
                updated_at: "1".into(),
            })
            .await
            .unwrap();
        store.with_conn(|conn| {
            conn.execute_batch("INSERT INTO worker_registry(workspace_id,runtime_id,worker_id,display_name,retention_state,created_at,updated_at)
                VALUES('w','r','worker','Worker','normal','1','1');
                INSERT INTO repositories(workspace_id,repository_id,repository_key,kind,provider,uri,created_at,updated_at,source_kind,source_uri,source_fingerprint)
                VALUES('w','main','main','git','git','file:///main','1','1','file','file:///main','sha256:fixture');")?;
            Ok(())
        }).unwrap();
        (dir, store)
    }

    fn update_test_case(
        backend: &ticket::SqliteTicketBackend,
        id: &str,
        operation: &str,
        action: ticket::TicketCaseAction,
    ) -> ticket::Ticket {
        use ticket::TicketBackend;
        let current = backend.show(id.into()).unwrap();
        backend
            .update_case(
                id,
                ticket::TicketCaseUpdate {
                    expected_content_digest: ticket::ticket_content_digest(&current),
                    expected_state: current.meta.workflow_state,
                    expected_closure_operation_key: current.closure_operation_key,
                    operation_key: operation.into(),
                    action,
                    explanation: "Store fixture case judgment".into(),
                    references: vec![],
                    author: Some("store-fixture-author".into()),
                },
            )
            .unwrap()
    }

    fn seed_manual_start_ticket(store: &SqliteWorkspaceStore, id: &str, state: &str) {
        store.with_conn(|conn| {
            conn.execute("INSERT INTO typed_tickets(workspace_id,ticket_id,slug,title,status,kind,priority,workflow_state,workflow_state_explicit,updated_at)
                VALUES('w',?1,?1,'Ticket','open','task','normal',?2,1,'1')", params![id,state])?;
            conn.execute("INSERT INTO typed_ticket_events(workspace_id,ticket_id,event_index,event_ref,kind,body) VALUES('w',?1,-1,?1 || ':-1','comment','')", [id])?;
            Ok(())
        }).unwrap();
    }

    fn manual_worker_assignment(
        ticket_id: &str,
        assignment_id: &str,
    ) -> TicketRoleAssignmentRecord {
        TicketRoleAssignmentRecord {
            workspace_id: "w".into(),
            ticket_id: ticket_id.into(),
            assignment_id: assignment_id.into(),
            role: TicketAssignmentRole::Worker,
            principal: TicketAssignmentPrincipal::Worker {
                runtime_id: "r".into(),
                worker_id: "worker".into(),
            },
            assigned_by: "owner-account".into(),
            assigned_at: "2".into(),
        }
    }

    #[tokio::test]
    async fn pending_claims_serialize_competing_ticket_and_known_worker_reservations() {
        for (same_ticket, same_operation) in [(true, false), (false, false), (true, true)] {
            let (dir, store) = manual_worker_start_store().await;
            seed_manual_start_ticket(&store, "first", "open");
            seed_manual_start_ticket(&store, "second", "open");
            store.with_conn(|conn| {
                conn.execute_batch("INSERT INTO worker_registry(workspace_id,runtime_id,worker_id,display_name,retention_state,created_at,updated_at)
                    VALUES('w','r','other','Other','normal','1','1');")?;
                Ok(())
            }).unwrap();
            let barrier = std::sync::Arc::new(std::sync::Barrier::new(3));
            let threads = (0..2)
                .map(|index| {
                    let store =
                        SqliteWorkspaceStore::open_for_test(dir.path().join("workspace.db"))
                            .unwrap();
                    let barrier = barrier.clone();
                    std::thread::spawn(move || {
                        barrier.wait();
                        let ticket = if same_ticket || index == 0 {
                            "first"
                        } else {
                            "second"
                        };
                        let worker = if same_ticket && !same_operation && index == 1 {
                            "other"
                        } else {
                            "worker"
                        };
                        let index = if same_operation { 0 } else { index };
                        store.reserve_ticket_assignment_operation(
                            "w",
                            &format!("operation-{index}"),
                            ticket,
                            "r",
                            Some(worker),
                            &format!("fingerprint-{index}"),
                            "1",
                        )
                    })
                })
                .collect::<Vec<_>>();
            barrier.wait();
            let results = threads
                .into_iter()
                .map(|thread| thread.join().unwrap())
                .collect::<Vec<_>>();
            assert_eq!(
                results
                    .iter()
                    .filter(|result| matches!(result, Ok(true)))
                    .count(),
                1
            );
            if same_operation {
                assert_eq!(
                    results
                        .iter()
                        .filter(|result| matches!(result, Ok(false)))
                        .count(),
                    1
                );
            } else {
                assert_eq!(results.iter().filter(|result| result.is_err()).count(), 1);
            }
            store.with_conn(|conn| {
                assert_eq!(conn.query_row("SELECT COUNT(*) FROM ticket_assignment_operations WHERE claim_state='pending'", [], |row| row.get::<_,i64>(0))?, 1);
                assert_eq!(conn.query_row("SELECT COUNT(*) FROM ticket_worker_assignments", [], |row| row.get::<_,i64>(0))?, 0);
                Ok(())
            }).unwrap();
        }
    }

    #[tokio::test]
    async fn pending_claims_fence_work_writers_but_allow_delegation_clear() {
        let (_dir, store) = manual_worker_start_store().await;
        seed_manual_start_ticket(&store, "first", "open");
        seed_manual_start_ticket(&store, "second", "open");
        let first = manual_worker_assignment("first", "first-assignment");
        let orchestrator = TicketRoleAssignmentRecord {
            role: TicketAssignmentRole::Orchestrator,
            principal: TicketAssignmentPrincipal::Subject {
                subject_id: "fixture-subject".into(),
            },
            ..first.clone()
        };
        store
            .set_current_ticket_role_assignment(
                &orchestrator,
                None,
                "original-event",
                "original-op",
                false,
            )
            .unwrap();
        assert!(
            store
                .reserve_ticket_assignment_operation(
                    "w",
                    "unknown",
                    "first",
                    "r",
                    None,
                    "fingerprint",
                    "1"
                )
                .unwrap()
        );
        assert!(
            store
                .rollback_ticket_assignment_operation("w", "original-op")
                .is_err()
        );
        assert!(
            store
                .clear_current_ticket_role_assignment(
                    "w",
                    "first",
                    TicketAssignmentRole::Orchestrator,
                    &orchestrator.assignment_id,
                    "clear-event",
                    "clear-op",
                    "actor",
                    "2",
                    None
                )
                .unwrap()
        );
        assert!(
            store
                .set_current_ticket_role_assignment(
                    &orchestrator,
                    None,
                    "orchestrator-event",
                    "orchestrator-op",
                    false
                )
                .is_err()
        );
        assert!(
            store
                .start_ticket_with_worker_assignment(&first, "manual-event", "manual-op", None)
                .is_err()
        );
        assert!(
            store
                .reserve_ticket_assignment_operation(
                    "w",
                    "competitor",
                    "first",
                    "r",
                    Some("worker"),
                    "other-fingerprint",
                    "1"
                )
                .is_err()
        );
        // An unknown claim has a Ticket fence; binding a concrete Worker must
        // add the Worker fence atomically without stealing another claim.
        assert!(
            store
                .reserve_ticket_assignment_operation(
                    "w",
                    "known",
                    "second",
                    "r",
                    Some("worker"),
                    "known-fingerprint",
                    "1"
                )
                .unwrap()
        );
        assert!(
            store
                .bind_ticket_assignment_operation_worker("w", "unknown", "worker")
                .is_err()
        );
        store
            .fail_ticket_assignment_operation("w", "known", "abandoned before dispatch")
            .unwrap();
        store
            .bind_ticket_assignment_operation_worker("w", "unknown", "worker")
            .unwrap();
        let worker = RuntimeWorkerRef::new("r", "worker");
        assert_eq!(
            store
                .get_pending_ticket_assignment_operation_for_worker("w", &worker)
                .unwrap()
                .unwrap()
                .operation_id,
            "unknown"
        );
        let second = manual_worker_assignment("second", "second-assignment");
        assert!(
            store
                .set_current_ticket_role_assignment(&second, None, "role-event", "role-op", false)
                .is_err()
        );
        assert!(
            store
                .start_ticket_with_worker_assignment(&second, "manual-event", "manual-op", None)
                .is_err()
        );
        let legacy = TicketWorkerAssignmentRecord {
            workspace_id: "w".into(),
            ticket_id: "second".into(),
            assignment_id: "legacy-assignment".into(),
            worker: worker.clone(),
            assigned_by: "actor".into(),
            assigned_at: "2".into(),
        };
        assert!(
            store
                .set_current_ticket_worker_assignment(
                    &legacy,
                    None,
                    "legacy-event",
                    "legacy-op",
                    false
                )
                .is_err()
        );
        let owner = TicketWorkerAssignmentRecord {
            ticket_id: "first".into(),
            ..legacy
        };
        store
            .set_current_ticket_worker_assignment(&owner, None, "owner-event", "unknown", false)
            .unwrap();
        assert_eq!(
            store
                .get_ticket_assignment_operation("w", "unknown")
                .unwrap()
                .unwrap()
                .claim_state,
            "committed"
        );
        assert!(
            store
                .get_pending_ticket_assignment_operation_for_worker("w", &worker)
                .unwrap()
                .is_none()
        );
    }

    #[tokio::test]
    async fn manual_claim_consumes_matching_binding_fingerprint_and_replays_committed_receipt() {
        let (_dir, store) = manual_worker_start_store().await;
        seed_manual_start_ticket(&store, "first", "open");
        let record = manual_worker_assignment("first", "assignment");
        let fingerprint =
            manual_ticket_assignment_fingerprint(&record, Some("bindings-a")).unwrap();
        assert!(
            store
                .reserve_ticket_assignment_operation(
                    "w",
                    "claim",
                    "first",
                    "r",
                    Some("worker"),
                    &fingerprint,
                    "1"
                )
                .unwrap()
        );
        assert!(
            !store
                .reserve_ticket_assignment_operation(
                    "w",
                    "claim",
                    "first",
                    "r",
                    Some("worker"),
                    &fingerprint,
                    "1"
                )
                .unwrap()
        );
        assert!(
            store
                .start_ticket_with_worker_assignment(&record, "event", "claim", Some("bindings-b"))
                .is_err()
        );
        assert_eq!(
            store
                .get_ticket_assignment_operation("w", "claim")
                .unwrap()
                .unwrap()
                .claim_state,
            "pending"
        );
        assert_eq!(
            store
                .start_ticket_with_worker_assignment(&record, "event", "claim", Some("bindings-a"))
                .unwrap(),
            record
        );
        let regenerated = TicketRoleAssignmentRecord {
            assignment_id: "retry-id".into(),
            assigned_at: "3".into(),
            ..record.clone()
        };
        assert_eq!(
            store
                .start_ticket_with_worker_assignment(
                    &regenerated,
                    "retry-event",
                    "claim",
                    Some("bindings-a")
                )
                .unwrap(),
            record
        );
        assert!(
            store
                .start_ticket_with_worker_assignment(&regenerated, "retry-event", "claim", None)
                .is_err()
        );
        let receipt = store
            .get_ticket_assignment_operation("w", "claim")
            .unwrap()
            .unwrap();
        assert_eq!(receipt.claim_state, "committed");
        assert_eq!(
            receipt.assignment_id.as_deref(),
            Some(record.assignment_id.as_str())
        );
        assert_eq!(
            receipt.request_fingerprint.as_deref(),
            Some(fingerprint.as_str())
        );
        assert!(
            store
                .fail_ticket_assignment_operation("w", "claim", "too late")
                .is_err()
        );
    }

    #[tokio::test]
    async fn manual_claim_recovery_survives_reopen_and_fences_stale_item_finalization() {
        let (dir, store) = manual_worker_start_store().await;
        seed_manual_start_ticket(&store, "first", "open");
        let record = manual_worker_assignment("first", "assignment");
        let fingerprint = manual_ticket_assignment_fingerprint(&record, Some("bindings")).unwrap();
        store
            .reserve_ticket_assignment_operation(
                "w",
                "claim",
                "first",
                "r",
                Some("worker"),
                &fingerprint,
                "1",
            )
            .unwrap();
        let recovery = TicketWorkerClaimRecovery {
            content_digest: store
                .with_conn(|conn| {
                    ticket::sqlite_ticket_content_digest(conn, "w", "first")
                        .map_err(|error| Error::Store(error.to_string()))
                })
                .unwrap()
                .unwrap(),
            selected: vec![],
            original_links: vec![],
            effective_links: vec![],
        };
        store
            .retain_ticket_claim_recovery("w", "claim", &fingerprint, &recovery)
            .unwrap();
        store
            .retain_ticket_claim_recovery("w", "claim", &fingerprint, &recovery)
            .unwrap();
        let mut changed = recovery.clone();
        changed.content_digest = "first:1".into();
        assert!(
            store
                .retain_ticket_claim_recovery("w", "claim", &fingerprint, &changed)
                .is_err()
        );
        let reopened =
            SqliteWorkspaceStore::open_for_test(dir.path().join("workspace.db")).unwrap();
        assert_eq!(
            reopened.get_ticket_claim_recovery("w", "claim").unwrap(),
            Some(recovery)
        );
        reopened.with_conn(|conn| {
            conn.execute_batch("UPDATE typed_tickets SET title='Changed requirements' WHERE workspace_id='w' AND ticket_id='first';
                UPDATE typed_ticket_events SET body='Ticket requirements changed',edited_at='2',edited_by='fixture-editor' WHERE workspace_id='w' AND ticket_id='first' AND event_index=-1;")?; Ok(())
        }).unwrap();
        assert!(
            reopened
                .start_ticket_with_worker_assignment(&record, "event", "claim", Some("bindings"))
                .unwrap_err()
                .to_string()
                .contains("Ticket changed")
        );
        assert_eq!(
            reopened
                .get_ticket_assignment_operation("w", "claim")
                .unwrap()
                .unwrap()
                .claim_state,
            "pending"
        );
        assert!(
            reopened
                .get_active_ticket_worker_assignment("w", "first")
                .unwrap()
                .is_none()
        );
    }

    #[tokio::test]
    async fn manual_claim_failed_receipt_survives_reopen_and_rollback_without_restarting() {
        let (dir, store) = manual_worker_start_store().await;
        seed_manual_start_ticket(&store, "first", "open");
        let record = manual_worker_assignment("first", "assignment");
        let fingerprint = manual_ticket_assignment_fingerprint(&record, Some("bindings")).unwrap();
        store
            .reserve_ticket_assignment_operation(
                "w",
                "claim",
                "first",
                "r",
                Some("worker"),
                &fingerprint,
                "1",
            )
            .unwrap();
        store
            .fail_ticket_assignment_operation("w", "claim", "binding compensation required")
            .unwrap();
        store
            .fail_ticket_assignment_operation("w", "claim", "must not replace original failure")
            .unwrap();
        store
            .rollback_ticket_assignment_operation("w", "claim")
            .unwrap();
        let reopened =
            SqliteWorkspaceStore::open_for_test(dir.path().join("workspace.db")).unwrap();
        let receipt = reopened
            .get_ticket_assignment_operation("w", "claim")
            .unwrap()
            .unwrap();
        assert_eq!(receipt.claim_state, "failed");
        assert_eq!(
            receipt.failure_reason.as_deref(),
            Some("binding compensation required")
        );
        assert_eq!(
            receipt.request_fingerprint.as_deref(),
            Some(fingerprint.as_str())
        );
        assert!(
            !reopened
                .reserve_ticket_assignment_operation(
                    "w",
                    "claim",
                    "first",
                    "r",
                    Some("worker"),
                    &fingerprint,
                    "1"
                )
                .unwrap()
        );
        assert!(
            reopened
                .start_ticket_with_worker_assignment(&record, "event", "claim", Some("bindings"))
                .unwrap_err()
                .to_string()
                .contains("binding compensation required")
        );
        assert!(
            reopened
                .get_pending_ticket_assignment_operation_for_worker(
                    "w",
                    &RuntimeWorkerRef::new("r", "worker")
                )
                .unwrap()
                .is_none()
        );
        assert!(
            reopened
                .get_active_ticket_worker_assignment("w", "first")
                .unwrap()
                .is_none()
        );
    }

    #[tokio::test]
    async fn manual_worker_start_is_case_neutral_with_idempotent_assignment_and_audit() {
        for state in ["open", "closed"] {
            for user_principal in [false, true] {
                let (_dir, store) = manual_worker_start_store().await;
                seed_manual_start_ticket(&store, "ticket", state);
                let mut record = manual_worker_assignment("ticket", "assignment");
                if user_principal {
                    record.principal = TicketAssignmentPrincipal::User {
                        account_id: "owner-account".into(),
                    };
                }
                let result =
                    store.start_ticket_with_worker_assignment(&record, "event", "operation", None);
                if state == "closed" {
                    assert!(result.is_err(), "{state}");
                } else {
                    assert_eq!(result.unwrap(), record, "{state}");
                    let replay = TicketRoleAssignmentRecord {
                        assignment_id: "regenerated".into(),
                        assigned_at: "3".into(),
                        ..record.clone()
                    };
                    assert_eq!(
                        store
                            .start_ticket_with_worker_assignment(
                                &replay,
                                "replay-event",
                                "operation",
                                None
                            )
                            .unwrap(),
                        record
                    );
                    assert_eq!(
                        store
                            .get_active_ticket_role_assignment(
                                "w",
                                "ticket",
                                TicketAssignmentRole::Worker
                            )
                            .unwrap(),
                        Some(record)
                    );
                }
                store.with_conn(|conn| {
                    let (persisted, events, assignments, operations): (String,i64,i64,i64) = conn.query_row(
                        "SELECT workflow_state, (SELECT COUNT(*) FROM typed_ticket_events),
                         (SELECT COUNT(*) FROM ticket_worker_assignments), (SELECT COUNT(*) FROM ticket_assignment_operations)
                         FROM typed_tickets WHERE ticket_id='ticket'", [],
                        |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)))?;
                    if state == "closed" {
                        assert_eq!((persisted.as_str(), events, assignments, operations), (state,1,0,0));
                    } else {
                        assert_eq!((persisted.as_str(), events, assignments, operations), ("open",2,1,1));
                        let transition: (Option<String>,Option<String>,String) = conn.query_row("SELECT from_state,to_state,kind FROM typed_ticket_events WHERE kind='assignment'", [], |row| Ok((row.get(0)?,row.get(1)?,row.get(2)?)))?;
                        assert_eq!(transition, (None, None, "assignment".into()));
                        assert_eq!(conn.query_row("SELECT value FROM typed_ticket_event_attributes WHERE key='assignment_role'", [], |row| row.get::<_,String>(0))?, "worker");
                    }
                    Ok(())
                }).unwrap();
            }
        }
    }

    #[tokio::test]
    async fn manual_worker_start_rejects_busy_worker_without_mutation_and_requires_new_reopen_identity()
     {
        let (_dir, store) = manual_worker_start_store().await;
        seed_manual_start_ticket(&store, "first", "open");
        seed_manual_start_ticket(&store, "second", "open");
        let first = manual_worker_assignment("first", "first-assignment");
        let second = manual_worker_assignment("second", "second-assignment");
        store
            .start_ticket_with_worker_assignment(&first, "first-event", "first-operation", None)
            .unwrap();
        assert!(
            store
                .start_ticket_with_worker_assignment(
                    &second,
                    "second-event",
                    "second-operation",
                    None
                )
                .is_err()
        );
        store
            .with_conn(|conn| {
                assert_eq!(
                    conn.query_row(
                        "SELECT workflow_state FROM typed_tickets WHERE ticket_id='second'",
                        [],
                        |row| row.get::<_, String>(0)
                    )?,
                    "open"
                );
                assert_eq!(
                    conn.query_row(
                        "SELECT COUNT(*) FROM ticket_assignment_operations",
                        [],
                        |row| row.get::<_, i64>(0)
                    )?,
                    1
                );
                conn.execute_batch(
                    "UPDATE typed_tickets SET workflow_state='closed' WHERE ticket_id='first';
                UPDATE typed_tickets SET workflow_state='open' WHERE ticket_id='first';",
                )?;
                Ok(())
            })
            .unwrap();
        // A replay returns history; it must not restore unfinished work.
        assert_eq!(
            store
                .start_ticket_with_worker_assignment(&first, "replay", "first-operation", None)
                .unwrap(),
            first
        );
        assert!(
            store
                .get_active_ticket_worker_assignment("w", "first")
                .unwrap()
                .is_none()
        );
        assert!(
            store
                .start_ticket_with_worker_assignment(&first, "reuse-event", "reuse-operation", None)
                .is_err()
        );
        assert!(
            store
                .get_active_ticket_worker_assignment("w", "first")
                .unwrap()
                .is_none()
        );
        let restart = TicketRoleAssignmentRecord {
            assignment_id: "restart".into(),
            ..first.clone()
        };
        store
            .start_ticket_with_worker_assignment(
                &restart,
                "restart-event",
                "restart-operation",
                None,
            )
            .unwrap();
        assert_eq!(
            store
                .get_active_ticket_role_assignment("w", "first", TicketAssignmentRole::Worker)
                .unwrap(),
            Some(restart)
        );
        let events = store
            .list_ticket_worker_assignment_events("w", "first", 10)
            .unwrap();
        assert_eq!(
            events[0].previous_assignment_id.as_deref(),
            Some(first.assignment_id.as_str())
        );
        assert_eq!(events[0].action, "reassigned");
    }

    #[tokio::test]
    async fn close_retains_responsibility_without_occupying_new_work_and_reopen_requires_new_identity()
     {
        use ticket::TicketBackend;
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("workspace.db");
        let store = SqliteWorkspaceStore::open_api_fixture(&path).unwrap();
        store
            .upsert_workspace(&WorkspaceRecord {
                workspace_id: "w".into(),
                owner_account_id: "owner-account".into(),
                display_name: "W".into(),
                state: "active".into(),
                created_at: "1".into(),
                updated_at: "1".into(),
            })
            .await
            .unwrap();
        store.with_conn(|conn| {
            conn.execute_batch("INSERT INTO worker_registry(workspace_id,runtime_id,worker_id,display_name,retention_state,created_at,updated_at) VALUES('w','r','coder','Coder','normal','1','1');")?;
            Ok(())
        }).unwrap();
        let backend = ticket::SqliteTicketBackend::open_verified(&path, "w").unwrap();
        let first = backend.create(ticket::NewTicket::new("First")).unwrap();
        let second = backend.create(ticket::NewTicket::new("Second")).unwrap();
        let assignment = TicketWorkerAssignmentRecord {
            workspace_id: "w".into(),
            ticket_id: first.id.clone(),
            assignment_id: "a1".into(),
            worker: RuntimeWorkerRef::new("r", "coder"),
            assigned_by: "actor".into(),
            assigned_at: "1".into(),
        };
        store
            .set_current_ticket_worker_assignment(&assignment, None, "e1", "op1", false)
            .unwrap();
        let next = TicketWorkerAssignmentRecord {
            ticket_id: second.id.clone(),
            assignment_id: "a2".into(),
            ..assignment.clone()
        };
        assert!(
            store
                .set_current_ticket_worker_assignment(&next, None, "e2", "op2", false)
                .is_err()
        );
        update_test_case(
            &backend,
            &first.id,
            "close-first",
            ticket::TicketCaseAction::Close {
                reason: ticket::TicketClosureReason::Unknown,
            },
        );
        assert_eq!(
            store
                .get_current_ticket_worker_assignment("w", &first.id)
                .unwrap(),
            Some(assignment.clone())
        );
        assert!(
            store
                .get_active_ticket_worker_assignment("w", &first.id)
                .unwrap()
                .is_none()
        );
        store
            .set_current_ticket_worker_assignment(&next, None, "e2", "op2", false)
            .unwrap();
        update_test_case(
            &backend,
            &first.id,
            "reopen-first",
            ticket::TicketCaseAction::Reopen,
        );
        assert!(
            store
                .get_active_ticket_worker_assignment("w", &first.id)
                .unwrap()
                .is_none()
        );
        // Replay of the original operation reports its identity but does not revive work.
        store
            .set_current_ticket_worker_assignment(&assignment, None, "e1", "op1", false)
            .unwrap();
        assert!(
            store
                .get_active_ticket_worker_assignment("w", &first.id)
                .unwrap()
                .is_none()
        );
        let restarted = TicketWorkerAssignmentRecord {
            assignment_id: "a3".into(),
            ..assignment.clone()
        };
        assert!(
            store
                .set_current_ticket_worker_assignment(&restarted, None, "e3", "op3", false)
                .is_err(),
            "another Ticket still occupies the Worker"
        );
        update_test_case(
            &backend,
            &second.id,
            "close-second",
            ticket::TicketCaseAction::Close {
                reason: ticket::TicketClosureReason::Unknown,
            },
        );
        store
            .set_current_ticket_worker_assignment(&restarted, None, "e3", "op3", false)
            .unwrap();
        assert_eq!(
            store
                .get_active_ticket_worker_assignment("w", &first.id)
                .unwrap(),
            Some(restarted)
        );
        let events = store
            .list_ticket_worker_assignment_events("w", &first.id, 10)
            .unwrap();
        assert_eq!(events[0].previous_assignment_id.as_deref(), Some("a1"));
        assert_eq!(events[0].action, "reassigned");
        assert!(
            store
                .delete_worker_registry("w", &assignment.worker)
                .is_err()
        );
    }

    #[tokio::test]
    async fn ticket_worker_assignment_replaces_current_and_preserves_audit_history() {
        let dir = tempfile::tempdir().unwrap();
        let db = dir.path().join("server.db");
        let store = SqliteWorkspaceStore::open_api_fixture(&db).unwrap();
        store
            .upsert_workspace(&WorkspaceRecord {
                workspace_id: "workspace-a".to_string(),
                owner_account_id: "owner-account".to_string(),
                display_name: "Workspace A".to_string(),
                state: "active".to_string(),
                created_at: "2026-07-32T00:00:00Z".to_string(),
                updated_at: "2026-07-32T00:00:00Z".to_string(),
            })
            .await
            .unwrap();
        store
            .with_conn(|conn| {
                conn.execute_batch(
                    r#"
INSERT INTO typed_tickets (
    workspace_id, ticket_id, slug, title, status, kind, priority,
    workflow_state, workflow_state_explicit
) VALUES
    ('workspace-a', 'ticket-1', 'ticket-1', 'Ticket 1', 'open', 'task', 'normal', 'open', 1),
    ('workspace-a', 'ticket-2', 'ticket-2', 'Ticket 2', 'open', 'task', 'normal', 'open', 1),
    ('workspace-a', 'ticket-3', 'ticket-3', 'Ticket 3', 'open', 'task', 'normal', 'open', 1);
INSERT INTO typed_ticket_events(workspace_id,ticket_id,event_index,event_ref,kind,body)
SELECT workspace_id,ticket_id,-1,ticket_id || ':-1','comment','' FROM typed_tickets WHERE workspace_id='workspace-a';
INSERT INTO worker_registry (
    workspace_id, runtime_id, worker_id, display_name, retention_state, created_at, updated_at
) VALUES
    ('workspace-a', 'runtime-1', 'worker-1', 'Worker 1', 'normal', '1', '1'),
    ('workspace-a', 'runtime-1', 'worker-other', 'Other Worker', 'normal', '1', '1'),
    ('workspace-a', 'runtime-2', 'worker-2', 'Worker 2', 'normal', '1', '1'),
    ('workspace-a', 'runtime-3', 'worker-3', 'Worker 3', 'normal', '1', '1');
"#,
                )?;
                Ok(())
            })
            .unwrap();

        let first = TicketWorkerAssignmentRecord {
            workspace_id: "workspace-a".to_string(),
            ticket_id: "ticket-1".to_string(),
            assignment_id: "assignment-1".to_string(),
            worker: RuntimeWorkerRef::new("runtime-1", "worker-1"),
            assigned_by: "user-1".to_string(),
            assigned_at: "2026-07-32T00:00:01Z".to_string(),
        };
        let created = store
            .set_current_ticket_worker_assignment(&first, None, "event-1", "operation-1", false)
            .unwrap();
        assert_eq!(created.current, first);
        assert_eq!(created.previous, None);
        let retried = store
            .set_current_ticket_worker_assignment(
                &TicketWorkerAssignmentRecord {
                    assignment_id: "ignored-retry-assignment".to_string(),
                    ..first.clone()
                },
                None,
                "ignored-retry-event",
                "operation-1",
                false,
            )
            .unwrap();
        assert_eq!(retried.current, first);
        assert_eq!(
            store
                .list_ticket_worker_assignment_events("workspace-a", "ticket-1", 10)
                .unwrap()
                .len(),
            1,
            "idempotent retry must not append another assignment event"
        );
        let implicit_reassign = store
            .set_current_ticket_worker_assignment(
                &TicketWorkerAssignmentRecord {
                    assignment_id: "implicit-reassign".to_string(),
                    worker: RuntimeWorkerRef::new("runtime-1", "worker-other"),
                    ..first.clone()
                },
                None,
                "implicit-event",
                "implicit-operation",
                false,
            )
            .unwrap_err();
        assert!(matches!(
            implicit_reassign,
            Error::TicketAssignmentConflict(_)
        ));
        let worker_conflict = store
            .set_current_ticket_worker_assignment(
                &TicketWorkerAssignmentRecord {
                    ticket_id: "ticket-2".to_string(),
                    assignment_id: "worker-conflict".to_string(),
                    ..first.clone()
                },
                None,
                "worker-conflict-event",
                "worker-conflict-operation",
                false,
            )
            .unwrap_err();
        assert!(matches!(
            worker_conflict,
            Error::TicketAssignmentConflict(_)
        ));

        let second = TicketWorkerAssignmentRecord {
            assignment_id: "assignment-2".to_string(),
            worker: RuntimeWorkerRef::new("runtime-2", "worker-2"),
            assigned_by: "user-2".to_string(),
            assigned_at: "2026-07-32T00:00:02Z".to_string(),
            ..first.clone()
        };
        let replaced = store
            .set_current_ticket_worker_assignment(
                &second,
                Some("assignment-1"),
                "event-2",
                "operation-2",
                true,
            )
            .unwrap();
        assert_eq!(replaced.current, second);
        assert_eq!(replaced.previous, Some(first.clone()));
        let replayed_reassignment = store
            .set_current_ticket_worker_assignment(
                &second,
                Some("assignment-1"),
                "ignored-reassign-event",
                "operation-2",
                true,
            )
            .unwrap();
        assert_eq!(replayed_reassignment, replaced);
        assert_eq!(
            store
                .get_current_ticket_worker_assignment("workspace-a", "ticket-1")
                .unwrap(),
            Some(second.clone())
        );

        let stale = store
            .clear_current_ticket_worker_assignment(
                "workspace-a",
                "ticket-1",
                Some("assignment-1"),
                "unassign-operation-stale",
                "event-stale",
                "user-1",
                "2026-07-32T00:00:03Z",
            )
            .unwrap_err();
        assert!(matches!(stale, Error::TicketAssignmentConflict(_)));

        let cleared = store
            .clear_current_ticket_worker_assignment(
                "workspace-a",
                "ticket-1",
                Some("assignment-2"),
                "unassign-operation-2",
                "event-3",
                "user-2",
                "2026-07-32T00:00:03Z",
            )
            .unwrap();
        assert_eq!(cleared, Some(second.clone()));
        let retried_clear = store
            .clear_current_ticket_worker_assignment(
                "workspace-a",
                "ticket-1",
                Some("assignment-2"),
                "unassign-operation-2",
                "ignored-clear-event",
                "user-2",
                "2026-07-32T00:00:04Z",
            )
            .unwrap();
        assert_eq!(retried_clear, Some(second));
        store
            .reserve_ticket_assignment_operation(
                "workspace-a",
                "reserved-operation",
                "ticket-3",
                "runtime-3",
                None,
                "sha256:reserved",
                "2026-07-32T00:00:05Z",
            )
            .unwrap();
        drop(store);
        let store = SqliteWorkspaceStore::open_for_test(&db).unwrap();
        let pending = store
            .get_ticket_assignment_operation("workspace-a", "reserved-operation")
            .unwrap()
            .unwrap();
        assert_eq!(pending.worker, None);
        assert_eq!(
            pending.request_fingerprint.as_deref(),
            Some("sha256:reserved")
        );
        store
            .bind_ticket_assignment_operation_worker(
                "workspace-a",
                "reserved-operation",
                "worker-3",
            )
            .unwrap();
        let reserved_assignment = TicketWorkerAssignmentRecord {
            workspace_id: "workspace-a".to_string(),
            ticket_id: "ticket-3".to_string(),
            assignment_id: "assignment-3".to_string(),
            worker: RuntimeWorkerRef::new("runtime-3", "worker-3"),
            assigned_by: "runtime".to_string(),
            assigned_at: "2026-07-32T00:00:06Z".to_string(),
        };
        let completed_reservation = store
            .set_current_ticket_worker_assignment(
                &reserved_assignment,
                None,
                "reserved-event",
                "reserved-operation",
                false,
            )
            .unwrap();
        assert_eq!(completed_reservation.current, reserved_assignment);
        assert_eq!(
            store
                .get_ticket_assignment_operation("workspace-a", "reserved-operation")
                .unwrap()
                .and_then(|operation| operation.assignment_id),
            Some("assignment-3".to_string())
        );
        assert_eq!(
            store
                .get_current_ticket_worker_assignment("workspace-a", "ticket-1")
                .unwrap(),
            None
        );
        // A committed receipt is not rollbackable evidence. Compensation is a
        // new unassign operation and preserves the original identity/audit.
        assert!(
            store
                .rollback_ticket_assignment_operation("workspace-a", "reserved-operation")
                .is_err()
        );
        assert_eq!(
            store
                .get_ticket_assignment_operation("workspace-a", "reserved-operation")
                .unwrap()
                .and_then(|operation| operation.assignment_id),
            Some("assignment-3".into())
        );
        assert_eq!(
            store
                .get_current_ticket_worker_assignment("workspace-a", "ticket-3")
                .unwrap(),
            Some(reserved_assignment.clone())
        );
        assert_eq!(
            store
                .clear_current_ticket_worker_assignment(
                    "workspace-a",
                    "ticket-3",
                    Some("assignment-3"),
                    "compensate-reserved-operation",
                    "compensation-event",
                    "user-1",
                    "2026-07-32T00:00:04Z"
                )
                .unwrap(),
            Some(reserved_assignment)
        );
        assert!(
            store
                .get_current_ticket_worker_assignment("workspace-a", "ticket-3")
                .unwrap()
                .is_none()
        );
        assert_eq!(
            store
                .list_ticket_worker_assignment_events("workspace-a", "ticket-3", 10)
                .unwrap()
                .iter()
                .map(|event| event.action.as_str())
                .collect::<BTreeSet<_>>(),
            BTreeSet::from(["unassigned", "assigned"])
        );
        assert!(
            store
                .rollback_ticket_assignment_operation("workspace-a", "reserved-operation")
                .is_err()
        );

        let events = store
            .list_ticket_worker_assignment_events("workspace-a", "ticket-1", 10)
            .unwrap();
        assert_eq!(
            events
                .iter()
                .map(|event| event.action.as_str())
                .collect::<Vec<_>>(),
            vec!["unassigned", "reassigned", "assigned"]
        );
        assert_eq!(events[1].assignment_id.as_deref(), Some("assignment-2"));
        assert_eq!(
            events[1].previous_assignment_id.as_deref(),
            Some("assignment-1")
        );
    }

    #[tokio::test]
    async fn role_assignment_routes_and_manual_start_are_state_fenced_atomically() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("workspace.db");
        let store = SqliteWorkspaceStore::open_api_fixture(&db_path).unwrap();
        store
            .upsert_workspace(&WorkspaceRecord {
                workspace_id: "workspace-role".to_string(),
                display_name: "Role Workspace".to_string(),
                state: "active".to_string(),
                owner_account_id: "owner-account".to_string(),
                created_at: "2026-09-01T00:00:00Z".to_string(),
                updated_at: "2026-09-01T00:00:00Z".to_string(),
            })
            .await
            .unwrap();
        store
            .upsert_repository(&RepositoryRecord {
                workspace_id: "workspace-role".to_string(),
                repository_id: "main".to_string(),
                repository_key: "main".to_string(),
                kind: "git".to_string(),
                provider: Some("git".to_string()),
                source: RepositorySource {
                    kind: server_api::RepositorySourceKind::File,
                    uri: "file:///tmp/main".to_string(),
                },
                default_ref: Some("develop".to_string()),

                source_fingerprint: "sha256:test".to_string(),
                observed_status: RepositoryObservedStatus::Unverified,
                observed_at: None,
                created_at: "2026-09-01T00:00:00Z".to_string(),
                updated_at: "2026-09-01T00:00:00Z".to_string(),
            })
            .unwrap();
        let worker = WorkerRegistryRecord {
            workspace_id: "workspace-role".to_string(),
            worker: RuntimeWorkerRef::new("runtime-role", "worker-role"),
            display_name: "Coder".to_string(),
            profile: Some("builtin:coder".to_string()),
            retention_state: "normal".to_string(),
            transcript_ref: None,
            session_ref: None,
            summary_ref: None,
            diagnostics_ref: None,
            created_at: "2026-09-01T00:00:00Z".to_string(),
            updated_at: "2026-09-01T00:00:00Z".to_string(),
        };
        store.upsert_worker_registry(&worker).unwrap();
        let backend =
            ticket::SqliteTicketBackend::open_verified(&db_path, "workspace-role").unwrap();
        let mut input = ticket::NewTicket::new("Role assignment");
        input.body = ticket::MarkdownText::new("test");
        input.workflow_state = Some(ticket::TicketState::Open);
        input.targets = vec![ticket::TicketTarget {
            repository_key: "main".to_string(),
            ref_selector: Some("develop".to_string()),
            access: ticket::TicketTargetAccess::ReadWrite,
        }];
        let ticket = ticket::TicketBackend::create(&backend, input).unwrap();

        let orchestrator = TicketRoleAssignmentRecord {
            workspace_id: "workspace-role".to_string(),
            ticket_id: ticket.id.clone(),
            assignment_id: "orchestrator-1".to_string(),
            role: TicketAssignmentRole::Orchestrator,
            principal: TicketAssignmentPrincipal::Subject {
                subject_id: "fixture-subject".to_string(),
            },
            assigned_by: "user".to_string(),
            assigned_at: "2026-09-01T00:00:00Z".to_string(),
        };
        store
            .set_current_ticket_role_assignment(
                &orchestrator,
                None,
                "event-orchestrator",
                "op-orchestrator",
                false,
            )
            .unwrap();
        assert_eq!(
            store
                .list_current_ticket_role_assignments("workspace-role", &ticket.id)
                .unwrap(),
            vec![orchestrator.clone()]
        );

        let replacement = TicketRoleAssignmentRecord {
            assignment_id: "orchestrator-2".to_string(),
            assigned_at: "2026-09-01T00:00:30Z".to_string(),
            ..orchestrator.clone()
        };
        store
            .set_current_ticket_role_assignment(
                &replacement,
                Some("orchestrator-1"),
                "event-orchestrator-reassign",
                "op-orchestrator-reassign",
                true,
            )
            .unwrap();
        assert_eq!(
            store
                .list_current_ticket_role_assignments("workspace-role", &ticket.id)
                .unwrap(),
            vec![replacement]
        );

        let coder = TicketRoleAssignmentRecord {
            workspace_id: "workspace-role".to_string(),
            ticket_id: ticket.id.clone(),
            assignment_id: "coder-manual-1".to_string(),
            role: TicketAssignmentRole::Worker,
            principal: TicketAssignmentPrincipal::Worker {
                runtime_id: "runtime-role".to_string(),
                worker_id: "worker-role".to_string(),
            },
            assigned_by: "user".to_string(),
            assigned_at: "2026-09-01T00:01:00Z".to_string(),
        };
        assert_eq!(
            ticket::TicketBackend::show(&backend, ticket.id.clone().into())
                .unwrap()
                .meta
                .workflow_state,
            ticket::TicketState::Open
        );
        assert!(
            store
                .clear_current_ticket_role_assignment(
                    "workspace-role",
                    &ticket.id,
                    TicketAssignmentRole::Orchestrator,
                    "orchestrator-2",
                    "event-clear-orchestrator",
                    "op-clear-orchestrator",
                    "user",
                    "2026-09-01T00:02:00Z",
                    Some("manual start"),
                )
                .unwrap()
        );
        let started = store
            .start_ticket_with_worker_assignment(&coder, "event-coder", "op-coder", None)
            .unwrap();
        assert_eq!(started, coder);
        let replay_input = TicketRoleAssignmentRecord {
            assignment_id: "coder-regenerated-result".to_string(),
            assigned_at: "2026-09-01T00:01:59Z".to_string(),
            ..coder.clone()
        };
        let replayed = store
            .start_ticket_with_worker_assignment(
                &replay_input,
                "event-coder-regenerated",
                "op-coder",
                None,
            )
            .unwrap();
        assert_eq!(replayed, coder);
        let ticket = ticket::TicketBackend::show(&backend, ticket.id.clone().into()).unwrap();
        assert_eq!(ticket.meta.workflow_state, ticket::TicketState::Open);
        assert_eq!(
            ticket
                .events
                .last()
                .and_then(|event| event.attributes.get("assignment_id"))
                .map(String::as_str),
            Some("coder-manual-1")
        );
        assert_eq!(
            store
                .get_current_ticket_role_assignment(
                    "workspace-role",
                    &ticket.meta.id,
                    TicketAssignmentRole::Worker,
                )
                .unwrap(),
            Some(coder.clone())
        );
        assert!(
            store
                .delete_worker_registry("workspace-role", &worker.worker)
                .is_err(),
            "active role assignment must prevent Worker removal"
        );
        assert!(
            store
                .cancel_current_ticket_worker_assignment(
                    "workspace-role",
                    &ticket.meta.id,
                    "coder-manual-1",
                    "event-cancel-coder",
                    "event-cancel-state",
                    "op-cancel-coder",
                    "user",
                    "2026-09-01T00:03:00Z",
                    "implementation needs to be redone",
                )
                .unwrap()
        );
        assert!(
            store
                .cancel_current_ticket_worker_assignment(
                    "workspace-role",
                    &ticket.meta.id,
                    "coder-manual-1",
                    "event-cancel-coder-replay",
                    "event-cancel-state-replay",
                    "op-cancel-coder",
                    "user",
                    "2026-09-01T00:03:30Z",
                    "implementation needs to be redone",
                )
                .unwrap(),
            "same operation must be idempotent after the assignment is cleared"
        );
        let cancelled_ticket =
            ticket::TicketBackend::show(&backend, ticket.meta.id.clone().into()).unwrap();
        assert_eq!(
            cancelled_ticket.meta.workflow_state,
            ticket::TicketState::Open
        );
        assert_eq!(
            cancelled_ticket
                .events
                .last()
                .and_then(|event| event.attributes.get("assignment_id"))
                .map(String::as_str),
            Some("coder-manual-1")
        );
        assert!(
            store
                .get_current_ticket_role_assignment(
                    "workspace-role",
                    &ticket.meta.id,
                    TicketAssignmentRole::Worker,
                )
                .unwrap()
                .is_none()
        );
        assert!(
            !store
                .delete_worker_registry("workspace-role", &worker.worker)
                .unwrap()
                .changes
                .is_empty()
        );
        let removed_worker_assignment = TicketRoleAssignmentRecord {
            assignment_id: "contributor-removed-worker".to_string(),
            role: TicketAssignmentRole::Contributor,
            assigned_at: "2026-09-01T00:04:00Z".to_string(),
            ..coder
        };
        assert!(
            store
                .set_current_ticket_role_assignment(
                    &removed_worker_assignment,
                    None,
                    "event-removed-worker",
                    "op-removed-worker",
                    false,
                )
                .is_err(),
            "removed/tombstoned Worker cannot become a new role principal"
        );
    }

    #[test]
    fn server_refuses_a_database_from_a_newer_schema_generation() {
        let conn = Connection::open_in_memory().unwrap();
        configure_sqlite(&conn).unwrap();
        let future_version = LATEST_SCHEMA_VERSION + 1;
        conn.execute(
            "INSERT INTO __yoi_schema_migrations (version, name) VALUES (?1, 'future')",
            params![future_version],
        )
        .unwrap();

        let error = apply_migrations(&conn).unwrap_err().to_string();
        assert!(
            error.contains(&format!("schema version {future_version} is newer")),
            "{error}"
        );
        assert!(error.contains("refusing to serve"), "{error}");
    }

    #[test]
    fn startup_rejects_missing_workspace_resource_constraint_trigger() {
        let temp = tempfile::tempdir().unwrap();
        let path = temp.path().join("server.db");
        let store = SqliteWorkspaceStore::open_for_test(&path).unwrap();
        store
            .with_conn(|conn| {
                conn.execute_batch("DROP TRIGGER ticket_worker_assignments_validate_insert")?;
                Ok(())
            })
            .unwrap();
        drop(store);

        let error = match SqliteWorkspaceStore::open_for_test(&path) {
            Ok(_) => panic!("missing assignment constraint trigger must fail closed"),
            Err(error) => error,
        };
        assert!(
            error
                .to_string()
                .contains("ticket_worker_assignments_validate_insert"),
            "{error}"
        );
    }

