    #[tokio::test]
    async fn backend_job_input_migration_preserves_original_identity_and_rolls_back_failure() {
        use crate::backend_job::{JobInputDisposition, JobInputRetirementReason};
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("migration.sqlite");
        // Build the actual retained boundary, never latest DDL relabelled as 102.
        prepare_retained_schema(&path, 102);
        let conn = Connection::open(&path).unwrap();
        configure_sqlite(&conn).unwrap();
        // Obtain a canonical pending Job through the current API, then copy only
        // columns that existed at the retained boundary into the historical file.
        let store = SqliteWorkspaceStore::in_memory_fixture().unwrap();
        seed_resource_job_workspace(&store).await;
        let original = resource_job_request("upgrade", "subject", "candidate");
        let before = store
            .reserve_backend_job("resource-workspace", &original, RESOURCE_JOB_NOW)
            .unwrap();
        for table in [
            "accounts",
            "workspaces",
            "backend_jobs",
            "backend_job_attempts",
        ] {
            let columns = conn
                .prepare(&format!("PRAGMA table_info({table})"))
                .unwrap()
                .query_map([], |row| row.get::<_, String>(1))
                .unwrap()
                .collect::<rusqlite::Result<Vec<_>>>()
                .unwrap();
            let names = columns.join(",");
            let rows = store
                .with_conn(|source| {
                    Ok(fixture_query_rows(
                        source,
                        &format!("SELECT {names} FROM {table}"),
                    ))
                })
                .unwrap();
            let placeholders = vec!["?"; columns.len()].join(",");
            for row in rows {
                conn.execute(
                    &format!("INSERT INTO {table} ({names}) VALUES ({placeholders})"),
                    rusqlite::params_from_iter(row),
                )
                .unwrap();
            }
        }
        drop(store);
        assert_eq!(current_schema_version(&conn).unwrap(), 102);
        verify_schema_history(&conn, 102).unwrap();
        assert!(!column_exists(&conn, "backend_jobs", "input_disposition").unwrap());
        conn.execute_batch("CREATE TRIGGER backend_job_input_retirement BEFORE UPDATE ON backend_job_attempts BEGIN SELECT RAISE(ABORT,'collision'); END;").unwrap();
        assert!(migrate_job_input_retention_v102_to_v103(&conn).is_err());
        assert_eq!(current_schema_version(&conn).unwrap(), 102);
        assert!(!column_exists(&conn, "backend_jobs", "input_disposition").unwrap());
        conn.execute_batch("DROP TRIGGER backend_job_input_retirement")
            .unwrap();
        migrate_job_input_retention_v102_to_v103(&conn).unwrap();
        drop(conn);
        let reopened = SqliteWorkspaceStore::open_for_test(&path).unwrap();
        assert_eq!(
            reopened
                .get_backend_job("resource-workspace", "upgrade")
                .unwrap()
                .unwrap(),
            before.job
        );
        let erased = reopened
            .reclaim_backend_job_input(
                "resource-workspace",
                "upgrade",
                &before.job.input_digest,
                JobInputRetirementReason::ExplicitErasure,
            )
            .unwrap();
        assert_eq!(erased.input_disposition, JobInputDisposition::Erased);
        assert_eq!(erased.state, BackendJobState::Pending);
        assert_eq!(
            reopened
                .reserve_backend_job("resource-workspace", &original, RESOURCE_JOB_NOW)
                .unwrap()
                .job,
            erased
        );
    }

    #[tokio::test]
    async fn backend_job_resource_reserve_converges_across_connections_without_changing_input() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("resource-jobs.sqlite");
        let store = SqliteWorkspaceStore::open_api_fixture(&path).unwrap();
        seed_resource_job_workspace(&store).await;
        let other = SqliteWorkspaceStore::open_for_test(&path).unwrap();
        let requests = [
            resource_job_request("first", "subject-a", "candidate-1"),
            resource_job_request("followup", "subject-a", "candidate-2"),
        ];
        let barrier = std::sync::Barrier::new(2);
        let reservations = std::thread::scope(|scope| {
            let a = scope.spawn(|| {
                barrier.wait();
                store
                    .reserve_backend_job("resource-workspace", &requests[0], RESOURCE_JOB_NOW)
                    .unwrap()
            });
            let b = scope.spawn(|| {
                barrier.wait();
                other
                    .reserve_backend_job("resource-workspace", &requests[1], RESOURCE_JOB_NOW)
                    .unwrap()
            });
            [a.join().unwrap(), b.join().unwrap()]
        });
        assert_eq!(reservations.iter().filter(|r| r.resource_reused).count(), 1);
        assert!(reservations.iter().all(|r| !r.replayed));
        assert_eq!(reservations[0].job.request, reservations[1].job.request);
        let original = &reservations[0];
        let deferred = requests
            .iter()
            .find(|r| r.job_id != original.job.request.job_id)
            .unwrap();
        assert!(
            store
                .get_backend_job("resource-workspace", &deferred.job_id)
                .unwrap()
                .is_none()
        );
        let replay = other
            .reserve_backend_job(
                "resource-workspace",
                &original.job.request,
                RESOURCE_JOB_NOW,
            )
            .unwrap();
        assert!(replay.replayed && !replay.resource_reused);
        let mut changed = original.job.request.clone();
        changed.input = serde_json::json!({"changed": true});
        assert!(
            other
                .reserve_backend_job("resource-workspace", &changed, RESOURCE_JOB_NOW)
                .is_err()
        );
        assert_eq!(
            store
                .find_active_backend_job_for_resource(
                    "resource-workspace",
                    &original.job.request.resource_key().unwrap()
                )
                .unwrap()
                .unwrap()
                .request,
            original.job.request
        );
        // A separate subject does not collide.
        assert!(
            !store
                .reserve_backend_job(
                    "resource-workspace",
                    &resource_job_request("other", "subject-b", "candidate-3"),
                    RESOURCE_JOB_NOW
                )
                .unwrap()
                .resource_reused
        );
        store
            .finish_backend_job_attempt(
                "resource-workspace",
                &original.job.request.job_id,
                &original.attempt.attempt_id,
                BackendJobAttemptState::Failed,
                "not_started",
                "no Worker allocated",
                RESOURCE_JOB_NOW,
            )
            .unwrap();
        let followup = other
            .reserve_backend_job("resource-workspace", deferred, RESOURCE_JOB_NOW)
            .unwrap();
        assert!(!followup.replayed && !followup.resource_reused);
        assert_eq!(&followup.job.request, deferred);
        assert_ne!(
            followup.job.intent_fingerprint,
            original.job.intent_fingerprint
        );
        assert_eq!(
            store
                .get_backend_job("resource-workspace", &original.job.request.job_id)
                .unwrap()
                .unwrap()
                .request,
            original.job.request
        );
        assert!(
            store
                .reserve_backend_job_retry(
                    "resource-workspace",
                    &original.job.request.job_id,
                    RESOURCE_JOB_NOW
                )
                .is_err(),
            "retry cannot displace a followup that reserved the same resource"
        );
    }

    #[tokio::test]
    async fn backend_job_resource_retry_and_unknown_are_fenced_by_durable_cleanup() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("cleanup-jobs.sqlite");
        let store = SqliteWorkspaceStore::open_api_fixture(&path).unwrap();
        seed_resource_job_workspace(&store).await;
        let request = resource_job_request("failed", "subject-a", "candidate-1");
        let first = store
            .reserve_backend_job("resource-workspace", &request, RESOURCE_JOB_NOW)
            .unwrap();
        let worker = bind_resource_job_worker(&store, &first, "failed-worker");
        assert_eq!(
            store
                .get_active_backend_job_for_worker("resource-workspace", &worker)
                .unwrap()
                .unwrap()
                .request
                .grants,
            request.grants
        );
        assert!(
            store
                .get_active_backend_job_for_worker("other-workspace", &worker)
                .unwrap()
                .is_none()
        );
        store
            .finish_backend_job_attempt(
                "resource-workspace",
                &request.job_id,
                &first.attempt.attempt_id,
                BackendJobAttemptState::Failed,
                "definite_failure",
                "known failed",
                RESOURCE_JOB_NOW,
            )
            .unwrap();
        assert!(
            store
                .get_active_backend_job_for_worker("resource-workspace", &worker)
                .unwrap()
                .is_none()
        );
        let deferred = resource_job_request("later", "subject-a", "candidate-2");
        for cleanup_state in [
            BackendJobWorkerCleanupState::Pending,
            BackendJobWorkerCleanupState::Executing,
            BackendJobWorkerCleanupState::Failed,
        ] {
            assert!(
                store
                    .reserve_backend_job_retry(
                        "resource-workspace",
                        &request.job_id,
                        RESOURCE_JOB_NOW
                    )
                    .is_err()
            );
            let reused = store
                .reserve_backend_job("resource-workspace", &deferred, RESOURCE_JOB_NOW)
                .unwrap();
            assert!(reused.resource_reused && !reused.replayed);
            assert_eq!(reused.job.request, request);
            match cleanup_state {
                BackendJobWorkerCleanupState::Pending => {
                    store
                        .claim_backend_job_worker_cleanup(
                            "resource-workspace",
                            &request.job_id,
                            &first.attempt.attempt_id,
                            RESOURCE_JOB_NOW,
                        )
                        .unwrap();
                }
                BackendJobWorkerCleanupState::Executing => {
                    store
                        .finish_backend_job_worker_cleanup(
                            "resource-workspace",
                            &request.job_id,
                            &first.attempt.attempt_id,
                            BackendJobWorkerCleanupState::Failed,
                            Some("cleanup_failed"),
                            Some("Worker still exists"),
                            RESOURCE_JOB_NOW,
                        )
                        .unwrap();
                }
                _ => {}
            }
        }
        finish_resource_job_cleanup(&store, &first);
        let second = store
            .reserve_backend_job_retry("resource-workspace", &request.job_id, RESOURCE_JOB_NOW)
            .unwrap();
        assert_eq!(second.job.request, request);
        assert_eq!(second.attempt.attempt, 2);
        bind_resource_job_worker(&store, &second, "unknown-worker");
        store
            .finish_backend_job_attempt(
                "resource-workspace",
                &request.job_id,
                &second.attempt.attempt_id,
                BackendJobAttemptState::Unknown,
                "unknown_effects",
                "domain outcome unknown",
                RESOURCE_JOB_NOW,
            )
            .unwrap();
        finish_resource_job_cleanup(&store, &second);
        drop(store);
        let restarted = SqliteWorkspaceStore::open_for_test(&path).unwrap();
        let active = restarted
            .find_active_backend_job_for_resource(
                "resource-workspace",
                &request.resource_key().unwrap(),
            )
            .unwrap()
            .unwrap();
        assert_eq!(active.state, BackendJobState::Unknown);
        assert_eq!(active.request, request);
        assert!(
            restarted
                .reserve_backend_job("resource-workspace", &deferred, RESOURCE_JOB_NOW)
                .unwrap()
                .resource_reused,
            "Worker removal must not resolve unknown domain effects"
        );
        assert!(
            restarted
                .reserve_backend_job_retry("resource-workspace", &request.job_id, RESOURCE_JOB_NOW)
                .is_err()
        );
    }

